cat > src/lang/turtle.ts <<'EOF'
import type { Vec3 } from "./types";

export interface Turtle {
  position: Vec3;
  heading: Vec3;
  right: Vec3;
  up: Vec3;
}

export function initialTurtle(): Turtle {
  return { position: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1] };
}

/** Cosine and sine of an angle in degrees; exact on multiples of 90. */
function cosSin(degrees: number): [number, number] {
  const turns = degrees / 90;
  if (Number.isInteger(turns)) {
    const q = ((turns % 4) + 4) % 4;
    return [[1, 0, -1, 0][q]!, [0, 1, 0, -1][q]!];
  }
  const r = (degrees * Math.PI) / 180;
  return [Math.cos(r), Math.sin(r)];
}

/** Rotates vector `a` towards vector `b` (orthonormal pair) by `degrees`; returns the new pair. */
function rotatePair(a: Vec3, b: Vec3, degrees: number): [Vec3, Vec3] {
  const [c, s] = cosSin(degrees);
  const na: Vec3 = [a[0] * c + b[0] * s, a[1] * c + b[1] * s, a[2] * c + b[2] * s];
  const nb: Vec3 = [b[0] * c - a[0] * s, b[1] * c - a[1] * s, b[2] * c - a[2] * s];
  return [na, nb];
}

/** Turns right (clockwise seen from above) around the up vector. */
export function turnRight(t: Turtle, degrees: number): void {
  const [heading, right] = rotatePair(t.heading, t.right, degrees);
  t.heading = heading;
  t.right = right;
}

export function advance(t: Turtle, distance: number): Vec3 {
  return [
    t.position[0] + t.heading[0] * distance,
    t.position[1] + t.heading[1] * distance,
    t.position[2] + t.heading[2] * distance,
  ];
}
EOF
cat > src/lang/lexer.ts <<'EOF'
export type TokenKind = "word" | "number";

export interface Token {
  kind: TokenKind;
  text: string;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const re = /\S+/g;
  const lineStarts = [0];
  for (let i = 0; i < source.length; i++) if (source[i] === "\n") lineStarts.push(i + 1);
  let match: RegExpExecArray | null;
  while ((match = re.exec(source))) {
    let line = lineStarts.length;
    while (lineStarts[line - 1]! > match.index) line--;
    tokens.push({
      kind: /^\d/.test(match[0]) ? "number" : "word",
      text: match[0],
      line,
      column: match.index - lineStarts[line - 1]! + 1,
    });
  }
  return tokens;
}
EOF
cat > src/lang/index.ts <<'EOF'
import { tokenize } from "./lexer";
import { advance, initialTurtle, turnRight } from "./turtle";
import type { Mode, RunResult, Segment } from "./types";

export type { Mode, RunResult, RunError, Segment, Vec3 } from "./types";

export function run(source: string, _mode: Mode): RunResult {
  const tokens = tokenize(source);
  const turtle = initialTurtle();
  const segments: Segment[] = [];
  for (let i = 0; i < tokens.length; i += 2) {
    const command = tokens[i]!.text;
    const amount = Number(tokens[i + 1]!.text);
    if (command === "np") {
      const to = advance(turtle, amount);
      segments.push({ from: turtle.position, to, color: "#16866a", width: 3 });
      turtle.position = to;
    } else if (command === "pw") {
      turnRight(turtle, amount);
    }
  }
  return { segments, error: null };
}
EOF
