import type { Token } from "./lexer";
import type { CommandId } from "./vocabulary";

export type Position = { line: number; column: number };

/** Every expression remembers the token it starts at: errors about an argument point there. */
export type Expr =
  | { type: "number"; value: number; at: Token }
  | { type: "group"; inner: Expr; at: Token }
  | { type: "unary"; op: "-" | "+"; operand: Expr; at: Token }
  | { type: "binary"; op: "+" | "-" | "*" | "/"; left: Expr; right: Expr; at: Token };

export type Statement =
  | { type: "command"; command: CommandId; arg?: Expr; color?: string; at: Token };

export interface Program {
  body: Statement[];
}
