export type TokenKind = "word" | "number" | "string" | "op" | "lparen" | "rparen";

export interface Token {
  kind: TokenKind;
  text: string;
  line: number;
  column: number;
  /** Whitespace (or the start of the file) directly before the token. */
  spaceBefore: boolean;
  /** Whitespace, a comment or the end of the file directly after the token. */
  spaceAfter: boolean;
}

const WORD_CHAR = /[\p{L}\p{N}_]/u;
const NUMBER = /^(?:\d+(?:\.\d+)?|\.\d+)/;

/** Splits source into positioned tokens; whitespace and `;` comments are skipped. */
export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  let lineStart = 0;
  let i = 0;
  const isSpace = (index: number) => index < 0 || index >= source.length || /[\s;]/.test(source[index]!);
  const push = (kind: TokenKind, start: number, end: number) => {
    tokens.push({
      kind,
      text: source.slice(start, end),
      line,
      column: start - lineStart + 1,
      spaceBefore: isSpace(start - 1),
      spaceAfter: isSpace(end),
    });
  };
  while (i < source.length) {
    const ch = source[i]!;
    if (ch === "\n") {
      line++;
      i++;
      lineStart = i;
    } else if (/\s/.test(ch)) {
      i++;
    } else if (ch === ";") {
      while (i < source.length && source[i] !== "\n") i++;
    } else if (ch === '"') {
      const start = i++;
      while (i < source.length && source[i] !== '"' && source[i] !== "\n") i++;
      if (source[i] === '"') i++;
      push("string", start, i);
    } else if ("+-*/".includes(ch)) {
      push("op", i, i + 1);
      i++;
    } else if (ch === "(" || ch === ")") {
      push(ch === "(" ? "lparen" : "rparen", i, i + 1);
      i++;
    } else if (/[\d.]/.test(ch)) {
      const match = NUMBER.exec(source.slice(i));
      const length = match ? match[0].length : 1;
      push("number", i, i + length);
      i += length;
    } else {
      const start = i;
      while (i < source.length && WORD_CHAR.test(source[i]!)) i++;
      if (i === start) i++;
      push("word", start, i);
    }
  }
  return tokens;
}
