import type { Expr, Program, Statement } from "./ast";
import { LangError } from "./errors";
import { tokenize, type Token } from "./lexer";
import { argumentOf, commandFor } from "./vocabulary";

const COLOR_MESSAGE =
  'Niepoprawny kolor: oczekiwano sześciu cyfr szesnastkowych w cudzysłowie, np. "#16866a".';
const WIDTH_MESSAGE = "Grubość musi być liczbą całkowitą od 1 do 12.";

class Parser {
  private pos = 0;
  constructor(private readonly tokens: Token[]) {}

  parseProgram(): Program {
    const body: Statement[] = [];
    while (this.pos < this.tokens.length) body.push(this.parseStatement());
    return { body };
  }

  private parseStatement(): Statement {
    const token = this.tokens[this.pos++]!;
    const command = token.kind === "word" ? commandFor(token.text) : undefined;
    if (!command) throw new LangError(`Nieznane polecenie „${token.text}”.`, token);
    const kind = argumentOf(command);
    if (kind === "color") {
      const arg = this.tokens[this.pos++] ?? token;
      if (arg.kind !== "string" || !/^"#[0-9a-fA-F]{6}"$/.test(arg.text)) {
        throw new LangError(COLOR_MESSAGE, arg);
      }
      return { type: "command", command, color: arg.text.slice(1, -1).toLowerCase(), at: token };
    }
    if (kind === "none") return { type: "command", command, at: token };
    const arg = this.parseExpression(token);
    if (kind === "width") {
      const value = arg.type === "number" ? arg.value : NaN;
      if (!(Number.isInteger(value) && value >= 1 && value <= 12)) {
        throw new LangError(WIDTH_MESSAGE, arg.at);
      }
    }
    return { type: "command", command, arg, at: token };
  }

  private parseExpression(owner: Token): Expr {
    let left = this.parseTerm(owner);
    while (this.isOperator("+", "-")) {
      const op = this.tokens[this.pos++]!;
      left = { type: "binary", op: op.text as "+" | "-", left, right: this.parseTerm(op), at: left.at };
    }
    return left;
  }

  private parseTerm(owner: Token): Expr {
    let left = this.parseOperand(owner);
    while (this.isOperator("*", "/")) {
      const op = this.tokens[this.pos++]!;
      left = { type: "binary", op: op.text as "*" | "/", left, right: this.parseOperand(op), at: left.at };
    }
    return left;
  }

  private parseOperand(owner: Token): Expr {
    const token = this.tokens[this.pos++] ?? owner;
    if (token.kind === "number") return { type: "number", value: Number(token.text), at: token };
    throw new LangError(`Oczekiwano wartości, a znaleziono „${token.text}”.`, token);
  }

  private isOperator(...ops: string[]): boolean {
    const token = this.tokens[this.pos];
    return token !== undefined && token.kind === "op" && ops.includes(token.text);
  }
}

export function parse(source: string): Program {
  return new Parser(tokenize(source)).parseProgram();
}
