describe("interpreter: variables", () => {
  test("niech assigns and reassigns; names ignore case and may be written :name", () => {
    expect(ahead("niech bok 40 niech bok bok * 2 np BOK + :Bok")).toBe(160);
    expect(ahead("LET x 3 np :x")).toBe(3);
  });

  test("a name that is never assigned anywhere is a parse-time error at that name", () => {
    const { segments, error } = run("np 5\nniech a 1\nnp a + b", "2d");
    expect(segments).toEqual([]);
    expect(error).toEqual({ message: "Nieznana nazwa „b”: nie jest zmienną ani parametrem.", line: 3, column: 8 });
  });

  test("a variable assigned later at top level is declared, but reading it early is a run-time error", () => {
    const { segments, error } = run("np 5\nnp 2 * x\nniech x 3", "2d");
    expect(error).toEqual({ message: "Zmienna „x” nie ma jeszcze wartości.", line: 2, column: 4 });
    expect(segments).toHaveLength(1);
  });

  test("a command word cannot be used as a variable name or as a value", () => {
    expect(run("niech np 5", "2d").error).toEqual({
      message: "„np” jest nazwą polecenia i nie może być nazwą zmiennej.",
      line: 1,
      column: 7,
    });
    expect(run("niech a 1 np a + pw", "2d").error).toEqual({
      message: "„pw” jest nazwą polecenia i nie może być użyte jako wartość.",
      line: 1,
      column: 17,
    });
  });
});
