describe("interpreter: nrpowt", () => {
  test("is the 1-based number of the current iteration of the innermost enclosing repeat", () => {
    const { segments } = run("powtorz 3 [np nrpowt]", "2d");
    expect(segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 2, 3]);
    const nested = run("powtorz 2 [powtorz 3 [np nrpowt] np nrpowt * 10]", "2d");
    expect(nested.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 2, 3, 10, 1, 2, 3, 20]);
  });

  test("repcount is an alias, and the count of an inner repeat sees the enclosing repeat", () => {
    expect(run("powtorz 3 [powtorz REPCOUNT [np 1]]", "2d").segments).toHaveLength(6);
  });

  test.each([
    ["np nrpowt", 1, 4],
    ["powtorz 2 [np 1]\nnp 1 + nrpowt", 2, 8],
    ["powtorz nrpowt [np 1]", 1, 9],
  ])("%p outside any repeat is a parse-time error", (source, line, column) => {
    const { segments, error } = run(source, "2d");
    expect(segments).toEqual([]);
    expect(error).toEqual({
      message: "„nrpowt” można użyć tylko wewnątrz powtórzenia.",
      line,
      column,
    });
  });
