    expect(run("jeśli 0.1 + 0.2 = 0.3 [np 1]", "2d").segments).toHaveLength(0);
    expect(run("jeśli 0.1 + 0.2 <> 0.3 [np 1]", "2d").segments).toHaveLength(1);
  });

