describe("interpreter: procedures", () => {
  const SQUARE = "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n";

  test("a procedure takes positional arguments and draws with them", () => {
    const { segments, error } = run(`${SQUARE}\nkwadrat 80 90`, "2d");
    expect(error).toBeNull();
    expect(segments).toHaveLength(4);
    expectPoint(segments[2]!.to, [80, 0, 0]);
    expectPoint(segments[3]!.to, [0, 0, 0]);
  });

  test("arguments are expressions separated by whitespace", () => {
    const { segments } = run(`${SQUARE}kwadrat 40 * 2 90`, "2d");
    expectPoint(segments[0]!.to, [0, 80, 0]);
    expect(run(`${SQUARE}kwadrat 80 -90`, "2d").error).toBeNull();
  });

  test("a call may come before the definition", () => {
    expect(run(`kwadrat 10 90\n${SQUARE}`, "2d").segments).toHaveLength(4);
  });

  test("legacy header with :params, to/end aliases and :name references work too", () => {
    const legacy = "TO kwadrat :bok :kąt\n  repeat 4 [fd :bok rt :KĄT]\nEND\nkwadrat 10 90";
    expect(run(legacy, "2d")).toEqual(run(`${SQUARE}kwadrat 10 90`, "2d"));
    expect(run("oto f\n np 1\njuz\nf f", "2d").segments).toHaveLength(2);
  });

  test("a parameter may share its name with a procedure: call in command position, value in argument position", () => {
    const { segments, error } = run("oto bok ma: bok\n  np bok\njuż\nbok 7", "2d");
    expect(error).toBeNull();
    expectPoint(segments[0]!.to, [0, 7, 0]);
  });
});
