    const body: Statement[] = [];
    while (this.pos < this.tokens.length) {
      const token = this.tokens[this.pos]!;
      if (token.kind === "word" && isDefineWord(token.text)) this.parseDefinition();
      else body.push(this.parseStatement());
    }
    return { body, procedures: this.procedures };
  }

  private parseDefinition(): void {
    const head = this.tokens[this.pos]!;
    const headIndex = this.pos++;
    if (!head.startsLine) {
      throw new LangError(`„${head.text}” musi stać na początku wiersza.`, head);
    }
    const name = this.tokens[this.pos];
    if (name?.kind !== "word" || name.line !== head.line) {
      throw new LangError("Po „oto” oczekiwano nazwy procedury.", name ?? head);
    }
    this.pos++;
    if (isReserved(name.text)) {
      throw new LangError(`„${name.text}” jest nazwą polecenia i nie może być nazwą procedury.`, name);
    }
    const key = nameOf(name.text);
    if (this.procedures.has(key)) {
      throw new LangError(`Procedura „${name.text}” jest już zdefiniowana.`, name);
    }
    const params = this.parseParameters(head);
    const procedure: Procedure = { name: key, params, body: [], at: head };
    this.procedures.set(key, procedure);

    this.declared = new Set([...this.scanned.globals, ...(this.scanned.locals.get(headIndex) ?? [])]);
    for (;;) {
      const token = this.tokens[this.pos];
      if (!token) throw new LangError(`Brakuje „już” kończącego procedurę „${name.text}”.`, head);
      if (token.kind === "word" && isEndWord(token.text)) {
        const next = this.tokens[this.pos + 1];
        if (!token.startsLine || (next && next.line === token.line)) {
          throw new LangError(`„${token.text}” musi stać samo w osobnym wierszu.`, token);
        }
        this.pos++;
        break;
      }
      procedure.body.push(this.parseStatement());
    }
    this.declared = this.scanned.globals;
  }

  /** The rest of the header line: `ma: a, b` or the legacy `:a :b`. */
  private parseParameters(head: Token): string[] {
    const header: Token[] = [];
    while (this.tokens[this.pos]?.line === head.line) header.push(this.tokens[this.pos++]!);
    const params: string[] = [];
    const add = (token: Token) => {
      if (token.kind !== "word") throw new LangError("Oczekiwano nazwy parametru.", token);
      const bare = token.text.replace(/^:/, "");
      if (isReserved(bare)) {
        throw new LangError(`„${bare}” jest nazwą polecenia i nie może być nazwą parametru.`, token);
      }
      if (params.includes(nameOf(token.text))) {
        throw new LangError(`Parametr „${bare}” występuje dwa razy.`, token);
      }
      params.push(nameOf(token.text));
    };
    if (header[0] && nameOf(header[0].text) === "ma" && header[1]?.kind === "colon") {
      for (let i = 2; i < header.length; i += 2) {
        add(header[i]!);
        const sep = header[i + 1];
        if (sep && sep.kind !== "comma") {
          throw new LangError("Parametry rozdziela się przecinkami.", sep);
        }
        if (sep && !header[i + 2]) throw new LangError("Po przecinku oczekiwano nazwy parametru.", sep);
      }
      if (header.length === 2) throw new LangError("Po „ma:” oczekiwano nazwy parametru.", header[1]!);
    } else {
      for (const token of header) {
        if (!token.text.startsWith(":")) {
          throw new LangError("Parametry wpisuje się po „ma:” lub w postaci :nazwa.", token);
        }
        add(token);
      }
    }
    return params;
  }
