describe("interpreter: stop, recursion and local variables", () => {
  const lengths = (source: string) =>
    run(source, "2d").segments.map((s) => Math.round(Math.hypot(...(s.to.map((c, i) => c - s.from[i]!) as number[]))));

  test("procedures may call themselves; stop ends the current call", () => {
    const source = "oto spirala ma: d\n  jeśli d < 1 [stop]\n  np d\n  pw 90\n  spirala d - 1\njuż\nspirala 3";
    expect(run(source, "2d").error).toBeNull();
    expect(lengths(source)).toEqual([3, 2, 1]);
  });

  test("at top level stop ends the program without an error", () => {
    const { segments, error } = run("np 1 stop np 2", "2d");
    expect(error).toBeNull();
    expect(segments).toHaveLength(1);
    expect(run("powtorz 5 [np 1 jeśli nrpowt = 2 [stop]] np 9", "2d").segments).toHaveLength(2);
  });

  test("a stop inside a repeat or conditional ends the enclosing procedure, not the body", () => {
    const source = "oto f\n  powtorz 5 [np 1 jeśli nrpowt = 2 [stop]]\n  np 100\njuż\nf\nnp 7";
    expect(lengths(source)).toEqual([1, 1, 7]);
  });

  test("niech inside a procedure is local to the call and shadows a global from then on", () => {
    expect(lengths("niech x 2\noto f\n  np x\n  niech x 9\n  np x\njuż\nf\nnp x")).toEqual([2, 9, 2]);
  });

  test("a local created in a procedure is gone after the call, so using it outside is a parse error", () => {
    const { segments, error } = run("oto f\n  niech y 4\n  np y\njuż\nf\nnp y", "2d");
    expect(segments).toEqual([]);
    expect(error).toEqual({ message: "Nieznana nazwa „y”: nie jest zmienną ani parametrem.", line: 6, column: 4 });
  });

  test("a parameter can be reassigned; each recursive call has its own", () => {
    expect(lengths("oto f ma: n\n  niech n n * 2\n  np n\njuż\nf 4")).toEqual([8]);
    expect(lengths("oto f ma: n\n  jeśli n > 0 [f n - 1]\n  np n\njuż\nf 3")).toEqual([0, 1, 2, 3].slice(1));
  });

  test("reading a local before it is assigned, with no global to fall back on, is a run-time error", () => {
    const { segments, error } = run("np 1\noto f\n  np y\n  niech y 3\njuż\nf", "2d");
    expect(error).toEqual({ message: "Zmienna „y” nie ma jeszcze wartości.", line: 3, column: 6 });
    expect(segments).toHaveLength(1);
  });

  test("nrpowt belongs to the repeat inside the procedure, one counter per call", () => {
    expect(lengths("oto f ma: n\n  powtorz n [np nrpowt]\njuż\npowtorz 2 [f 2]")).toEqual([1, 2, 1, 2]);
  });
});
