describe("interpreter: 3D orientation", () => {
  const end = (source: string) => {
    const { segments, error } = run(source, "3d");
    expect(error).toBeNull();
    return segments[segments.length - 1]!.to;
  };

  test("gora tilts the heading towards the up vector, dol the other way", () => {
    expectPoint(end("gora 90 np 10"), [0, 0, 10]);
    expectPoint(end("dol 90 np 10"), [0, 0, -10]);
    expectPoint(end("gora 45 np 10"), [0, 7.0710678, 7.0710678], 1e-6);
    expectPoint(end("pitchup 180 np 10"), [0, -10, 0]);
  });

  test("the up vector follows a pitch: after gora 90 the turtle's up is the former back", () => {
    // heading +Z, up -Y, right +X: turning right by 90 heads along +X
    expectPoint(end("gora 90 pw 90 np 10"), [10, 0, 0]);
    // and rolling by 90 then pitching up heads along the former right
    expectPoint(end("gora 90 pp 90 gora 90 np 10"), [0, 0, 0].map((_, i) => [0, -10, 0][i]!));
  });

  test("pp rolls the up vector towards the right vector around the heading", () => {
    // after pp 90 the up vector is the former right (+X): pitching up heads along +X
