describe("interpreter: run-time limits", () => {
  const OPS = "Przekroczono limit 10000 wykonanych operacji.";
  const FRAMES = "Przekroczono limit zagnieżdżenia wywołań i powtórzeń (32).";
  const COORD = "Współrzędna wykracza poza dozwolony zakres ±100000.";

  test("10,000 operations are allowed; a repeat costs one plus one per finished iteration", () => {
    expect(run("powtorz 4999 [pod]", "2d").error).toBeNull(); // 1 + 4999 * 2 = 9999
    expect(run("powtorz 4999 [pod] pod", "2d").error).toBeNull(); // exactly 10000
    const over = run("np 1\npowtorz 4999 [pod] pod pod", "2d");
    expect(over.error).toEqual({ message: OPS, line: 2, column: 24 });
    expect(over.segments).toHaveLength(1);
    expect(run("powtorz 5000 [pod]", "2d").error).toEqual({ message: OPS, line: 1, column: 1 });
  });

  test("a conditional costs one, plus one for a body that ran to its end", () => {
    expect(run("powtorz 4999 [jeśli 1 = 2 [pod]]", "2d").error).toBeNull(); // 1 + 4999 * 2
    expect(run("powtorz 5000 [jeśli 1 = 2 [pod]]", "2d").error?.message).toBe(OPS);
    expect(run("powtorz 2499 [jeśli 1 = 1 [pod]]", "2d").error).toBeNull(); // 1 + 2499 * 4 = 9997
    expect(run("powtorz 2500 [jeśli 1 = 1 [pod]]", "2d").error?.message).toBe(OPS);
  });

  test("a procedure call costs one, plus one when the call finishes; niech costs one", () => {
    const f = "oto f\n  pod\njuż\n";
    expect(run(`${f}powtorz 2499 [f]`, "2d").error).toBeNull(); // 1 + 2499 * 4 = 9997
    expect(run(`${f}powtorz 2500 [f]`, "2d").error?.message).toBe(OPS);
    expect(run("powtorz 4999 [niech x 1]", "2d").error).toBeNull();
    expect(run("powtorz 5000 [niech x 1]", "2d").error?.message).toBe(OPS);
  });

  test("evaluating an expression is not an operation", () => {
    const long = "np " + Array(1500).fill("1").join(" + ");
    expect(run(`${long}\n`.repeat(3), "2d").error).toBeNull();
  });

  test("32 active call and repeat frames are allowed, the 33rd is an error and keeps the drawing", () => {
    const recurse = "oto f ma: n\n  np 1\n  jeśli n > 0 [f n - 1]\njuż\n";
    expect(run(`${recurse}f 31`, "2d").error).toBeNull();
    const { segments, error } = run(`${recurse}f 32`, "2d");
    expect(error).toEqual({ message: FRAMES, line: 3, column: 15 });
    expect(segments).toHaveLength(32);
    expect(run("oto f\n  f\njuż\nf", "2d").error?.message).toBe(FRAMES);
  });

  test("repeat frames and call frames share the limit; conditional bodies are not frames", () => {
    const mixed = "oto f ma: n\n  powtorz 1 [jeśli n > 0 [f n - 1]]\njuż\n";
    expect(run(`${mixed}f 15`, "2d").error).toBeNull(); // 16 calls + 16 repeats = 32 frames
    expect(run(`${mixed}f 16`, "2d").error?.message).toBe(FRAMES);
  });

  test("a coordinate may reach ±100000 but not beyond; the offending move is not drawn", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    expect(run("ws 100000", "2d").error).toBeNull();
    expect(run("np 100001", "2d").error).toEqual({ message: COORD, line: 1, column: 1 });
    expect(run("pod ws 100001", "2d").error?.message).toBe(COORD);
    const { segments, error } = run("np 60000 pw 90 np 5 pw 90 np 60000 np 60000", "2d");
    expect(error).toEqual({ message: COORD, line: 1, column: 38 });
    expect(segments).toHaveLength(3);
    expect(run("gora 90 np 100001", "3d").error?.message).toBe(COORD);
    expect(run("gora 90 np 100000", "3d").error).toBeNull();
  });

  test("a result that is not finite is an error at the first token of the argument", () => {
    const source = "niech x 1\npowtorz 400 [niech x x * 1000]\nnp 1";
    const { segments, error } = run(source, "2d");
    expect(segments).toEqual([]);
    expect(error).toEqual({ message: "Wynik wyrażenia nie jest skończoną liczbą.", line: 2, column: 22 });
  });
});
EOF
