import type { Expr, Program, Statement } from "./ast";
import { LangError } from "./errors";
import { advance, initialTurtle, pitchUp, rollRight, turnRight, type Turtle } from "./turtle";
import type { Segment, Vec3 } from "./types";

class Fault extends Error {}

/** Evaluates an argument; any fault is reported at the argument's first token. */
function value(expr: Expr, m: Machine): number {
  try {
    return evaluate(expr, m);
  } catch (e) {
    if (e instanceof Fault) throw new LangError(e.message, expr.at);
    throw e;
  }
}

function evaluate(expr: Expr, m: Machine): number {
  switch (expr.type) {
    case "number":
      return expr.value;
    case "repcount":
      return m.frame.repeatCounters[m.frame.repeatCounters.length - 1]!;
    case "name": {
      const v = m.frame.locals.get(expr.name) ?? m.globals.get(expr.name);
      if (v === undefined) throw new Fault(`Zmienna „${expr.at.text.replace(/^:/, "")}” nie ma jeszcze wartości.`);
      return v;
    }
    case "group":
      return evaluate(expr.inner, m);
    case "unary":
      return expr.op === "-" ? -evaluate(expr.operand, m) : evaluate(expr.operand, m);
    case "binary": {
      const l = evaluate(expr.left, m);
      const r = evaluate(expr.right, m);
      if (expr.op === "/" && r === 0) throw new Fault("Dzielenie przez zero.");
      return expr.op === "+" ? l + r : expr.op === "-" ? l - r : expr.op === "*" ? l * r : l / r;
    }
  }
}

interface Frame {
  locals: Map<string, number>;
  repeatCounters: number[];
}

class Machine {
  constructor(readonly program: Program) {}
  turtle: Turtle = initialTurtle();
  segments: Segment[] = [];
  penDown = true;
  color = "#16866a";
  width = 3;
  globals = new Map<string, number>();
  frames: Frame[] = [{ locals: this.globals, repeatCounters: [] }];
  get frame(): Frame {
    return this.frames[this.frames.length - 1]!;
  }
}

/** Runs statements; returns true when a `stop` ended the enclosing call (or the program). */
function* runBlock(body: Statement[], m: Machine): Generator<void, boolean> {
  for (const statement of body) {
    if (statement.type === "repeat") {
      const count = value(statement.count, m);
      const counters = m.frame.repeatCounters;
      counters.push(0);
      for (let i = 1; i <= count; i++) {
        counters[counters.length - 1] = i;
        if (yield* runBlock(statement.body, m)) return true;
      }
      counters.pop();
      continue;
    }
    if (statement.type === "call") {
      const procedure = m.program.procedures.get(statement.name)!;
      const locals = new Map<string, number>();
      procedure.params.forEach((param, i) => locals.set(param, value(statement.args[i]!, m)));
      yield;
      m.frames.push({ locals, repeatCounters: [] });
      yield* runBlock(procedure.body, m);
      m.frames.pop();
      continue;
    }
    if (statement.type === "if") {
      const { op, left, right } = statement.condition;
      const l = value(left, m);
      const r = value(right, m);
      const holds =
        op === "<" ? l < r : op === ">" ? l > r : op === "=" ? l === r : op === "<=" ? l <= r : op === ">=" ? l >= r : l !== r;
      yield;
      const branch = holds ? statement.then : statement.otherwise;
      if (branch && (yield* runBlock(branch, m))) return true;
      continue;
    }
    if (statement.type === "let") {
      m.frame.locals.set(statement.name, value(statement.value, m));
      yield;
      continue;
    }
    const { command } = statement;
    const amount = statement.arg ? value(statement.arg, m) : 0;
    if (command === "forward" || command === "back") {
      const to = advance(m.turtle, command === "forward" ? amount : -amount);
      const moved = to.some((c, axis) => c !== m.turtle.position[axis]);
      if (m.penDown && moved) {
        m.segments.push({ from: m.turtle.position, to, color: m.color, width: m.width });
      }
      m.turtle.position = to;
    } else if (command === "right" || command === "left") {
      turnRight(m.turtle, command === "right" ? amount : -amount);
    } else if (command === "pitchup" || command === "pitchdown") {
      pitchUp(m.turtle, command === "pitchup" ? amount : -amount);
    } else if (command === "rollright" || command === "rollleft") {
      rollRight(m.turtle, command === "rollright" ? amount : -amount);
    } else if (command === "color") {
      m.color = statement.color!;
    } else if (command === "width") {
      m.width = amount;
    } else if (command === "home") {
      const origin: Vec3 = [0, 0, 0];
      const away = Math.hypot(...m.turtle.position) > 1e-9;
      if (m.penDown && away) {
        m.segments.push({ from: m.turtle.position, to: origin, color: m.color, width: m.width });
      }
      m.turtle = initialTurtle();
    } else if (command === "clear") {
      m.segments = [];
    } else if (command === "stop") {
      yield;
      return true;
    } else {
      m.penDown = command === "pendown";
    }
    yield;
  }
  return false;
}

export function execute(program: Program): { segments: Segment[]; error: LangError | null } {
  const machine = new Machine(program);
  try {
    for (const _ of runBlock(program.body, machine)) {
      // run to completion
    }
  } catch (e) {
    if (e instanceof LangError) return { segments: machine.segments, error: e };
    throw e;
  }
  return { segments: machine.segments, error: null };
}

