import type { Expr, Program, Statement } from "./ast";
import { LangError } from "./errors";
import { LIMITS } from "./limits";
import type { Token } from "./lexer";
import { advance, initialTurtle, pitchUp, rollRight, turnRight, type Turtle } from "./turtle";
import type { Segment, Vec3 } from "./types";

const MESSAGES = {
  operations: `Przekroczono limit ${LIMITS.operations} wykonanych operacji.`,
  frames: `Przekroczono limit zagnieżdżenia wywołań i powtórzeń (${LIMITS.frames}).`,
  segments: `Przekroczono limit ${LIMITS.segments} odcinków.`,
  coordinate: `Współrzędna wykracza poza dozwolony zakres ±${LIMITS.coordinate}.`,
  width: "Grubość musi być liczbą całkowitą od 1 do 12.",
  repeat: "Liczba powtórzeń musi być liczbą całkowitą od 0 do 10000.",
  divisionByZero: "Dzielenie przez zero.",
  notFinite: "Wynik wyrażenia nie jest skończoną liczbą.",
};

/** A problem found while evaluating an expression; reported at the argument's first token. */
class Fault extends Error {}

interface Frame {
  locals: Map<string, number>;
  repeatCounters: number[];
}

class Machine {
  turtle: Turtle = initialTurtle();
  segments: Segment[] = [];
  penDown = true;
  color = "#16866a";
  width = 3;
  readonly globals = new Map<string, number>();
  frames: Frame[] = [{ locals: this.globals, repeatCounters: [] }];
  /** Active call and repeat frames (the top level is not one). */
  depth = 0;
  ops = 0;

  constructor(readonly program: Program) {}

  get frame(): Frame {
    return this.frames[this.frames.length - 1]!;
  }

  /** Counts one executed operation. */
  count(at: Token): void {
    if (++this.ops > LIMITS.operations) throw new LangError(MESSAGES.operations, at);
  }

  enterFrame(at: Token): void {
    if (this.depth >= LIMITS.frames) throw new LangError(MESSAGES.frames, at);
    this.depth++;
  }

  addSegment(from: Vec3, to: Vec3, at: Token): void {
    if (this.segments.length >= LIMITS.segments) throw new LangError(MESSAGES.segments, at);
    this.segments.push({ from, to, color: this.color, width: this.width });
  }
}

function evaluate(expr: Expr, m: Machine): number {
  switch (expr.type) {
    case "number":
      return expr.value;
    case "repcount":
      return m.frame.repeatCounters[m.frame.repeatCounters.length - 1]!;
    case "name": {
      const v = m.frame.locals.get(expr.name) ?? m.globals.get(expr.name);
      if (v === undefined) throw new Fault(`Zmienna „${expr.at.text.replace(/^:/, "")}” nie ma jeszcze wartości.`);
      return v;
    }
    case "group":
      return evaluate(expr.inner, m);
    case "unary":
      return expr.op === "-" ? -evaluate(expr.operand, m) : evaluate(expr.operand, m);
    case "binary": {
      const l = evaluate(expr.left, m);
      const r = evaluate(expr.right, m);
      if (expr.op === "/" && r === 0) throw new Fault(MESSAGES.divisionByZero);
      const result = expr.op === "+" ? l + r : expr.op === "-" ? l - r : expr.op === "*" ? l * r : l / r;
      if (!Number.isFinite(result)) throw new Fault(MESSAGES.notFinite);
      return result;
    }
  }
}

/** Evaluates an argument; any fault is reported at the argument's first token. */
function value(expr: Expr, m: Machine): number {
  try {
    return evaluate(expr, m);
  } catch (e) {
    if (e instanceof Fault) throw new LangError(e.message, expr.at);
    throw e;
  }
}

function integerIn(n: number, min: number, max: number): boolean {
  return Number.isInteger(n) && n >= min && n <= max;
}

function checkCoordinates(position: Vec3, at: Token): void {
  if (position.some((c) => Math.abs(c) > LIMITS.coordinate)) {
    throw new LangError(MESSAGES.coordinate, at);
  }
}

function holds(op: string, l: number, r: number): boolean {
  switch (op) {
    case "<":
      return l < r;
    case ">":
      return l > r;
    case "=":
      return l === r;
    case "<=":
      return l <= r;
    case ">=":
      return l >= r;
    default:
      return l !== r;
  }
}

/** Runs statements; returns true when a `stop` ended the enclosing call (or the program). */
function* runBlock(body: Statement[], m: Machine): Generator<void, boolean> {
  for (const statement of body) {
    const at = statement.at;
    m.count(at);
    switch (statement.type) {
      case "repeat": {
        const times = value(statement.count, m);
        if (!integerIn(times, 0, 10_000)) throw new LangError(MESSAGES.repeat, statement.count.at);
        m.enterFrame(at);
        const counters = m.frame.repeatCounters;
        counters.push(0);
        for (let i = 1; i <= times; i++) {
          counters[counters.length - 1] = i;
          if (yield* runBlock(statement.body, m)) return true;
          m.count(at);
        }
        counters.pop();
        m.depth--;
        yield;
        break;
      }
      case "call": {
        const procedure = m.program.procedures.get(statement.name)!;
        const locals = new Map<string, number>();
        procedure.params.forEach((param, i) => locals.set(param, value(statement.args[i]!, m)));
        const depth = m.depth;
        m.enterFrame(at);
        yield;
        m.frames.push({ locals, repeatCounters: [] });
        yield* runBlock(procedure.body, m);
        m.frames.pop();
        m.depth = depth;
        m.count(at);
        break;
      }
      case "if": {
        const { op, left, right } = statement.condition;
        const taken = holds(op, value(left, m), value(right, m));
        yield;
        const branch = taken ? statement.then : statement.otherwise;
        if (branch) {
          if (yield* runBlock(branch, m)) return true;
          m.count(at);
        }
        break;
      }
      case "let":
        m.frame.locals.set(statement.name, value(statement.value, m));
        yield;
        break;
      case "command": {
        const amount = statement.arg ? value(statement.arg, m) : 0;
        if (execCommand(statement, amount, m)) {
          yield;
          return true;
        }
        yield;
        break;
      }
    }
  }
  return false;
}

/** Executes one simple command; returns true for `stop`. */
function execCommand(statement: Extract<Statement, { type: "command" }>, amount: number, m: Machine): boolean {
  const { command, at } = statement;
  switch (command) {
    case "forward":
    case "back": {
      const to = advance(m.turtle, command === "forward" ? amount : -amount);
      checkCoordinates(to, at);
      if (m.penDown && to.some((c, axis) => c !== m.turtle.position[axis])) {
        m.addSegment(m.turtle.position, to, at);
      }
      m.turtle.position = to;
      break;
    }
    case "right":
    case "left":
      turnRight(m.turtle, command === "right" ? amount : -amount);
      break;
    case "pitchup":
    case "pitchdown":
      pitchUp(m.turtle, command === "pitchup" ? amount : -amount);
      break;
    case "rollright":
    case "rollleft":
      rollRight(m.turtle, command === "rollright" ? amount : -amount);
      break;
    case "color":
      m.color = statement.color!;
      break;
