import { describe, expect, test } from "bun:test";
import { EXAMPLES, findExample } from "../src/examples";
import { run } from "../src/lang";
import { expectPoint } from "./helpers";

const length = (s: { from: number[]; to: number[] }) =>
  Math.hypot(s.to[0]! - s.from[0]!, s.to[1]! - s.from[1]!, s.to[2]! - s.from[2]!);

function drawn(id: string) {
