  const result = run(example.source, example.mode);
  expect(result.error).toBeNull();
  return result.segments;
}

describe("standard programs", () => {
  test("thirteen programs ship, with the names and modes of the brief", () => {
    expect(EXAMPLES.map((e) => [e.id, e.name, e.mode])).toEqual([
      ["kwadrat", "Kwadrat", "2d"],
      ["gwiazda", "Gwiazda", "2d"],
      ["rozeta", "Rozeta", "2d"],
      ["spirala", "Spirala", "2d"],
      ["wielokaty", "Wielokąty", "2d"],
      ["drzewo", "Drzewo", "2d"],
      ["sniezynka", "Śnieżynka", "2d"],
