      ["szescian", "Sześcian", "3d"],
      ["pierscien", "Pierścień", "3d"],
      ["kula", "Kula", "3d"],
      ["helisa", "Helisa", "3d"],
      ["drzewo3d", "Drzewo 3D", "3d"],
    ]);
  });

