    expect(findExample("Śnieżynka")?.id).toBe("sniezynka");
    expect(findExample("WIELOKĄTY")?.id).toBe("wielokaty");
    expect(findExample("drzewo 3d")?.id).toBe("drzewo3d");
    expect(findExample("nie ma takiego")).toBeUndefined();
  });

  test("sources are shipped verbatim", () => {
    expect(findExample("kwadrat")!.source).toBe(
      '; Cztery boki, cztery skręty.\nkolor "#16866a"\ngrubosc 3\npowtorz 4 [\n  np 120\n  pw 90\n]',
    );
    expect(findExample("helisa")!.source.split("\n")[0]).toBe("; Spirala wznosi się ku górze.");
    expect(findExample("drzewo")!.source).toContain("oto gałąź ma: dł\n  jeśli dł < 6 [stop]");
  });

  test("all thirteen run to the end without an error in their own mode", () => {
    for (const example of EXAMPLES) {
      const { error, segments } = run(example.source, example.mode);
      expect(error).toBeNull();
      expect(segments.length).toBeGreaterThan(0);
    }
  });

  test("kwadrat: a closed square of side 120", () => {
    const s = drawn("kwadrat");
    expect(s).toHaveLength(4);
    expect(s.every((seg) => Math.abs(length(seg) - 120) < 1e-9)).toBe(true);
    expectPoint(s[3]!.to, [0, 0, 0]);
  });

  test("gwiazda: five strokes of 180 turning 144 degrees, back at the start in the tangle's centre", () => {
    const s = drawn("gwiazda");
    expect(s).toHaveLength(5);
    expectPoint(s[4]!.to, [0, 0, 0]);
    expect(s.every((seg) => seg.color === "#c1763d")).toBe(true);
  });

  test("rozeta: twelve squares of 100", () => {
    const s = drawn("rozeta");
    expect(s).toHaveLength(48);
    expect(s.every((seg) => seg.width === 2)).toBe(true);
    expectPoint(s[47]!.to, [0, 0, 0]);
  });

  test("spirala: each of the 90 sides is 2.5 longer than the last, colours alternate", () => {
    const s = drawn("spirala");
