    expect(s.map(length).slice(0, 3)).toEqual([2.5, 5, 7.5]);
    expect(s[0]!.color).toBe("#c1763d"); // zmiana is negated before the first stroke is drawn... no: after kolor
    expect(s[1]!.color).not.toBe(s[0]!.color);
