    const s = drawn("wielokaty");
    expect(s).toHaveLength(3 + 4 + 5 + 6 + 7 + 8 + 9);
    expect(s.every((seg) => Math.abs(length(seg) - 60) < 1e-9)).toBe(true);
  });

  test("drzewo: 255 branches, thinner and greener as they shorten", () => {
    const s = drawn("drzewo");
    expect(s).toHaveLength(255);
    expectPoint(s[0]!.from, [0, -120, 0]);
    expectPoint(s[0]!.to, [0, -30, 0]);
    expect([s[0]!.color, s[0]!.width]).toEqual(["#6b4f2a", 3]);
    expect(s[s.length - 1]!.color).toBe("#2f8f4e");
