    expect(s).toHaveLength(768);
    expect(s.every((seg) => Math.abs(length(seg) - 270 / 81) < 1e-9)).toBe(true);
    expect(s.every((seg) => seg.color === "#2b6fb3" && seg.width === 1)).toBe(true);
  });

  test("schody: six steps climbing 120 in z", () => {
    const s = drawn("schody");
    expect(s).toHaveLength(12);
    expectPoint(s[11]!.to, [0, 210, 120]);
  });

  test("szescian: every vertex of the drawing is a corner of the 100-cube", () => {
    const s = drawn("szescian");
    expect(s).toHaveLength(17);
    for (const seg of s) {
      for (const p of [seg.from, seg.to]) {
        for (const c of p) expect([0, 100].some((v) => Math.abs(c - v) < 1e-9)).toBe(true);
      }
    }
  });

  test("pierscien: a closed 36-gon of side 10 tilted by 30 degrees", () => {
    const s = drawn("pierscien");
    expect(s).toHaveLength(36);
    expectPoint(s[35]!.to, [0, 0, 0]);
    expectPoint(s[0]!.to, [0, 10 * Math.cos(Math.PI / 6), 10 * Math.sin(Math.PI / 6)]);
  });

  test("kula: twelve closed circles, each returning to the origin, inside a sphere of twice the radius", () => {
    const s = drawn("kula");
    expect(s).toHaveLength(432);
    for (let circle = 0; circle < 12; circle++) expectPoint(s[circle * 36 + 35]!.to, [0, 0, 0]);
    const radius = 360 / (2 * Math.PI);
    for (const seg of s) expect(Math.hypot(...seg.to)).toBeLessThanOrEqual(2 * radius + 1e-6);
    expect(s[0]!.color).toBe("#2b6fb3");
    expect(s[36]!.color).toBe("#16866a");
  });

  test("helisa: 120 steps, five turns, rising 1.5 per step", () => {
    const s = drawn("helisa");
    expect(s).toHaveLength(240);
    expectPoint(s[239]!.to, [0, 0, 180]);
  });

  test("drzewo3d: 121 branches growing from a vertical trunk", () => {
    const s = drawn("drzewo3d");
    expect(s).toHaveLength(121);
    expectPoint(s[0]!.from, [0, 0, 0]);
    expectPoint(s[0]!.to, [0, 0, 70]);
    expect(s[0]!.color).toBe("#6b4f2a");
  });
});
