import type { Scheduler } from "../src/studio/scheduler";

/** A hand-cranked stand-in for requestAnimationFrame and the clock. */
export class FakeScheduler implements Scheduler {
  time = 0;
  private nextId = 1;
  private pending = new Map<number, (time: number) => void>();

  now(): number {
    return this.time;
  }
  request(callback: (time: number) => void): number {
    const id = this.nextId++;
    this.pending.set(id, callback);
    return id;
  }
  cancel(id: number): void {
    this.pending.delete(id);
  }
  get waiting(): number {
    return this.pending.size;
  }
  /** Advances the clock by `ms` in one frame and fires what was requested. */
  frame(ms = 16): void {
    this.time += ms;
    const callbacks = [...this.pending.values()];
    this.pending.clear();
    for (const callback of callbacks) callback(this.time);
  }
  /** Runs frames until nothing is waiting (or the safety limit is hit). */
  settle(ms = 16, limit = 20_000): void {
    for (let i = 0; i < limit && this.pending.size > 0; i++) this.frame(ms);
  }
}

/** An in-memory stand-in for window.localStorage. */
export class MemoryStorage implements Storage {
  private data = new Map<string, string>();
  get length(): number {
    return this.data.size;
  }
  clear(): void {
    this.data.clear();
  }
  getItem(key: string): string | null {
    return this.data.get(key) ?? null;
  }
  key(index: number): string | null {
    return [...this.data.keys()][index] ?? null;
  }
  removeItem(key: string): void {
    this.data.delete(key);
  }
  setItem(key: string, value: string): void {
    this.data.set(key, String(value));
  }
}
EOF
