import { describe, expect, test } from "bun:test";
import { Studio } from "../src/studio/studio";
import { FakeScheduler } from "./fakes";

function newStudio(source = "", mode: "2d" | "3d" = "2d") {
  const scheduler = new FakeScheduler();
  const studio = new Studio({ scheduler });
  studio.setMode(mode);
  studio.setSource(source);
  return { studio, scheduler };
}

describe("studio: stepping", () => {
  test("step executes one command at a time and names the line being executed", () => {
    const { studio } = newStudio("np 10\npw 90\nnp 20");
    studio.step();
    expect(studio.state.status).toBe("paused");
    expect(studio.state.segments).toHaveLength(1);
    expect(studio.state.currentLine).toBe(1);
    studio.step();
    expect(studio.state.segments).toHaveLength(1);
    expect(studio.state.currentLine).toBe(2);
    studio.step();
    expect(studio.state.segments).toHaveLength(2);
    expect(studio.state.currentLine).toBe(3);
    expect(studio.state.status).toBe("paused");
  });
});
