import { compile, type Execution, type Mode, type RunError, type Segment, type TurtleView } from "../lang";
import { browserScheduler, type Scheduler } from "./scheduler";

export type Status = "idle" | "running" | "paused" | "finished" | "error";

export interface StudioState {
  mode: Mode;
  source: string;
  status: Status;
  /** The segments drawn so far. */
  segments: readonly Segment[];
  /** The line of the statement just executed, while running or stepping. */
  currentLine: number | null;
  error: RunError | null;
}

export interface StudioOptions {
  scheduler?: Scheduler;
}

export class Studio {
  state: StudioState = {
    mode: "2d",
    source: "",
    status: "idle",
    segments: [],
    currentLine: null,
    error: null,
  };
  private execution: Execution | null = null;
  private readonly scheduler: Scheduler;

  constructor(options: StudioOptions = {}) {
    this.scheduler = options.scheduler ?? browserScheduler;
  }

  setMode(mode: Mode): void {
    this.state = { ...this.state, mode };
  }

  setSource(source: string): void {
    this.state = { ...this.state, source };
  }

  /** Executes one statement; the first step starts a fresh, paused execution. */
  step(): void {
    if (!this.execution) {
      const compiled = compile(this.state.source, this.state.mode);
      if (!compiled.ok) {
        this.state = { ...this.state, status: "error", segments: [], error: compiled.error };
        return;
      }
      this.execution = compiled.start();
    }
    const advance = this.execution.next();
    if (advance.done) {
      this.state = { ...this.state, status: "finished", currentLine: null };
      return;
    }
    this.state = {
      ...this.state,
      status: "paused",
      segments: [...this.execution.segments],
      currentLine: advance.step.line,
    };
  }
}
