import { compile, type Execution, type Mode, type RunError, type Segment } from "../lang";
import { browserScheduler, type Scheduler } from "./scheduler";

export type Status = "idle" | "running" | "paused" | "finished" | "error";

export interface StudioState {
  mode: Mode;
  source: string;
  status: Status;
  /** The segments drawn so far. */
  segments: readonly Segment[];
  /** The line of the statement just executed, while running or stepping. */
  currentLine: number | null;
  error: RunError | null;
  /** Animation speed, 1 (slowest) to 6 (no animation). */
  speed: number;
}

export interface StudioOptions {
  scheduler?: Scheduler;
}

/** Statements per second at each animation speed; the last level draws everything at once. */
const RATES = [4, 15, 50, 150, 600, Infinity];
/** No frame executes more than this many statements, so the page stays responsive. */
const MAX_STEPS_PER_FRAME = 20_000;

export class Studio {
  state: StudioState = {
    mode: "2d",
    source: "",
    status: "idle",
    segments: [],
    currentLine: null,
    error: null,
    speed: 4,
  };
  private execution: Execution | null = null;
  private readonly scheduler: Scheduler;
  private frameId: number | null = null;
  private lastTime = 0;
  private budget = 0;

  constructor(options: StudioOptions = {}) {
    this.scheduler = options.scheduler ?? browserScheduler;
  }

  setMode(mode: Mode): void {
    this.state = { ...this.state, mode };
  }

  setSource(source: string): void {
    this.state = { ...this.state, source };
  }

  setSpeed(speed: number): void {
    this.state = { ...this.state, speed: Math.min(RATES.length, Math.max(1, Math.round(speed))) };
  }

  /** Runs the whole program, animated at the chosen speed. */
  run(): void {
    if (!this.begin()) return;
    this.state = { ...this.state, status: "running" };
    if (RATES[this.state.speed - 1] === Infinity) {
      this.advance(Infinity);
      return;
    }
    this.lastTime = this.scheduler.now();
    this.budget = 0;
    this.schedule();
  }

  /** Executes one statement; the first step starts a fresh, paused execution. */
  step(): void {
    if (!this.execution && !this.begin()) return;
    this.state = { ...this.state, status: "paused" };
    this.advance(1);
  }

  /** Compiles the source and starts an empty drawing; false when it cannot be run. */
  private begin(): boolean {
    const compiled = compile(this.state.source, this.state.mode);
    if (!compiled.ok) {
      this.execution = null;
      this.state = { ...this.state, status: "error", segments: [], currentLine: null, error: compiled.error };
      return false;
    }
    this.execution = compiled.start();
    this.state = { ...this.state, segments: [], currentLine: null, error: null };
    return true;
  }

  private schedule(): void {
    this.frameId = this.scheduler.request((time) => this.tick(time));
  }

  private tick(time: number): void {
    this.frameId = null;
    if (this.state.status !== "running") return;
    this.budget += ((time - this.lastTime) * RATES[this.state.speed - 1]!) / 1000;
    this.lastTime = time;
    const steps = Math.min(Math.floor(this.budget), MAX_STEPS_PER_FRAME);
    this.budget -= steps;
    this.advance(steps);
    if (this.state.status === "running") this.schedule();
  }

  /** Executes up to `count` statements and publishes the result as one state change. */
  private advance(count: number): void {
    const execution = this.execution;
    if (!execution) return;
    let line: number | null = this.state.currentLine;
    let ended: { error: RunError | null } | null = null;
    for (let i = 0; i < count; i++) {
      const next = execution.next();
      if (next.done) {
        ended = { error: next.error ? next.error.toRunError() : null };
        break;
      }
      line = next.step.line;
    }
    const segments = [...execution.segments];
    if (ended) {
      this.execution = null;
      this.state = {
        ...this.state,
        segments,
        currentLine: null,
        status: ended.error ? "error" : "finished",
        error: ended.error,
      };
    } else {
      this.state = { ...this.state, segments, currentLine: line };
    }
  }
}
