describe("studio: editing while a program is in flight", () => {
  const LONG = "powtorz 300 [np 1 pw 1]";

  test("editing during a run stops it, keeps the drawing but marks it as stale", () => {
    const { studio, scheduler } = newStudio(LONG);
    studio.run();
    scheduler.frame();
    scheduler.frame();
    const kept = studio.state.segments.length;
    expect(kept).toBeGreaterThan(0);
    studio.setSource(LONG + " np 5");
    expect(studio.state.status).toBe("idle");
    expect(studio.state.stale).toBe(true);
    expect(studio.state.currentLine).toBeNull();
    expect(studio.state.segments).toHaveLength(kept);
    expect(scheduler.waiting).toBe(0);
  });

  test("editing while paused or after the end also makes the drawing stale", () => {
    const paused = newStudio("np 1 np 2").studio;
    paused.step();
    paused.setSource("np 3 np 4");
    expect(paused.state.status).toBe("idle");
    expect(paused.state.stale).toBe(true);

    const { studio, scheduler } = newStudio("np 1");
    studio.run();
    scheduler.settle();
    expect(studio.state.stale).toBe(false);
    studio.setSource("np 2");
    expect(studio.state.stale).toBe(true);
    expect(studio.state.segments).toHaveLength(1);
  });

  test("running the edited program replaces the stale drawing and clears the flag", () => {
    const { studio, scheduler } = newStudio("np 1");
    studio.run();
    scheduler.settle();
    studio.setSource("pw 90 np 7 np 8");
    studio.run();
    scheduler.settle();
    expect(studio.state.stale).toBe(false);
    expect(studio.state.segments).toHaveLength(2);
    expect(studio.state.segments[0]!.to[0]).toBe(7);
