    studio.run();
    scheduler.frame();
    studio.setSource(LONG);
    expect(studio.state.status).toBe("running");
    expect(studio.state.stale).toBe(false);
  });

  test("an empty drawing is never stale", () => {
    const { studio } = newStudio("np 1");
    studio.setSource("np 2");
    expect(studio.state.stale).toBe(false);
  });
});
