describe("studio: the route (call stack) while stepping", () => {
  const SOURCE = "oto Kwadrat ma: bok\n  powtorz 2 [\n    np bok\n  ]\njuż\nKwadrat 5";

  test("lists the procedure calls and repeat counters that are active, innermost last", () => {
    const { studio } = newStudio(SOURCE);
    const stacks: unknown[] = [];
    for (let i = 0; i < 6; i++) {
      studio.step();
      stacks.push(studio.state.stack.map((e) => [e.kind, e.label, e.iteration, e.total, e.args, e.line]));
    }
    expect(stacks[0]).toEqual([["call", "Kwadrat", undefined, undefined, [5], 6]]);
    expect(stacks[1]).toEqual([
      ["call", "Kwadrat", undefined, undefined, [5], 6],
      ["repeat", "powtórz", 1, 2, undefined, 2],
    ]);
    expect(stacks[2]).toEqual(stacks[1]); // np bok, iteration 1
    expect(stacks[3]).toEqual([
      ["call", "Kwadrat", undefined, undefined, [5], 6],
      ["repeat", "powtórz", 2, 2, undefined, 2],
    ]);
    expect(studio.state.status).toBe("finished");
    expect(studio.state.stack).toEqual([]);
  });

  test("is empty at top level and when nothing runs", () => {
    const { studio } = newStudio("np 1");
    expect(studio.state.stack).toEqual([]);
    studio.step();
    expect(studio.state.stack).toEqual([]);
  });

  test("a repeat at top level is listed too, and recursion shows every active call", () => {
    const { studio } = newStudio("oto r ma: n\n  jeśli n > 0 [r n - 1]\njuż\nr 2");
    for (let i = 0; i < 6; i++) studio.step();
    const calls = studio.state.stack.filter((e) => e.kind === "call");
    expect(calls.map((c) => c.args)).toEqual([[2], [1], [0]]);
  });
});
