import { describe, expect, test } from "bun:test";
import { buildPermalink, parsePermalink } from "../src/share/permalink";

describe("permalink", () => {
  test("a program and its mode survive a round trip through the URL", () => {
    const source = '; Śnieżynka żółwia\nkolor "#2b6fb3"\npowtorz 3 [np 90 pw 120]\n';
    const url = buildPermalink("https://example.test/app/", { source, mode: "3d" });
    expect(url.startsWith("https://example.test/app/#/")).toBe(true);
    const hash = url.slice(url.indexOf("#"));
    expect(parsePermalink(hash)).toEqual({ source, mode: "3d" });
  });

  test("the link uses only URL-safe characters, whatever the program contains", () => {
    const url = buildPermalink("http://x/", { source: "np 1 ; ąęść 🐢 \"\\ <>&% +/=?#\n\t", mode: "2d" });
    const hash = url.slice(url.indexOf("#"));
    expect(hash).toMatch(/^#\/[A-Za-z0-9\/_-]+$/);
  });

  test("an empty program and a 50,000 character program both round trip", () => {
    expect(parsePermalink(buildPermalink("http://x/", { source: "", mode: "2d" }).split("#")[1]!.replace(/^/, "#"))).toEqual({
      source: "",
      mode: "2d",
    });
    const big = "np 1\n".repeat(10_000);
    const hash = "#" + buildPermalink("http://x/", { source: big, mode: "2d" }).split("#")[1];
    expect(parsePermalink(hash)?.source).toBe(big);
  });

  test("anything that is not a valid program link is rejected, never thrown", () => {
    for (const hash of ["", "#", "#/", "#/p/2d", "#/p/4d/AAAA", "#/p/2d/!!!!", "#/przyklady", "#/p/2d/%%%", "#/p/3d/a", "#/wyzwania/kwadrat"]) {
      expect(parsePermalink(hash)).toBeNull();
    }
  });

  test("links built from a base that already has a hash or query keep working", () => {
    const url = buildPermalink("https://example.test/app/?x=1#/opis", { source: "np 5", mode: "2d" });
    expect(url.startsWith("https://example.test/app/?x=1#/")).toBe(true);
    expect(parsePermalink("#" + url.split("#")[1])).toEqual({ source: "np 5", mode: "2d" });
  });
});
