import type { Mode } from "../lang";

export interface SharedProgram {
  source: string;
  mode: Mode;
}

function encodeBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function decodeBase64Url(payload: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(payload) || payload.length % 4 === 1) return null;
  try {
    const binary = atob(payload.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** The address that reopens `program`: `<base>#/p/<mode>/<program as base64url>`. */
export function buildPermalink(base: string, program: SharedProgram): string {
  const page = base.split("#")[0]!;
  return `${page}#/p/${program.mode}/${encodeBase64Url(program.source)}`;
}

/** Reads a location hash such as `#/p/3d/…`; null when it is not a valid program link. */
export function parsePermalink(hash: string): SharedProgram | null {
  const match = /^#\/p\/(2d|3d)\/([^/]*)$/.exec(hash);
  if (!match) return null;
  const source = decodeBase64Url(match[2]!);
  return source === null ? null : { source, mode: match[1] as Mode };
}
EOF
