import { describe, expect, test } from "bun:test";
import { DraftStore } from "../src/studio/drafts";
import { MemoryStorage } from "./fakes";

describe("drafts: surviving a reload", () => {
  test("the draft of each mode comes back from a new store over the same storage", () => {
    const storage = new MemoryStorage();
    const before = new DraftStore(storage);
    before.saveDraft("2d", "np 100 ; płaski");
    before.saveDraft("3d", "gora 90 np 5");
    const after = new DraftStore(storage);
    expect(after.loadDraft("2d")).toBe("np 100 ; płaski");
    expect(after.loadDraft("3d")).toBe("gora 90 np 5");
  });

  test("a mode that was never saved has no draft; an empty draft is a draft", () => {
    const store = new DraftStore(new MemoryStorage());
    expect(store.loadDraft("2d")).toBeNull();
    store.saveDraft("2d", "");
    expect(store.loadDraft("2d")).toBe("");
    expect(store.loadDraft("3d")).toBeNull();
  });

  test("unreadable or foreign data in storage is ignored", () => {
    const storage = new MemoryStorage();
    storage.setItem("logomocja:v1:draft:2d", "{not json");
    storage.setItem("logomocja:v1:draft:3d", JSON.stringify({ text: 42 }));
    storage.setItem("logomocja:v1:backups", "[1, 2, {\"id\": 3}]");
    const store = new DraftStore(storage);
    expect(store.loadDraft("2d")).toBeNull();
    expect(store.loadDraft("3d")).toBeNull();
    expect(store.listBackups()).toEqual([]);
  });

  test("when storage refuses writes the draft still works for the session and the store says so", () => {
    const storage = new MemoryStorage();
    storage.setItem = () => {
      throw new DOMException("full", "QuotaExceededError");
    };
    const store = new DraftStore(storage);
    expect(store.saveDraft("2d", "np 1")).toBe(false);
    expect(store.persistent).toBe(false);
    expect(store.loadDraft("2d")).toBe("np 1");
  });

  test("with no storage at all, drafts live in memory", () => {
    const store = new DraftStore(null);
    expect(store.saveDraft("2d", "np 2")).toBe(false);
    expect(store.loadDraft("2d")).toBe("np 2");
  });
});

describe("drafts: backups of replaced programs", () => {
  test("stash keeps a replaced program, newest first, and survives a reload", () => {
    const storage = new MemoryStorage();
    const store = new DraftStore(storage, () => 1000);
    store.stash("2d", "np 1", "Wczytano przykład");
    store.stash("3d", "gora 5", "Otwarto link");
    const list = new DraftStore(storage).listBackups();
    expect(list.map((b) => [b.mode, b.source, b.reason])).toEqual([
      ["3d", "gora 5", "Otwarto link"],
      ["2d", "np 1", "Wczytano przykład"],
    ]);
    expect(list[0]!.savedAt).toBe(1000);
  });

  test("blank programs and exact repeats are not worth a backup; only the ten newest are kept", () => {
    const store = new DraftStore(new MemoryStorage());
    store.stash("2d", "   \n", "x");
    store.stash("2d", "np 1", "x");
    store.stash("2d", "np 1", "x");
    expect(store.listBackups()).toHaveLength(1);
    for (let i = 2; i <= 15; i++) store.stash("2d", `np ${i}`, "x");
    const list = store.listBackups();
    expect(list).toHaveLength(10);
    expect(list[0]!.source).toBe("np 15");
    expect(list[9]!.source).toBe("np 6");
  });

  test("a backup can be fetched by id and removed", () => {
    const store = new DraftStore(new MemoryStorage());
    store.stash("2d", "np 1", "x");
    const [backup] = store.listBackups();
    expect(store.getBackup(backup!.id)?.source).toBe("np 1");
    store.removeBackup(backup!.id);
    expect(store.getBackup(backup!.id)).toBeUndefined();
    expect(store.listBackups()).toEqual([]);
  });
});
