import type { Mode } from "../lang";

export interface Backup {
  id: string;
  mode: Mode;
  source: string;
  /** Why it was set aside, in the user's language. */
  reason: string;
  savedAt: number;
}

const PREFIX = "logomocja:v1:";
const MAX_BACKUPS = 10;

/**
 * The text of each mode's draft, plus a short list of programs that were replaced.
 * Backed by `localStorage` when it works, by memory when it does not.
 */
export class DraftStore {
  /** False once a write failed or when there is no storage: drafts then last only this session. */
  persistent: boolean;
  private readonly memory = new Map<string, string>();

  constructor(
    private readonly storage: Storage | null,
    private readonly clock: () => number = Date.now,
  ) {
    this.persistent = storage !== null;
  }

  private read(key: string): string | null {
    if (this.memory.has(key)) return this.memory.get(key)!;
    try {
      return this.storage?.getItem(PREFIX + key) ?? null;
    } catch {
      return null;
    }
  }

  private write(key: string, value: string): boolean {
    this.memory.set(key, value);
    try {
      if (!this.storage) return false;
      this.storage.setItem(PREFIX + key, value);
      this.memory.delete(key);
      return true;
    } catch {
      this.persistent = false;
      return false;
    }
  }

  loadDraft(mode: Mode): string | null {
    const raw = this.read(`draft:${mode}`);
    if (raw === null) return null;
    try {
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === "object" && typeof (parsed as { text?: unknown }).text === "string") {
        return (parsed as { text: string }).text;
      }
    } catch {
      // fall through: unreadable data is as good as none
    }
    return null;
  }

  /** Remembers the draft; false when it could not be written to persistent storage. */
  saveDraft(mode: Mode, text: string): boolean {
    return this.write(`draft:${mode}`, JSON.stringify({ text }));
  }

  listBackups(): Backup[] {
    const raw = this.read("backups");
    if (raw === null) return [];
    try {
      const parsed: unknown = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(
        (b): b is Backup =>
          !!b &&
          typeof b.id === "string" &&
          (b.mode === "2d" || b.mode === "3d") &&
          typeof b.source === "string" &&
          typeof b.reason === "string" &&
          typeof b.savedAt === "number",
      );
    } catch {
      return [];
    }
  }

  /** Sets a replaced program aside; blank programs and immediate repeats are not kept. */
  stash(mode: Mode, source: string, reason: string): void {
    if (source.trim() === "") return;
    const list = this.listBackups();
    if (list[0] && list[0].mode === mode && list[0].source === source) return;
    const id = `${this.clock().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    list.unshift({ id, mode, source, reason, savedAt: this.clock() });
    this.write("backups", JSON.stringify(list.slice(0, MAX_BACKUPS)));
  }

  getBackup(id: string): Backup | undefined {
    return this.listBackups().find((b) => b.id === id);
  }

  removeBackup(id: string): void {
    this.write("backups", JSON.stringify(this.listBackups().filter((b) => b.id !== id)));
  }
}
