import { describe, expect, test } from "bun:test";
import { findExample } from "../src/examples";
import { run } from "../src/lang";
import { buildPermalink } from "../src/share/permalink";
import { Workspace } from "../src/studio/workspace";
import { FakeScheduler, MemoryStorage } from "./fakes";

function open(storage = new MemoryStorage()) {
  const scheduler = new FakeScheduler();
  const workspace = new Workspace({ storage, scheduler });
  return { workspace, storage, scheduler };
}

describe("workspace: first visit and drafts that survive a reload", () => {
  test("a first visit starts with a small program in each mode, drawn straight away", () => {
    const { workspace } = open();
    expect(workspace.studio.state.mode).toBe("2d");
    expect(workspace.studio.state.source).toBe(findExample("kwadrat")!.source);
    workspace.start();
    expect(workspace.studio.state.status).toBe("finished");
    expect(workspace.studio.state.segments).toHaveLength(4);
    workspace.switchMode("3d");
    expect(workspace.studio.state.source).toBe(findExample("schody")!.source);
  });

  test("edits are kept for each mode and come back after a reload, in the mode that was open", () => {
    const first = open();
    first.workspace.edit("np 77");
    first.workspace.switchMode("3d");
    first.workspace.edit("gora 90 np 33");
    const second = open(first.storage);
    expect(second.workspace.studio.state.mode).toBe("3d");
    expect(second.workspace.studio.state.source).toBe("gora 90 np 33");
    second.workspace.switchMode("2d");
    expect(second.workspace.studio.state.source).toBe("np 77");
  });

  test("start draws what the restored draft says", () => {
    const first = open();
    first.workspace.edit("powtorz 3 [np 5 pw 120]");
    const second = open(first.storage);
    second.workspace.start();
    expect(second.workspace.studio.state.segments).toEqual(run("powtorz 3 [np 5 pw 120]", "2d").segments);
  });

  test("switching mode never loses the text of the mode left behind", () => {
    const { workspace } = open();
    workspace.edit("np 1");
    workspace.switchMode("3d");
    workspace.switchMode("2d");
    expect(workspace.studio.state.source).toBe("np 1");
  });
});

describe("workspace: loading examples never silently destroys a draft", () => {
  test("an untouched draft is replaced by the example without any question", () => {
    const { workspace } = open();
    expect(workspace.loadExample("gwiazda")).toEqual({ status: "loaded" });
    expect(workspace.studio.state.source).toBe(findExample("gwiazda")!.source);
    expect(workspace.studio.state.status).toBe("finished");
    expect(workspace.studio.state.segments).toHaveLength(5);
  });

  test("a draft with unsaved changes is kept and the caller is asked to confirm", () => {
    const { workspace } = open();
    workspace.edit("np 123 ; moja praca");
    expect(workspace.loadExample("gwiazda")).toEqual({ status: "needs-confirmation" });
    expect(workspace.studio.state.source).toBe("np 123 ; moja praca");
    expect(workspace.backups()).toEqual([]);
  });

  test("when confirmed the example loads and the replaced draft is recoverable", () => {
    const { workspace } = open();
    workspace.edit("np 123 ; moja praca");
    expect(workspace.loadExample("gwiazda", { confirmed: true })).toEqual({ status: "loaded" });
    expect(workspace.studio.state.source).toBe(findExample("gwiazda")!.source);
    const [backup] = workspace.backups();
    expect(backup!.source).toBe("np 123 ; moja praca");
    expect(backup!.mode).toBe("2d");
    expect(workspace.restoreBackup(backup!.id)).toBe(true);
    expect(workspace.studio.state.source).toBe("np 123 ; moja praca");
    expect(workspace.studio.state.mode).toBe("2d");
  });

  test("a 3D example opens in 3D and leaves the 2D draft alone", () => {
    const { workspace } = open();
    workspace.edit("np 5 ; płaski szkic");
    expect(workspace.loadExample("helisa")).toEqual({ status: "loaded" });
    expect(workspace.studio.state.mode).toBe("3d");
    expect(workspace.studio.state.source).toBe(findExample("helisa")!.source);
    workspace.switchMode("2d");
    expect(workspace.studio.state.source).toBe("np 5 ; płaski szkic");
  });

  test("only the draft of the example's own mode is at risk", () => {
    const { workspace } = open();
    workspace.switchMode("3d");
    workspace.edit("gora 1 ; trójwymiarowy szkic");
    workspace.switchMode("2d");
    expect(workspace.loadExample("kula")).toEqual({ status: "needs-confirmation" });
    expect(workspace.studio.state.mode).toBe("2d");
    expect(workspace.loadExample("rozeta")).toEqual({ status: "loaded" });
  });

  test("unknown examples are reported, not guessed", () => {
    expect(open().workspace.loadExample("nie ma")).toEqual({ status: "not-found" });
  });

  test("an empty editor holds nothing worth confirming", () => {
    const { workspace } = open();
    workspace.edit("");
    expect(workspace.loadExample("kwadrat")).toEqual({ status: "loaded" });
  });

  test("a loaded example that the user then edits is protected again", () => {
    const { workspace } = open();
    workspace.loadExample("gwiazda");
    workspace.edit(findExample("gwiazda")!.source + "\nnp 1");
    expect(workspace.loadExample("kwadrat")).toEqual({ status: "needs-confirmation" });
  });
});

describe("workspace: sharing links", () => {
  test("opening a permalink loads the program in its mode and draws it", () => {
    const { workspace } = open();
    const link = buildPermalink("http://x/", { source: "gora 90 powtorz 4 [np 10 pw 90]", mode: "3d" });
    const result = workspace.openPermalink("#" + link.split("#")[1]);
    expect(result).toEqual(run("gora 90 powtorz 4 [np 10 pw 90]", "3d"));
    expect(workspace.studio.state.mode).toBe("3d");
    expect(workspace.studio.state.source).toBe("gora 90 powtorz 4 [np 10 pw 90]");
    expect(workspace.studio.state.status).toBe("finished");
  });

  test("a link replaces the draft of its mode but the old text is set aside, not lost", () => {
    const { workspace } = open();
    workspace.switchMode("3d");
    workspace.edit("gora 5 ; mój szkic");
    workspace.openPermalink("#" + buildPermalink("http://x/", { source: "gora 90 np 1", mode: "3d" }).split("#")[1]);
    expect(workspace.backups().map((b) => b.source)).toEqual(["gora 5 ; mój szkic"]);
  });

  test("a bad link changes nothing", () => {
    const { workspace } = open();
    workspace.edit("np 5");
    expect(workspace.openPermalink("#/p/2d/%%%")).toBeNull();
    expect(workspace.studio.state.source).toBe("np 5");
  });

  test("the link to share is built from the program in the editor and its mode", () => {
    const { workspace } = open();
    workspace.switchMode("3d");
    workspace.edit("gora 10 np 5");
    const link = workspace.shareLink("https://example.test/Logomocja/builds/x/");
    expect(link.startsWith("https://example.test/Logomocja/builds/x/#/p/3d/")).toBe(true);
    const other = open();
    other.workspace.openPermalink("#" + link.split("#")[1]);
    expect(other.workspace.studio.state.source).toBe("gora 10 np 5");
    expect(other.workspace.studio.state.mode).toBe("3d");
  });
});

describe("workspace: .logo files", () => {
  test("the program downloads as plain text named after it", () => {
    const { workspace } = open();
    workspace.loadExample("sniezynka");
    const file = workspace.exportFile();
    expect(file.name).toBe("sniezynka.logo");
    expect(file.text).toBe(findExample("sniezynka")!.source + "\n");
    workspace.edit("np 1");
    expect(workspace.exportFile().name).toBe("sniezynka.logo");
  });

  test("an unnamed program downloads as szkic-2d.logo or szkic-3d.logo", () => {
    const { workspace } = open();
    workspace.edit("np 1");
    expect(workspace.exportFile().name).toBe("szkic-2d.logo");
    workspace.switchMode("3d");
    workspace.edit("gora 1");
    expect(workspace.exportFile().name).toBe("szkic-3d.logo");
  });

  test("opening a file loads it; a program with pitch or roll lands in 3D, a flat one in the current mode", () => {
    const { workspace } = open();
    workspace.importFile("wspinaczka.logo", "gora 45\nnp 10\n");
    expect(workspace.studio.state.mode).toBe("3d");
    expect(workspace.studio.state.source).toBe("gora 45\nnp 10\n");
    expect(workspace.exportFile().name).toBe("wspinaczka.logo");
    workspace.importFile("plaski.LOGO", "np 10\n");
    expect(workspace.studio.state.mode).toBe("3d"); // flat programs keep the current mode
    workspace.switchMode("2d");
    workspace.importFile("plaski.logo", "np 20\n");
