import { EXAMPLES, findExample } from "../examples";
import { usesSpatialCommands, type Mode, type RunResult } from "../lang";
import { buildPermalink, parsePermalink } from "../share/permalink";
import { DraftStore, type Backup } from "./drafts";
import type { Scheduler } from "./scheduler";
import { Studio } from "./studio";

export interface WorkspaceOptions {
  storage: Storage | null;
  scheduler?: Scheduler;
  clock?: () => number;
}

export type LoadResult =
  | { status: "loaded" }
  | { status: "needs-confirmation" }
  | { status: "not-found" };

interface Origin {
  /** The text counted as saved: an example, a file just opened or downloaded, or a shared link. */
  baseline: string;
  /** What the program is called when downloaded; null for an unnamed sketch. */
  title: string | null;
}

const FIRST_VISIT: Record<Mode, string> = { "2d": "kwadrat", "3d": "schody" };

/**
 * The app's model: the studio plus everything the user would be upset to lose, namely the drafts
 * of both modes, the programs set aside when something replaced them, and where each came from.
 */
export class Workspace {
  readonly studio: Studio;
  readonly drafts: DraftStore;
  private readonly origins: Record<Mode, Origin>;

  constructor(options: WorkspaceOptions) {
    this.drafts = new DraftStore(options.storage, options.clock);
    this.studio = new Studio({ scheduler: options.scheduler });
    const initial = (mode: Mode): Origin => {
      const example = findExample(FIRST_VISIT[mode])!;
      return this.drafts.loadOrigin(mode) ?? { baseline: example.source, title: example.id };
    };
    this.origins = { "2d": initial("2d"), "3d": initial("3d") };
    const mode = this.drafts.loadLastMode() ?? "2d";
    this.studio.open("", mode);
    this.studio.reset();
    this.studio.setSource(this.draftOf(mode));
  }

  private draftOf(mode: Mode): string {
    return this.drafts.loadDraft(mode) ?? this.origins[mode].baseline;
  }

  /** Draws the draft that is on screen, at once. */
  start(): void {
    this.studio.open(this.studio.state.source, this.studio.state.mode);
  }

  /** The text counts as unsaved work: it is not blank and differs from where it came from. */
  isDirty(mode: Mode): boolean {
    const text = mode === this.studio.state.mode ? this.studio.state.source : this.draftOf(mode);
    return text.trim() !== "" && text !== this.origins[mode].baseline;
  }

  edit(text: string): void {
    this.studio.setSource(text);
    this.drafts.saveDraft(this.studio.state.mode, text);
  }

  switchMode(mode: Mode): void {
    if (mode === this.studio.state.mode) return;
    this.drafts.saveLastMode(mode);
    this.studio.open(this.draftOf(mode), mode);
  }

  /** The name the program is downloaded under, without the extension. */
  title(): string | null {
    return this.origins[this.studio.state.mode].title;
  }

  private setOrigin(mode: Mode, origin: Origin): void {
    this.origins[mode] = origin;
    this.drafts.saveOrigin(mode, origin);
  }

  /** Puts a program in the editor of `mode`, setting aside whatever unsaved text it replaces. */
  private replace(mode: Mode, source: string, origin: Origin, reason: string): RunResult {
    if (this.isDirty(mode)) {
      const current = mode === this.studio.state.mode ? this.studio.state.source : this.draftOf(mode);
      this.drafts.stash(mode, current, reason);
    }
    this.setOrigin(mode, origin);
    this.drafts.saveDraft(mode, source);
    this.drafts.saveLastMode(mode);
    return this.studio.open(source, mode);
  }

  loadExample(id: string, options: { confirmed?: boolean } = {}): LoadResult {
    const example = findExample(id);
    if (!example) return { status: "not-found" };
    if (this.isDirty(example.mode) && !options.confirmed) return { status: "needs-confirmation" };
    this.replace(example.mode, example.source, { baseline: example.source, title: example.id }, `Zastąpiono przykładem „${example.name}”`);
    return { status: "loaded" };
  }

  /** Opens `#/p/<mode>/<program>`; null when the hash is not a program link. */
  openPermalink(hash: string): RunResult | null {
    const shared = parsePermalink(hash);
    if (!shared) return null;
    return this.replace(shared.mode, shared.source, { baseline: shared.source, title: null }, "Otwarto link do programu");
  }

  shareLink(base: string): string {
    return buildPermalink(base, { source: this.studio.state.source, mode: this.studio.state.mode });
  }

  /** The program as a `.logo` text file. Downloading counts as saving it. */
  exportFile(): { name: string; text: string } {
    const { source, mode } = this.studio.state;
    const title = this.origins[mode].title ?? `szkic-${mode}`;
    this.setOrigin(mode, { baseline: source, title: this.origins[mode].title });
    return { name: `${title}.logo`, text: source.endsWith("\n") ? source : source + "\n" };
  }

  importFile(fileName: string, text: string, options: { confirmed?: boolean } = {}): LoadResult {
    const mode: Mode = usesSpatialCommands(text) ? "3d" : this.studio.state.mode;
    if (this.isDirty(mode) && !options.confirmed) return { status: "needs-confirmation" };
    const title = fileName.replace(/^.*[\\/]/, "").replace(/\.logo$/i, "") || null;
    this.replace(mode, text, { baseline: text, title }, `Zastąpiono plikiem „${fileName}”`);
    return { status: "loaded" };
  }

  backups(): Backup[] {
    return this.drafts.listBackups();
  }

  /** Brings a set-aside program back; the program it replaces is set aside in turn. */
  restoreBackup(id: string): boolean {
    const backup = this.drafts.getBackup(id);
    if (!backup) return false;
    this.replace(backup.mode, backup.source, { baseline: backup.source, title: null }, "Zastąpiono kopią zapasową");
    return true;
  }
}

export { EXAMPLES };
EOF
