    if (!example) return { status: "not-found" };
    if (this.isDirty(example.mode) && !options.confirmed) return { status: "needs-confirmation" };
    this.replace(example.mode, example.source, { baseline: example.source, title: example.id }, `Zastąpiono przykładem „${example.name}”`);
    return { status: "loaded" };
  }

  /** Opens `#/p/<mode>/<program>`; null when the hash is not a program link. */
  openPermalink(hash: string): RunResult | null {
    const shared = parsePermalink(hash);
    if (!shared) return null;
    return this.replace(shared.mode, shared.source, { baseline: shared.source, title: null }, "Otwarto link do programu");
  }

  shareLink(base: string): string {
    return buildPermalink(base, { source: this.studio.state.source, mode: this.studio.state.mode });
  }

  /** The program as a `.logo` text file. Downloading counts as saving it. */
  exportFile(): { name: string; text: string } {
    const { source, mode } = this.studio.state;
    const title = this.origins[mode].title ?? `szkic-${mode}`;
    this.setOrigin(mode, { baseline: source, title: this.origins[mode].title });
    return { name: `${title}.logo`, text: source.endsWith("\n") ? source : source + "\n" };
  }

  importFile(fileName: string, text: string, options: { confirmed?: boolean } = {}): LoadResult {
    const mode: Mode = usesSpatialCommands(text) ? "3d" : this.studio.state.mode;
    if (this.isDirty(mode) && !options.confirmed) return { status: "needs-confirmation" };
    const title = fileName.replace(/^.*[\\/]/, "").replace(/\.logo$/i, "") || null;
    this.replace(mode, text, { baseline: text, title }, `Zastąpiono plikiem „${fileName}”`);
    return { status: "loaded" };
  }

  backups(): Backup[] {
    return this.drafts.listBackups();
  }

  /** Brings a set-aside program back; the program it replaces is set aside in turn. */
  restoreBackup(id: string): boolean {
    const backup = this.drafts.getBackup(id);
    if (!backup) return false;
    this.replace(backup.mode, backup.source, { baseline: backup.source, title: null }, "Zastąpiono kopią zapasową");
    return true;
  }
}

export { EXAMPLES };
