import { describe, expect, test } from "bun:test";
import { CHALLENGES, findChallenge } from "../src/challenges/challenges";
import { checkChallenge } from "../src/challenges/check";
import { ChallengeProgress } from "../src/challenges/progress";
import { MemoryStorage } from "./fakes";

const check = (id: string, source: string) => checkChallenge(findChallenge(id)!, source);

describe("challenges: the catalogue", () => {
  test("at least five practice tasks, each telling what to draw", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    for (const c of CHALLENGES) {
      expect(c.id).toMatch(/^[a-z0-9-]+$/);
      expect(c.title.length).toBeGreaterThan(2);
      expect(c.brief.length).toBeGreaterThan(20);
      expect(["2d", "3d"]).toContain(c.mode);
    }
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    expect(CHALLENGES.some((c) => c.mode === "3d")).toBe(true);
  });

  test("the target drawing of every task is available to show", () => {
    for (const c of CHALLENGES) {
      expect(c.target().length).toBeGreaterThan(0);
    }
  });
});

describe("challenges: right answers pass, however they are written", () => {
  test.each([
    ["kwadrat", "np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100"],
    ["kwadrat", "oto bok\n np 100\n pw 90\njuż\nbok bok bok bok"],
    ["trojkat", "np 120 pw 120 np 120 pw 120 np 120"],
    ["trojkat", "powtorz 3 [np 120 pw 120]"],
    ["szesciokat", 'kolor "#c1763d"\npowtorz 6 [np 70 pw 60]'],
    ["gwiazda", "oto ramie ma: d\n np d\n pw 144\njuż\npowtorz 5 [ramie 150]"],
    ["gwiazda", "niech k 0\npowtorz 5 [np 150 niech k k + 144 pw 144]"],
    ["schodki", "powtorz 5 [np 30 pw 90 np 30 lw 90]"],
    ["rozeta", "powtorz 8 [powtorz 4 [np 60 pw 90] pw 45]"],
    ["kwadraty", "oto k\n powtorz 4 [np 50 pw 90]\njuż\nk pod pw 90 np 70 lw 90 opu k pod pw 90 np 70 lw 90 opu k"],
    ["szkielet", "powtorz 4 [np 100 pw 90] gora 90 np 100 dol 90 powtorz 4 [np 100 pw 90]\npowtorz 4 [np 100 dol 90 np 100 pod ws 100 opu gora 90 pw 90]"],
  ])("%s accepts %p", (id, source) => {
    const result = check(id, source);
    expect(result.reason).toMatch(/Brawo/);
    expect(result.passed).toBe(true);
  });

  test("the order of the strokes, their direction and doubled lines do not matter", () => {
    expect(check("kwadrat", "pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 np 0 ws 100 np 100").passed).toBe(false); // wrong place: starts east
    expect(check("kwadrat", "np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 np 100 ws 100").passed).toBe(false); // sticks out
    expect(check("kwadrat", "pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100").passed).toBe(false);
    // the same square drawn the other way round, over itself twice
    expect(check("kwadrat", "pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 ".replace("pw 90 np 100", "lw 0 np 0") + "pw 90 np 100").passed).toBe(false);
  });

  test("a square drawn backwards from the start corner is the same square", () => {
    expect(check("kwadrat", "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100").passed).toBe(false);
    expect(check("kwadrat", "np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100").passed).toBe(true);
    expect(check("kwadrat", "ws 0 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 dom").passed).toBe(true);
  });
});

describe("challenges: wrong answers fail, and say why", () => {
  test("an empty program draws nothing", () => {
    const r = check("kwadrat", "; jeszcze nic");
    expect(r.passed).toBe(false);
    expect(r.reason).toBe("Nic nie narysowano. Zacznij od polecenia ruchu, na przykład „np 100”.");
  });

  test("a program with an error fails with the position of the error", () => {
    const r = check("kwadrat", "np 100\nskacz");
    expect(r.passed).toBe(false);
    expect(r.reason).toBe("Program ma błąd w wierszu 2, kolumnie 1: Nieznane polecenie „skacz”.");
  });

  test("a run-time error fails even if the drawing so far looks right", () => {
    const r = check("kwadrat", "powtorz 4 [np 100 pw 90] np 1 / 0");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Program ma błąd w wierszu 1, kolumnie 31: Dzielenie przez zero/);
  });

  test("an incomplete figure says how much is missing", () => {
    const r = check("kwadrat", "powtorz 3 [np 100 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Brakuje części rysunku/);
  });

  test("a figure with extra lines says so", () => {
    const r = check("kwadrat", "powtorz 4 [np 100 pw 90] np 60");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Rysunek ma linie, których nie ma we wzorze/);
  });

  test("the right shape in the wrong size is called too small or too large", () => {
    expect(check("kwadrat", "powtorz 4 [np 80 pw 90]").reason).toMatch(/za mały/);
    expect(check("kwadrat", "powtorz 4 [np 130 pw 90]").reason).toMatch(/za duży/);
  });

  test("the right shape in the wrong place is recognised as such", () => {
    const r = check("kwadrat", "pw 90 np 50 lw 90 powtorz 4 [np 100 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Kształt się zgadza, ale leży w innym miejscu/);
  });

  test("a required colour is checked", () => {
    const r = check("szesciokat", "powtorz 6 [np 70 pw 60]");
    expect(r.passed).toBe(false);
    expect(r.reason).toBe("Kształt jest dobry, ale kolor powinien być #c1763d.");
  });

  test("a required technique is checked: a procedure here", () => {
    const r = check("kwadraty", "powtorz 4 [np 50 pw 90] pod pw 90 np 70 lw 90 opu powtorz 4 [np 50 pw 90] pod pw 90 np 70 lw 90 opu powtorz 4 [np 50 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Rysunek jest dobry, ale to zadanie trzeba rozwiązać procedurą/);
  });

  test("a 3D task checks all three coordinates", () => {
    const flat = check("szkielet", "powtorz 4 [np 100 pw 90]");
    expect(flat.passed).toBe(false);
    expect(flat.reason).toMatch(/Brakuje części rysunku/);
  });

  test("a task is not solved by drawing the whole plane", () => {
    expect(check("kwadrat", "powtorz 200 [np 100 pw 91]").passed).toBe(false);
  });
});

describe("challenges: progress is persisted", () => {
  test("a solved task stays solved after a reload, with the winning program", () => {
    const storage = new MemoryStorage();
    const before = new ChallengeProgress(storage, () => 5000);
    expect(before.isSolved("kwadrat")).toBe(false);
    before.record("kwadrat", "powtorz 4 [np 100 pw 90]", check("kwadrat", "powtorz 4 [np 100 pw 90]"));
    const after = new ChallengeProgress(storage);
    expect(after.isSolved("kwadrat")).toBe(true);
    expect(after.solution("kwadrat")).toBe("powtorz 4 [np 100 pw 90]");
    expect(after.solvedCount()).toBe(1);
    expect(after.isSolved("trojkat")).toBe(false);
  });

  test("failed attempts are counted but never mark a task solved, and a solved task stays solved", () => {
    const progress = new ChallengeProgress(new MemoryStorage());
    progress.record("kwadrat", "np 1", check("kwadrat", "np 1"));
    progress.record("kwadrat", "np 2", check("kwadrat", "np 2"));
    expect(progress.isSolved("kwadrat")).toBe(false);
    expect(progress.attempts("kwadrat")).toBe(2);
    progress.record("kwadrat", "powtorz 4 [np 100 pw 90]", check("kwadrat", "powtorz 4 [np 100 pw 90]"));
    progress.record("kwadrat", "np 3", check("kwadrat", "np 3"));
    expect(progress.isSolved("kwadrat")).toBe(true);
    expect(progress.attempts("kwadrat")).toBe(4);
    expect(progress.solution("kwadrat")).toBe("powtorz 4 [np 100 pw 90]");
  });

  test("each task keeps its own unfinished draft", () => {
    const storage = new MemoryStorage();
    const progress = new ChallengeProgress(storage);
    progress.saveDraft("trojkat", "np 120 ; w trakcie");
    expect(new ChallengeProgress(storage).loadDraft("trojkat")).toBe("np 120 ; w trakcie");
    expect(new ChallengeProgress(storage).loadDraft("kwadrat")).toBeNull();
  });

  test("broken data in storage is ignored and progress can be reset", () => {
    const storage = new MemoryStorage();
    storage.setItem("logomocja:v1:challenges", "[[[");
    const progress = new ChallengeProgress(storage);
    expect(progress.solvedCount()).toBe(0);
    progress.record("kwadrat", "powtorz 4 [np 100 pw 90]", check("kwadrat", "powtorz 4 [np 100 pw 90]"));
    progress.resetAll();
    expect(new ChallengeProgress(storage).solvedCount()).toBe(0);
  });
});
