import type { CheckResult } from "./check";

interface Entry {
  solved: boolean;
  attempts: number;
  solution?: string;
  solvedAt?: number;
  draft?: string;
}

const KEY = "logomocja:v1:challenges";

/** Which tasks are solved, how often each was tried and the unfinished draft of each. */
export class ChallengeProgress {
  private entries: Record<string, Entry> = {};

  constructor(
    private readonly storage: Storage | null,
    private readonly clock: () => number = Date.now,
  ) {
    try {
      const parsed: unknown = JSON.parse(storage?.getItem(KEY) ?? "{}");
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        for (const [id, value] of Object.entries(parsed)) {
          const e = value as Partial<Entry>;
          if (e && typeof e === "object" && typeof e.solved === "boolean" && typeof e.attempts === "number") {
            this.entries[id] = e as Entry;
          }
        }
      }
    } catch {
      this.entries = {};
    }
  }

  private persist(): void {
    try {
      this.storage?.setItem(KEY, JSON.stringify(this.entries));
    } catch {
      // progress then lasts only for this visit
    }
  }

  private entry(id: string): Entry {
    return (this.entries[id] ??= { solved: false, attempts: 0 });
  }

  isSolved(id: string): boolean {
    return this.entries[id]?.solved === true;
  }

  attempts(id: string): number {
    return this.entries[id]?.attempts ?? 0;
  }

  solution(id: string): string | undefined {
    return this.entries[id]?.solution;
