cd /work && cat > src/challenges/check.ts <<'EOF'
import { definesProcedure, run, usesRepeat, type Segment, type Vec3 } from "../lang";
import type { Challenge } from "./challenges";

export interface CheckResult {
  passed: boolean;
  /** One or two sentences in Polish saying what is right or what to fix. */
  reason: string;
  /** Share of the target drawing the program did not cover (0 to 1). */
  missing: number;
  /** Share of the program's drawing that lies off the target (0 to 1). */
  extra: number;
}

/** The share of either drawing that may be off before the answer counts as wrong. */
const ALLOWED_SHARE = 0.02;
const MAX_SAMPLES = 20_000;

const length = (s: Segment) => Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);

function bounds(segments: Segment[]): { min: Vec3; max: Vec3 } {
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const s of segments) {
    for (const p of [s.from, s.to]) {
      for (let i = 0; i < 3; i++) {
        min[i] = Math.min(min[i]!, p[i]!);
        max[i] = Math.max(max[i]!, p[i]!);
      }
    }
  }
  return { min, max };
}

function diagonal(segments: Segment[]): number {
  const { min, max } = bounds(segments);
  return Math.hypot(max[0] - min[0], max[1] - min[1], max[2] - min[2]);
}

function map(segments: Segment[], f: (p: Vec3) => Vec3): Segment[] {
  return segments.map((s) => ({ ...s, from: f(s.from), to: f(s.to) }));
}

/** Points along the segments, no further apart than `step`. */
function sample(segments: Segment[], step: number): Vec3[] {
  const total = segments.reduce((sum, s) => sum + length(s), 0);
  const spacing = Math.max(step, total / MAX_SAMPLES);
  const points: Vec3[] = [];
  for (const s of segments) {
    const n = Math.max(1, Math.ceil(length(s) / spacing));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      points.push([
        s.from[0] + (s.to[0] - s.from[0]) * t,
        s.from[1] + (s.to[1] - s.from[1]) * t,
        s.from[2] + (s.to[2] - s.from[2]) * t,
      ]);
    }
  }
  return points;
}

function distanceToSegment(p: Vec3, s: Segment): number {
  const ax = s.from[0], ay = s.from[1], az = s.from[2];
  const dx = s.to[0] - ax, dy = s.to[1] - ay, dz = s.to[2] - az;
  const len2 = dx * dx + dy * dy + dz * dz;
  let t = len2 === 0 ? 0 : ((p[0] - ax) * dx + (p[1] - ay) * dy + (p[2] - az) * dz) / len2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p[0] - (ax + dx * t), p[1] - (ay + dy * t), p[2] - (az + dz * t));
}

/** The share of `points` that lie further than `tolerance` from every one of `segments`. */
function uncovered(points: Vec3[], segments: Segment[], tolerance: number): number {
  let far = 0;
  for (const p of points) {
    if (!segments.some((s) => distanceToSegment(p, s) <= tolerance)) far++;
  }
  return points.length === 0 ? 0 : far / points.length;
}

function compare(user: Segment[], target: Segment[], tolerance: number) {
  return {
    missing: uncovered(sample(target, tolerance), user, tolerance),
    extra: uncovered(sample(user, tolerance), target, tolerance),
  };
}

const matches = (c: { missing: number; extra: number }) => c.missing <= ALLOWED_SHARE && c.extra <= ALLOWED_SHARE;

function fail(reason: string, missing = 1, extra = 0): CheckResult {
  return { passed: false, reason, missing, extra };
}

/** Runs `source` and compares the drawing with the challenge's target, however it was drawn. */
export function checkChallenge(challenge: Challenge, source: string): CheckResult {
  const result = run(source, challenge.mode);
  if (result.error) {
    const { line, column, message } = result.error;
    return fail(`Program ma błąd w wierszu ${line}, kolumnie ${column}: ${message}`);
  }
  const user = result.segments.filter((s) => length(s) > 0);
  if (user.length === 0) {
    return fail("Nic nie narysowano. Zacznij od polecenia ruchu, na przykład „np 100”.");
  }

  const target = challenge.target();
  const tolerance = Math.max(1, 0.012 * diagonal(target));
  const comparison = compare(user, target, tolerance);

  if (!matches(comparison)) {
    // Is it the right shape, only somewhere else or at another size?
    const userSize = diagonal(user);
    const targetSize = diagonal(target);
    const scale = userSize > 0 ? targetSize / userSize : 1;
    if (Math.abs(scale - 1) > 0.06) {
      const scaled = map(user, (p) => [p[0] * scale, p[1] * scale, p[2] * scale]);
      if (matches(compare(scaled, target, tolerance))) {
        return fail(
          scale > 1
            ? "Kształt jest dobry, ale rysunek jest za mały. Sprawdź długości boków w treści zadania."
            : "Kształt jest dobry, ale rysunek jest za duży. Sprawdź długości boków w treści zadania.",
          comparison.missing,
          comparison.extra,
        );
      }
    }
    const from = bounds(user).min;
    const to = bounds(target).min;
    const moved = map(user, (p) => [p[0] - from[0] + to[0], p[1] - from[1] + to[1], p[2] - from[2] + to[2]]);
    if (matches(compare(moved, target, tolerance))) {
      return fail(
        "Kształt się zgadza, ale leży w innym miejscu. Zacznij rysować w punkcie startowym, skierowany do góry.",
        comparison.missing,
        comparison.extra,
      );
    }
    const gone = Math.round(comparison.missing * 100);
    const stray = Math.round(comparison.extra * 100);
    if (comparison.extra <= ALLOWED_SHARE) {
      return fail(`Brakuje części rysunku: narysowano około ${100 - gone}% wzoru.`, comparison.missing, comparison.extra);
    }
    if (comparison.missing <= ALLOWED_SHARE) {
      return fail(
        `Rysunek ma linie, których nie ma we wzorze (około ${stray}% rysunku).`,
        comparison.missing,
        comparison.extra,
      );
    }
    return fail(
      `Rysunek różni się od wzoru: brakuje około ${gone}% wzoru, a około ${stray}% rysunku leży poza nim.`,
      comparison.missing,
      comparison.extra,
    );
  }

  if (challenge.color && user.some((s) => s.color !== challenge.color)) {
    return fail(`Kształt jest dobry, ale kolor powinien być ${challenge.color}.`, 0, 0);
  }
  if (challenge.requires === "procedure" && !definesProcedure(source)) {
    return fail("Rysunek jest dobry, ale to zadanie trzeba rozwiązać procedurą („oto … już”).", 0, 0);
  }
  if (challenge.requires === "repeat" && !usesRepeat(source)) {
    return fail("Rysunek jest dobry, ale to zadanie trzeba rozwiązać pętlą „powtorz”.", 0, 0);
  }
  return { passed: true, reason: "Brawo! Rysunek zgadza się ze wzorem.", missing: comparison.missing, extra: comparison.extra };
}
