import { describe, expect, test } from "bun:test";
import {
  fit2d,
  gridStep,
  panBy2d,
  toScreen2d,
  fromScreen2d,
  zoomAt2d,
} from "../src/view/camera2d";
import {
  DEFAULT_CAMERA,
  PRESETS,
  clipToNearPlane,
  fit3d,
  orbit,
  pan3d,
  projector,
  zoom3d,
} from "../src/view/camera3d";
import { displayColor } from "../src/view/color";

const W = 800;
const H = 600;
const near = (a: number, b: number, eps = 1e-6) => expect(Math.abs(a - b)).toBeLessThanOrEqual(eps);

describe("2D camera", () => {
  test("maps +X to the right and +Y up the screen, with the camera centre in the middle", () => {
    const cam = { cx: 10, cy: 20, scale: 2 };
    expect(toScreen2d(cam, W, H, [10, 20])).toEqual([400, 300]);
    expect(toScreen2d(cam, W, H, [11, 20])).toEqual([402, 300]);
    expect(toScreen2d(cam, W, H, [10, 21])).toEqual([400, 298]);
  });

  test("fromScreen undoes toScreen", () => {
    const cam = { cx: -5, cy: 7, scale: 3.5 };
    const [sx, sy] = toScreen2d(cam, W, H, [12.5, -3]);
    const [x, y] = fromScreen2d(cam, W, H, sx, sy);
    near(x, 12.5);
    near(y, -3);
  });

  test("zooming around the cursor keeps the point under the cursor where it was", () => {
    const cam = { cx: 0, cy: 0, scale: 1 };
    const before = fromScreen2d(cam, W, H, 600, 100);
    const zoomed = zoomAt2d(cam, 2.5, 600, 100, W, H);
    expect(zoomed.scale).toBeCloseTo(2.5);
    const after = fromScreen2d(zoomed, W, H, 600, 100);
    near(after[0], before[0]);
    near(after[1], before[1]);
  });

  test("zoom stays within sensible limits", () => {
    expect(zoomAt2d({ cx: 0, cy: 0, scale: 1 }, 1e9, 0, 0, W, H).scale).toBeLessThanOrEqual(400);
    expect(zoomAt2d({ cx: 0, cy: 0, scale: 1 }, 1e-9, 0, 0, W, H).scale).toBeGreaterThanOrEqual(0.0005);
  });

  test("dragging moves the picture with the pointer", () => {
    const cam = panBy2d({ cx: 0, cy: 0, scale: 2 }, 40, -20);
    expect(toScreen2d(cam, W, H, [0, 0])).toEqual([440, 280]);
  });

  test("fit shows every point with room around, centred", () => {
    const points: [number, number][] = [[-50, -10], [250, 30], [100, 400]];
    const cam = fit2d(points, W, H, 40);
    for (const p of points) {
      const [sx, sy] = toScreen2d(cam, W, H, p);
      expect(sx).toBeGreaterThanOrEqual(40 - 1e-6);
      expect(sx).toBeLessThanOrEqual(W - 40 + 1e-6);
      expect(sy).toBeGreaterThanOrEqual(40 - 1e-6);
      expect(sy).toBeLessThanOrEqual(H - 40 + 1e-6);
    }
    near(cam.cx, 100);
    near(cam.cy, 195);
  });

  test("fitting nothing, or a single point, still gives a usable view", () => {
    expect(fit2d([], W, H, 40).scale).toBeGreaterThan(0);
    const one = fit2d([[5, 5]], W, H, 40);
    expect(Number.isFinite(one.scale)).toBe(true);
    expect(one.scale).toBeLessThan(100);
  });

  test("grid lines are never packed tighter than 36px, in steps of 1, 2 or 5", () => {
    for (const scale of [0.002, 0.05, 0.3, 1, 2.2, 7, 40, 300]) {
      const step = gridStep(scale);
      expect(step * scale).toBeGreaterThanOrEqual(36);
      expect([1, 2, 5]).toContain(Number((step / 10 ** Math.floor(Math.log10(step))).toFixed(6)));
    }
  });
});

describe("3D camera", () => {
  const view = (camera = DEFAULT_CAMERA) => projector(camera, W, H);

  test("the point the camera looks at lands in the middle of the screen", () => {
    const camera = { ...DEFAULT_CAMERA, target: [30, 40, 50] as [number, number, number] };
    const p = view(camera).project([30, 40, 50])!;
    near(p.x, W / 2);
    near(p.y, H / 2);
    near(p.depth, camera.distance, 1e-6);
  });

  test("from straight above, +X is right and +Y is up the screen, like the 2D plane", () => {
    const top = view({ ...DEFAULT_CAMERA, ...PRESETS.top, target: [0, 0, 0], distance: 500 });
    const o = top.project([0, 0, 0])!;
    const right = top.project([100, 0, 0])!;
    const up = top.project([0, 100, 0])!;
    expect(right.x).toBeGreaterThan(o.x);
    near(right.y, o.y, 1e-3);
    expect(up.y).toBeLessThan(o.y); // screen y grows downwards
    near(up.x, o.x, 1e-3);
    near(right.x - o.x, o.y - up.y, 1e-3); // equal scale on both axes
  });

  test("a flat drawing seen from above is the 2D drawing up to one uniform scale", () => {
    const top = view({ ...DEFAULT_CAMERA, ...PRESETS.top, target: [50, 50, 0], distance: 400 });
    const square: [number, number, number][] = [[0, 0, 0], [0, 100, 0], [100, 100, 0], [100, 0, 0]];
    const s = square.map((p) => top.project(p)!);
