export interface Camera2D {
  /** The world point in the middle of the view. */
  cx: number;
  cy: number;
  /** Pixels per world unit. */
  scale: number;
}

export const MIN_SCALE = 0.0005;
export const MAX_SCALE = 400;

const clampScale = (scale: number) => Math.min(MAX_SCALE, Math.max(MIN_SCALE, scale));

/** +X goes right and +Y goes up the screen, as on the page. */
export function toScreen2d(cam: Camera2D, w: number, h: number, [x, y]: [number, number]): [number, number] {
  return [w / 2 + (x - cam.cx) * cam.scale, h / 2 - (y - cam.cy) * cam.scale];
}

export function fromScreen2d(cam: Camera2D, w: number, h: number, sx: number, sy: number): [number, number] {
  return [cam.cx + (sx - w / 2) / cam.scale, cam.cy - (sy - h / 2) / cam.scale];
}

/** Zooms by `factor` keeping the world point under (sx, sy) where it is. */
export function zoomAt2d(cam: Camera2D, factor: number, sx: number, sy: number, w: number, h: number): Camera2D {
  const scale = clampScale(cam.scale * factor);
  const [px, py] = fromScreen2d(cam, w, h, sx, sy);
  return { scale, cx: px - (sx - w / 2) / scale, cy: py + (sy - h / 2) / scale };
}

/** Moves the picture by (dx, dy) screen pixels. */
export function panBy2d(cam: Camera2D, dx: number, dy: number): Camera2D {
  return { ...cam, cx: cam.cx - dx / cam.scale, cy: cam.cy + dy / cam.scale };
}

/** A view that shows all of `points` with `padding` pixels to spare; nothing to show gives a roomy default. */
export function fit2d(points: [number, number][], w: number, h: number, padding: number): Camera2D {
  const roomy = clampScale(Math.min(w, h) / 360);
  if (points.length === 0) return { cx: 0, cy: 0, scale: roomy };
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [x, y] of points) {
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
  }
  const bw = maxX - minX;
  const bh = maxY - minY;
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  if (bw < 1e-9 && bh < 1e-9) return { cx, cy, scale: roomy };
  const usableW = Math.max(1, w - 2 * padding);
  const usableH = Math.max(1, h - 2 * padding);
  const scale = Math.min(bw > 1e-9 ? usableW / bw : Infinity, bh > 1e-9 ? usableH / bh : Infinity);
  return { cx, cy, scale: clampScale(scale) };
}

/** The world distance between grid lines: 1, 2 or 5 times a power of ten, at least 36px apart. */
export function gridStep(scale: number): number {
  const raw = 36 / scale;
  const base = 10 ** Math.floor(Math.log10(raw));
  for (const m of [1, 2, 5, 10]) {
    if (m * base * scale >= 36 - 1e-9) return m * base;
  }
  return 10 * base;
}
