import type { Vec3 } from "../lang";

export interface Camera3D {
  /** The point the camera orbits and looks at. */
  target: Vec3;
  /** Degrees around the vertical axis; 0 looks along +Y with +X to the right. */
  azimuth: number;
  /** Degrees above the ground plane. */
  elevation: number;
  distance: number;
  /** Vertical field of view, in degrees. */
  fov: number;
}

export const DEFAULT_CAMERA: Camera3D = { target: [0, 0, 0], azimuth: 28, elevation: 24, distance: 400, fov: 40 };

export const PRESETS = {
  perspective: { azimuth: 28, elevation: 24 },
  /** The same view as the flat 2D plane: +X right, +Y up the screen. */
  top: { azimuth: 0, elevation: 90 },
  front: { azimuth: 0, elevation: 0 },
  side: { azimuth: 90, elevation: 0 },
} as const;

const RAD = Math.PI / 180;
const MAX_ELEVATION = 89;

interface Basis {
  position: Vec3;
  forward: Vec3;
  right: Vec3;
  up: Vec3;
}

function basis(camera: Camera3D): Basis {
  const az = camera.azimuth * RAD;
  const el = camera.elevation * RAD;
  const toCamera: Vec3 = [Math.sin(az) * Math.cos(el), -Math.cos(az) * Math.cos(el), Math.sin(el)];
  const forward: Vec3 = [-toCamera[0], -toCamera[1], -toCamera[2]];
  const right: Vec3 = [Math.cos(az), Math.sin(az), 0];
  const up: Vec3 = [
    right[1] * forward[2] - right[2] * forward[1],
    right[2] * forward[0] - right[0] * forward[2],
    right[0] * forward[1] - right[1] * forward[0],
  ];
  const position: Vec3 = [
    camera.target[0] + toCamera[0] * camera.distance,
    camera.target[1] + toCamera[1] * camera.distance,
    camera.target[2] + toCamera[2] * camera.distance,
  ];
  return { position, forward, right, up };
}

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

export interface Projected {
  x: number;
  y: number;
  /** Distance in front of the camera along its view direction. */
  depth: number;
}

export interface Projector {
  /** Screen position of a world point, or null when it is behind the near plane. */
  project(p: Vec3): Projected | null;
  /** Depth of a world point (negative behind the camera). */
  depthOf(p: Vec3): number;
  /** Pixels per world unit at the given depth. */
  pixelsPerUnit(depth: number): number;
  near: number;
  basis: Basis;
}

export function projector(camera: Camera3D, w: number, h: number): Projector {
  const b = basis(camera);
  const focal = h / 2 / Math.tan((camera.fov * RAD) / 2);
  const near = Math.max(0.1, camera.distance * 0.02);
  const depthOf = (p: Vec3) => dot([p[0] - b.position[0], p[1] - b.position[1], p[2] - b.position[2]], b.forward);
  return {
    near,
    basis: b,
    depthOf,
    pixelsPerUnit: (depth) => focal / depth,
    project(p) {
      const v: Vec3 = [p[0] - b.position[0], p[1] - b.position[1], p[2] - b.position[2]];
      const depth = dot(v, b.forward);
      if (depth < near) return null;
      return { x: w / 2 + (dot(v, b.right) / depth) * focal, y: h / 2 - (dot(v, b.up) / depth) * focal, depth };
    },
  };
}

/** Trims a segment to the part in front of the near plane; null when none of it is. */
export function clipToNearPlane(p: Projector, a: Vec3, b: Vec3): [Vec3, Vec3] | null {
  const da = p.depthOf(a);
  const db = p.depthOf(b);
  if (da >= p.near && db >= p.near) return [a, b];
  if (da < p.near && db < p.near) return null;
  const t = (p.near - da) / (db - da);
  const cut: Vec3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
  return da < p.near ? [cut, b] : [a, cut];
}

function wrap(degrees: number): number {
  return ((((degrees + 180) % 360) + 360) % 360) - 180;
}

/** Drag by (dx, dy) pixels to turn the scene: right turns it right, down shows more of the top. */
export function orbit(camera: Camera3D, dx: number, dy: number): Camera3D {
  return {
    ...camera,
    azimuth: wrap(camera.azimuth - dx * 0.4),
    elevation: Math.min(MAX_ELEVATION, Math.max(-MAX_ELEVATION, camera.elevation + dy * 0.4)),
  };
}

/** Moves the scene by (dx, dy) screen pixels by sliding the target the other way. */
export function pan3d(camera: Camera3D, dx: number, dy: number, viewportHeight: number): Camera3D {
  const b = basis(camera);
  const unitsPerPixel = (2 * camera.distance * Math.tan((camera.fov * RAD) / 2)) / viewportHeight;
  return {
    ...camera,
    target: [
      camera.target[0] - b.right[0] * dx * unitsPerPixel + b.up[0] * dy * unitsPerPixel,
      camera.target[1] - b.right[1] * dx * unitsPerPixel + b.up[1] * dy * unitsPerPixel,
      camera.target[2] - b.right[2] * dx * unitsPerPixel + b.up[2] * dy * unitsPerPixel,
    ],
  };
}

export function zoom3d(camera: Camera3D, factor: number): Camera3D {
  return { ...camera, distance: Math.min(1e6, Math.max(1, camera.distance * factor)) };
}

/** Frames the points, looking from the camera's current direction. */
export function fit3d(camera: Camera3D, points: Vec3[], w: number, h: number): Camera3D {
  let target: Vec3 = [0, 0, 0];
  let radius = 150;
  if (points.length > 0) {
    const min: Vec3 = [Infinity, Infinity, Infinity];
    const max: Vec3 = [-Infinity, -Infinity, -Infinity];
    for (const p of points) {
      for (let i = 0; i < 3; i++) {
        min[i] = Math.min(min[i]!, p[i]!);
        max[i] = Math.max(max[i]!, p[i]!);
      }
    }
    target = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2];
    radius = Math.max(
      10,
      ...points.map((p) => Math.hypot(p[0] - target[0], p[1] - target[1], p[2] - target[2])),
    );
  }
  const halfV = Math.tan((camera.fov * RAD) / 2);
  const halfAngle = Math.atan(halfV * Math.min(1, w / h));
  return { ...camera, target, distance: Math.min(1e6, (radius / Math.sin(halfAngle)) * 1.12) };
}
