type Child = Node | string | number | null | undefined | false | Child[];

export interface Props {
  class?: string;
  /** Becomes `textContent`; use children for anything richer. */
  text?: string;
  attrs?: Record<string, string | number | boolean | undefined | null>;
  on?: { [K in keyof HTMLElementEventMap]?: (event: HTMLElementEventMap[K]) => void };
  style?: Partial<CSSStyleDeclaration>;
}

function append(parent: Node, child: Child): void {
  if (child === null || child === undefined || child === false) return;
  if (Array.isArray(child)) {
    for (const c of child) append(parent, c);
  } else if (child instanceof Node) {
    parent.appendChild(child);
  } else {
    parent.appendChild(document.createTextNode(String(child)));
  }
}

/** Creates an element: `h("button", { class: "btn", on: { click } }, "Uruchom")`. */
export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: Props = {},
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  if (props.class) el.className = props.class;
  if (props.text !== undefined) el.textContent = props.text;
  if (props.attrs) {
    for (const [name, value] of Object.entries(props.attrs)) {
      if (value === undefined || value === null || value === false) continue;
      el.setAttribute(name, value === true ? "" : String(value));
    }
  }
  if (props.style) Object.assign(el.style, props.style);
  if (props.on) {
    for (const [type, handler] of Object.entries(props.on)) {
      el.addEventListener(type, handler as EventListener);
    }
  }
  for (const child of children) append(el, child);
  return el;
}

export function clear(el: Element): void {
  while (el.firstChild) el.removeChild(el.firstChild);
}

let counter = 0;
/** A document-unique id for wiring labels and descriptions. */
export function uid(prefix = "id"): string {
  return `${prefix}-${++counter}`;
}
