import { describe, expect, test } from "bun:test";
import { highlight } from "../src/editor/highlight";

const kinds = (source: string) =>
  highlight(source)
    .filter((s) => s.kind !== "space")
    .map((s) => [s.text, s.kind]);

describe("editor: syntax highlighting", () => {
  test("the spans always add up to the source, so the overlay lines up with the text", () => {
    const samples = [
      "",
      "np 100\n  pw 90 ; skręt\n",
      'kolor "#16866a" powtorz 4 [np 10]\r\n',
      "oto gałąź ma: dł, kąt\n  jeśli dł < 6 [stop]\njuż\n",
      "np 1e3 @ 🐢 \"bez końca\n\t\t",
      "-+*/()[]<>=<=>=<>,:",
    ];
    for (const sample of samples) expect(highlight(sample).map((s) => s.text).join("")).toBe(sample);
  });

  test("commands, numbers, names, strings, comments and brackets each get their own kind", () => {
    expect(kinds('niech bok 40 ; mały\npowtorz 4 [np bok pw 90]\nkolor "#16866a"')).toEqual([
      ["niech", "command"],
      ["bok", "name"],
      ["40", "number"],
      ["; mały", "comment"],
      ["powtorz", "command"],
      ["4", "number"],
      ["[", "bracket"],
      ["np", "command"],
      ["bok", "name"],
      ["pw", "command"],
      ["90", "number"],
      ["]", "bracket"],
      ["kolor", "command"],
      ['"#16866a"', "string"],
    ]);
  });

  test("aliases, accents and letter case are all commands", () => {
    for (const word of ["NAPRZÓD", "Forward", "jeśli", "JESLI", "czyść", "opuść", "przechylprawo"]) {
      expect(kinds(word)).toEqual([[word, "command"]]);
    }
  });

  test("operators, parentheses and comparisons are told apart from brackets", () => {
    expect(kinds("(1+2)*3<=4")).toEqual([
      ["(", "paren"],
      ["1", "number"],
      ["+", "operator"],
      ["2", "number"],
      [")", "paren"],
      ["*", "operator"],
      ["3", "number"],
      ["<=", "operator"],
      ["4", "number"],
    ]);
  });

  test("procedure definitions: keywords, the procedure's name wherever it is used, parameters as names", () => {
    const source = "oto kwadrat ma: bok\n  powtorz 4 [np :bok pw 90]\njuż\nkwadrat 30";
    expect(kinds(source)).toEqual([
      ["oto", "keyword"],
      ["kwadrat", "procedure"],
      ["ma", "keyword"],
      [":", "punct"],
      ["bok", "name"],
      ["powtorz", "command"],
      ["4", "number"],
      ["[", "bracket"],
      ["np", "command"],
      [":bok", "name"],
      ["pw", "command"],
      ["90", "number"],
      ["]", "bracket"],
      ["już", "keyword"],
      ["kwadrat", "procedure"],
      ["30", "number"],
    ]);
  });

  test("nrpowt is a keyword value; malformed numbers and unterminated strings are marked", () => {
    expect(kinds("np nrpowt")[1]).toEqual(["nrpowt", "keyword"]);
    expect(kinds("np 1e3")[1]).toEqual(["1e3", "error"]);
    expect(kinds('kolor "#12')[1]).toEqual(['"#12', "error"]);
  });

  test("a colour literal carries its colour so the editor can show it", () => {
    const [swatch] = highlight('"#C1763D"');
    expect(swatch).toMatchObject({ kind: "string", color: "#c1763d" });
    expect(highlight('"nie kolor"')[0]!.color).toBeUndefined();
  });

  test("a very long program is highlighted in one pass without trouble", () => {
    const source = "np 1 pw 90\n".repeat(4500);
    expect(highlight(source).map((s) => s.text).join("")).toBe(source);
  });
});
