import { nameOf } from "../lang/lexer";
import { commandFor, isDefineWord, isEndWord, isRepcount } from "../lang/vocabulary";

export type SpanKind =
  | "command"
  | "keyword"
  | "procedure"
  | "name"
  | "number"
  | "string"
  | "comment"
  | "bracket"
  | "paren"
  | "operator"
  | "punct"
  | "space"
  | "error";

export interface Span {
  text: string;
  kind: SpanKind;
  /** For a colour literal such as "#16866a": the colour, lowercase. */
  color?: string;
}

const TOKEN = new RegExp(
  [
    String.raw`(?<comment>;[^\n]*)`,
    String.raw`(?<string>"[^"\n]*"?)`,
    String.raw`(?<space>\s+)`,
    String.raw`(?<numberish>[\p{N}.][\p{L}\p{M}\p{N}_.]*)`,
    String.raw`(?<legacy>:[\p{L}\p{M}\p{N}_]+)`,
    String.raw`(?<word>[\p{L}\p{M}_][\p{L}\p{M}\p{N}_]*)`,
    String.raw`(?<compare><=|>=|<>|<|>|=)`,
    String.raw`(?<operator>[+\-*/])`,
    String.raw`(?<bracket>[\[\]])`,
    String.raw`(?<paren>[()])`,
    String.raw`(?<punct>[,:])`,
    String.raw`(?<other>[\s\S])`,
  ].join("|"),
  "gu",
);

const NUMBER = /^(?:\d+(?:\.\d+)?|\.\d+)$/;
const COLOR = /^"#([0-9a-fA-F]{6})"$/;

/** The names of procedures defined anywhere in the text (`oto name …` at the start of a line). */
function procedureNames(source: string): Set<string> {
  const names = new Set<string>();
  for (const match of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}\p{M}_][\p{L}\p{M}\p{N}_]*)/gimu)) {
    names.add(nameOf(match[1]!));
  }
  return names;
}

/**
 * Splits the program into spans for colouring. Never throws, and the spans always join back into
 * exactly the source, so a coloured copy can sit under the textarea character for character.
 */
export function highlight(source: string): Span[] {
  const procedures = procedureNames(source);
  const spans: Span[] = [];
  let lastWord: { text: string; end: number } | null = null;
  for (const match of source.matchAll(TOKEN)) {
    const text = match[0];
    const group = Object.entries(match.groups!).find(([, v]) => v !== undefined)![0];
    const start = match.index!;
    let kind: SpanKind;
    let color: string | undefined;
    switch (group) {
      case "comment":
        kind = "comment";
        break;
      case "string": {
        const m = COLOR.exec(text);
        kind = m || /^"[^"]*"$/.test(text) ? "string" : "error";
        if (m) color = `#${m[1]!.toLowerCase()}`;
        break;
      }
      case "space":
        kind = "space";
        break;
      case "numberish":
        kind = NUMBER.test(text) ? "number" : "error";
        break;
      case "legacy":
        kind = "name";
        break;
      case "word": {
        const lower = nameOf(text);
        if (isDefineWord(text) || isEndWord(text) || isRepcount(text)) kind = "keyword";
        else if (lower === "ma" && source[start + text.length] === ":") kind = "keyword";
        else if (commandFor(text)) kind = "command";
        else if (procedures.has(lower)) kind = "procedure";
        else kind = "name";
        break;
      }
      case "compare":
      case "operator":
        kind = "operator";
        break;
      case "bracket":
        kind = "bracket";
        break;
      case "paren":
        kind = "paren";
        break;
      case "punct":
        kind = "punct";
        break;
      default:
        kind = "error";
    }
    spans.push(color ? { text, kind, color } : { text, kind });
    lastWord = group === "word" ? { text, end: start + text.length } : lastWord;
  }
  void lastWord;
  return spans;
}
EOF
