import type { Theme } from "./color";

/** Colours the canvas needs, taken from the page's CSS variables so both themes stay in one place. */
export interface Palette {
  theme: Theme;
  bg: string;
  gridMinor: string;
  gridMajor: string;
  axisX: string;
  axisY: string;
  axisZ: string;
  label: string;
  labelHalo: string;
  route: string;
  turtle: string;
  turtleEdge: string;
  ink: string;
}

const LIGHT: Palette = {
  theme: "light",
  bg: "#fbfcfe",
  gridMinor: "#e6ebf2",
  gridMajor: "#d3dbe6",
  axisX: "#c0392b",
  axisY: "#2b8a3e",
  axisZ: "#2f6fd6",
  label: "#435368",
  labelHalo: "#fbfcfe",
  route: "#8a3ab9",
  turtle: "#12468e",
  turtleEdge: "#ffffff",
  ink: "#121c2a",
};

const DARK: Palette = {
  theme: "dark",
  bg: "#0e141c",
  gridMinor: "#19222d",
  gridMajor: "#243040",
  axisX: "#ff7b6b",
  axisY: "#58c46f",
  axisZ: "#6aa4ff",
  label: "#aab7c7",
  labelHalo: "#0e141c",
  route: "#c08ae8",
  turtle: "#8db8ff",
  turtleEdge: "#0e141c",
  ink: "#e8eef6",
};

export const DEFAULT_PALETTES: Record<Theme, Palette> = { light: LIGHT, dark: DARK };

const VARIABLES: Record<Exclude<keyof Palette, "theme">, string> = {
  bg: "--canvas",
  gridMinor: "--grid-minor",
  gridMajor: "--grid-major",
  axisX: "--axis-x",
  axisY: "--axis-y",
  axisZ: "--axis-z",
  label: "--canvas-label",
  labelHalo: "--canvas",
  route: "--route",
  turtle: "--turtle",
  turtleEdge: "--turtle-edge",
  ink: "--ink",
};

/** Reads the palette from the element's computed style; falls back to the built-in values. */
export function readPalette(element: Element, theme: Theme): Palette {
  const fallback = DEFAULT_PALETTES[theme];
  if (typeof getComputedStyle !== "function") return fallback;
  const style = getComputedStyle(element);
  const palette: Palette = { ...fallback };
  for (const [key, variable] of Object.entries(VARIABLES)) {
    const value = style.getPropertyValue(variable).trim();
    if (value) (palette as unknown as Record<string, string>)[key] = value;
  }
  return palette;
}
