import type { Segment, TurtleView, Vec3 } from "../lang";
import { fromScreen2d, gridStep, toScreen2d, type Camera2D } from "./camera2d";
import { clipToNearPlane, projector, type Camera3D } from "./camera3d";
import { displayColor } from "./color";
import type { Palette } from "./palette";

export interface Scene {
  segments: readonly Segment[];
  turtle?: TurtleView | null;
  /** The target of a challenge, drawn as a dashed route beneath the user's drawing. */
  ghost?: readonly Segment[];
}

export interface DrawOptions {
  grid: boolean;
  axes: boolean;
  turtle: boolean;
}

const FONT = '600 11px "Barlow", system-ui, sans-serif';

function label(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, p: Palette, align: CanvasTextAlign = "left") {
  ctx.font = FONT;
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.lineJoin = "round";
  ctx.lineWidth = 3;
  ctx.strokeStyle = p.labelHalo;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = p.label;
  ctx.fillText(text, x, y);
}

function formatTick(value: number): string {
  const rounded = Math.abs(value) < 1e-9 ? 0 : value;
  return Number.isInteger(rounded) ? String(rounded) : String(Number(rounded.toPrecision(6)));
}

/** Paints runs of equal colour and width as one path, which keeps drawing order and costs far fewer strokes. */
function strokeSegments(
  ctx: CanvasRenderingContext2D,
  segments: readonly Segment[],
  place: (s: Segment) => [number, number, number, number] | null,
  theme: Palette["theme"],
  widthScale: number,
) {
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  let color = "";
  let width = -1;
  let open = false;
  for (const segment of segments) {
    const at = place(segment);
    if (!at) continue;
    if (segment.color !== color || segment.width !== width) {
      if (open) ctx.stroke();
      color = segment.color;
      width = segment.width;
      ctx.beginPath();
      ctx.strokeStyle = displayColor(color, theme);
      ctx.lineWidth = Math.max(1, width * widthScale);
      open = true;
    }
    ctx.moveTo(at[0], at[1]);
    ctx.lineTo(at[2], at[3]);
  }
  if (open) ctx.stroke();
}

function drawGhost2d(ctx: CanvasRenderingContext2D, ghost: readonly Segment[], cam: Camera2D, w: number, h: number, p: Palette) {
  ctx.save();
  ctx.setLineDash([7, 5]);
  ctx.lineCap = "round";
  ctx.strokeStyle = p.route;
  ctx.lineWidth = 2.5;
  ctx.globalAlpha = 0.85;
  ctx.beginPath();
  for (const s of ghost) {
    const a = toScreen2d(cam, w, h, [s.from[0], s.from[1]]);
    const b = toScreen2d(cam, w, h, [s.to[0], s.to[1]]);
    ctx.moveTo(a[0], a[1]);
    ctx.lineTo(b[0], b[1]);
  }
  ctx.stroke();
  ctx.restore();
}

export function draw2d(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  cam: Camera2D,
  scene: Scene,
  p: Palette,
  options: DrawOptions,
): void {
  ctx.fillStyle = p.bg;
  ctx.fillRect(0, 0, w, h);

  if (options.grid) {
    const step = gridStep(cam.scale);
    const [x0, y1] = fromScreen2d(cam, w, h, 0, 0);
    const [x1, y0] = fromScreen2d(cam, w, h, w, h);
    ctx.lineWidth = 1;
    const first = (v: number) => Math.floor(v / step) * step;
    for (let major = 0; major < 2; major++) {
      ctx.strokeStyle = major ? p.gridMajor : p.gridMinor;
      ctx.beginPath();
      let n = 0;
      for (let x = first(x0); x <= x1 && n < 600; x += step, n++) {
        const isMajor = Math.abs(Math.round(x / step) % 5) === 0;
        if (isMajor !== (major === 1)) continue;
        const sx = Math.round(toScreen2d(cam, w, h, [x, 0])[0]) + 0.5;
        ctx.moveTo(sx, 0);
        ctx.lineTo(sx, h);
      }
      n = 0;
      for (let y = first(y0); y <= y1 && n < 600; y += step, n++) {
        const isMajor = Math.abs(Math.round(y / step) % 5) === 0;
        if (isMajor !== (major === 1)) continue;
        const sy = Math.round(toScreen2d(cam, w, h, [0, y])[1]) + 0.5;
        ctx.moveTo(0, sy);
        ctx.lineTo(w, sy);
      }
      ctx.stroke();
    }
  }

  const [ox, oy] = toScreen2d(cam, w, h, [0, 0]);
  if (options.axes) {
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.9;
    ctx.strokeStyle = p.axisX;
    ctx.beginPath();
    ctx.moveTo(0, oy);
    ctx.lineTo(w, oy);
    ctx.stroke();
    ctx.strokeStyle = p.axisY;
    ctx.beginPath();
    ctx.moveTo(ox, 0);
    ctx.lineTo(ox, h);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // numbers at the major lines, kept on screen next to the axes
    const step = gridStep(cam.scale) * 5;
    const [lx0, ly1] = fromScreen2d(cam, w, h, 0, 0);
    const [lx1, ly0] = fromScreen2d(cam, w, h, w, h);
    const labelY = Math.min(h - 10, Math.max(12, oy + 11));
    const labelX = Math.min(w - 6, Math.max(6, ox - 6));
    let n = 0;
    for (let x = Math.ceil(lx0 / step) * step; x <= lx1 && n < 60; x += step, n++) {
      if (Math.abs(x) < step / 2) continue;
      label(ctx, formatTick(x), toScreen2d(cam, w, h, [x, 0])[0], labelY, p, "center");
    }
    n = 0;
    for (let y = Math.ceil(ly0 / step) * step; y <= ly1 && n < 60; y += step, n++) {
      if (Math.abs(y) < step / 2) continue;
      const align = ox > w - 40 ? "right" : "right";
      label(ctx, formatTick(y), labelX, toScreen2d(cam, w, h, [0, y])[1], p, align);
    }
    label(ctx, "X", Math.min(w - 12, w - 14), Math.min(h - 10, Math.max(12, oy - 12)), p, "center");
    label(ctx, "Y", Math.min(w - 14, Math.max(14, ox + 12)), 12, p, "center");
  }

  // the origin, always visible
  ctx.lineWidth = 1.75;
  ctx.strokeStyle = p.ink;
  ctx.fillStyle = p.bg;
  ctx.beginPath();
  ctx.arc(ox, oy, 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ox - 8, oy);
  ctx.lineTo(ox + 8, oy);
  ctx.moveTo(ox, oy - 8);
  ctx.lineTo(ox, oy + 8);
  ctx.stroke();

  if (scene.ghost && scene.ghost.length > 0) drawGhost2d(ctx, scene.ghost, cam, w, h, p);

  strokeSegments(
    ctx,
    scene.segments,
    (s) => {
      const a = toScreen2d(cam, w, h, [s.from[0], s.from[1]]);
      const b = toScreen2d(cam, w, h, [s.to[0], s.to[1]]);
      return [a[0], a[1], b[0], b[1]];
    },
    p.theme,
    1,
  );

  if (options.turtle && scene.turtle) drawTurtle2d(ctx, w, h, cam, scene.turtle, p);
}

function drawTurtle2d(ctx: CanvasRenderingContext2D, w: number, h: number, cam: Camera2D, t: TurtleView, p: Palette) {
  const [x, y] = toScreen2d(cam, w, h, [t.position[0], t.position[1]]);
  const angle = Math.atan2(-t.heading[1], t.heading[0]);
  const size = 11;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(size * 1.15, 0);
  ctx.lineTo(-size * 0.8, size * 0.72);
  ctx.lineTo(-size * 0.4, 0);
  ctx.lineTo(-size * 0.8, -size * 0.72);
  ctx.closePath();
  ctx.lineJoin = "round";
  ctx.lineWidth = 3;
  ctx.strokeStyle = p.turtleEdge;
  ctx.stroke();
  ctx.fillStyle = t.penDown ? p.turtle : p.turtleEdge;
  ctx.fill();
  ctx.lineWidth = 1.75;
  ctx.strokeStyle = p.turtle;
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------

function niceStep(raw: number): number {
  const base = 10 ** Math.floor(Math.log10(raw));
  for (const m of [1, 2, 5, 10]) if (m * base >= raw) return m * base;
  return 10 * base;
}

export function draw3d(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  cam: Camera3D,
  scene: Scene,
  p: Palette,
  options: DrawOptions,
): void {
  ctx.fillStyle = p.bg;
  ctx.fillRect(0, 0, w, h);
  const view = projector(cam, w, h);
  const line = (a: Vec3, b: Vec3, style: string, width: number, dash: number[] = []) => {
    const cut = clipToNearPlane(view, a, b);
    if (!cut) return;
    const pa = view.project(cut[0]);
    const pb = view.project(cut[1]);
    if (!pa || !pb) return;
    ctx.setLineDash(dash);
    ctx.strokeStyle = style;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(pa.x, pa.y);
    ctx.lineTo(pb.x, pb.y);
    ctx.stroke();
    ctx.setLineDash([]);
  };

  const step = niceStep(cam.distance / 7);
  const half = step * 10;
  if (options.grid) {
    ctx.lineCap = "butt";
    for (let i = -10; i <= 10; i++) {
      const major = i % 5 === 0;
      const style = major ? p.gridMajor : p.gridMinor;
      line([i * step, -half, 0], [i * step, half, 0], style, 1);
      line([-half, i * step, 0], [half, i * step, 0], style, 1);
    }
  }
  if (options.axes) {
    ctx.lineCap = "round";
    const reach = half;
    line([-reach, 0, 0], [0, 0, 0], p.axisX, 1.25, [4, 4]);
    line([0, -reach, 0], [0, 0, 0], p.axisY, 1.25, [4, 4]);
    line([0, 0, -reach], [0, 0, 0], p.axisZ, 1.25, [4, 4]);
    line([0, 0, 0], [reach, 0, 0], p.axisX, 2);
    line([0, 0, 0], [0, reach, 0], p.axisY, 2);
    line([0, 0, 0], [0, 0, reach], p.axisZ, 2);
    for (const [text, tip, color] of [
      ["X", [reach, 0, 0], p.axisX],
      ["Y", [0, reach, 0], p.axisY],
      ["Z", [0, 0, reach], p.axisZ],
    ] as [string, Vec3, string][]) {
      const at = view.project(tip);
      if (!at) continue;
      ctx.font = '700 12px "Barlow", system-ui, sans-serif';
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineWidth = 3;
      ctx.strokeStyle = p.labelHalo;
      ctx.strokeText(text, at.x + 10, at.y - 8);
      ctx.fillStyle = color;
      ctx.fillText(text, at.x + 10, at.y - 8);
    }
    const o = view.project([0, 0, 0]);
    if (o) {
