      ctx.strokeStyle = p.ink;
      ctx.fillStyle = p.bg;
      ctx.beginPath();
      ctx.arc(o.x, o.y, 4.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  if (scene.ghost && scene.ghost.length > 0) {
    ctx.lineCap = "round";
    ctx.globalAlpha = 0.85;
    for (const s of scene.ghost) line(s.from, s.to, p.route, 2.5, [7, 5]);
    ctx.globalAlpha = 1;
  }

  interface Placed {
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    depth: number;
    color: string;
    width: number;
  }
  const placed: Placed[] = [];
  for (const s of scene.segments) {
    const cut = clipToNearPlane(view, s.from, s.to);
    if (!cut) continue;
    const a = view.project(cut[0]);
    const b = view.project(cut[1]);
    if (!a || !b) continue;
    placed.push({ x1: a.x, y1: a.y, x2: b.x, y2: b.y, depth: (a.depth + b.depth) / 2, color: s.color, width: s.width });
  }
  placed.sort((l, r) => r.depth - l.depth);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const reference = cam.distance;
  for (const s of placed) {
    const scale = Math.min(1.9, Math.max(0.7, reference / s.depth));
    ctx.globalAlpha = 1 - 0.5 * Math.min(1, Math.max(0, (s.depth - reference) / reference));
    ctx.strokeStyle = displayColor(s.color, p.theme);
    ctx.lineWidth = Math.max(1, s.width * scale);
    ctx.beginPath();
    ctx.moveTo(s.x1, s.y1);
    ctx.lineTo(s.x2, s.y2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  if (options.turtle && scene.turtle) drawTurtle3d(ctx, view, scene.turtle, cam, p);
}

function drawTurtle3d(ctx: CanvasRenderingContext2D, view: ReturnType<typeof projector>, t: TurtleView, cam: Camera3D, p: Palette) {
  const length = Math.max(3, cam.distance * 0.045);
  const at = (f: number, r: number, u: number): Vec3 => [
    t.position[0] + t.heading[0] * f * length + t.right[0] * r * length + t.up[0] * u * length,
    t.position[1] + t.heading[1] * f * length + t.right[1] * r * length + t.up[1] * u * length,
    t.position[2] + t.heading[2] * f * length + t.right[2] * r * length + t.up[2] * u * length,
  ];
  const tip = at(1.2, 0, 0);
  const left = at(-0.7, -0.7, 0);
  const right = at(-0.7, 0.7, 0);
  const top = at(-0.5, 0, 0.6);
  const faces: { points: Vec3[]; fill: string }[] = [
    { points: [tip, left, right], fill: p.turtle },
    { points: [tip, right, top], fill: "#ffd21f" },
    { points: [tip, top, left], fill: "#f2b705" },
    { points: [left, right, top], fill: p.turtle },
  ];
  const drawn = faces
