    const dpr = Math.min(3, typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1);
    if (width === this.width && height === this.height && dpr === this.dpr) return;
    this.width = width;
    this.height = height;
    this.dpr = dpr;
    this.canvas.width = Math.max(1, Math.round(width * dpr));
    this.canvas.height = Math.max(1, Math.round(height * dpr));
    if (this.needsFit || this.following) this.fit(true);
    this.invalidate();
  }

  /** Measures the container now (used after the page becomes visible). */
  refresh(): void {
    this.resize();
    this.invalidate();
  }

  invalidate(): void {
    if (this.frame || !this.ctx) return;
    const run = () => {
      this.frame = 0;
      this.paint();
    };
    this.frame = typeof requestAnimationFrame === "function" ? requestAnimationFrame(run) : (setTimeout(run, 0) as unknown as number);
  }

  private get drawOptions(): DrawOptions {
    return { grid: this.options.decorations, axes: this.options.decorations, turtle: this.options.decorations };
  }

  private paint(): void {
    const ctx = this.ctx;
    if (!ctx || this.width === 0 || this.height === 0) return;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.setLineDash([]);
    if (this.mode === "2d") draw2d(ctx, this.width, this.height, this.cam2, this.scene, this.palette, this.drawOptions);
    else draw3d(ctx, this.width, this.height, this.cam3, this.scene, this.palette, this.drawOptions);
  }

  // ---- export -------------------------------------------------------------------------

  /**
   * The drawing as a PNG on a white page: the whole drawing, framed, without the turtle or the grid,
   * in the colours the program chose (never the dark-theme lift).
   */
  async exportPng(maxSide = 1600): Promise<Blob | null> {
    if (this.scene.segments.length === 0) return null;
    const ratio = Math.max(0.6, Math.min(1.6, (this.width || 4) / (this.height || 3)));
    const w = ratio >= 1 ? maxSide : Math.round(maxSide * ratio);
    const hh = ratio >= 1 ? Math.round(maxSide / ratio) : maxSide;
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = hh;
    const ctx = canvas.getContext("2d");
    if (!ctx) return null;
    const palette = readPalette(document.documentElement, "light");
    const scene: Scene = { segments: this.scene.segments };
    const options: DrawOptions = { grid: false, axes: false, turtle: false };
    const points = pointsOf(scene, this.mode, false);
    const scale = w / Math.max(1, this.width || w);
    if (this.mode === "2d") {
      const cam = fit2d(points.map((p) => [p[0], p[1]] as [number, number]), w, hh, 60 * scale);
      draw2d(ctx, w, hh, cam, scale > 1 ? scaleScene(scene, 1) : scene, palette, options);
    } else {
      const cam = fit3d(this.cam3, points, w, hh);
      draw3d(ctx, w, hh, cam, scene, palette, options);
    }
    return new Promise((resolve) => canvas.toBlob((blob) => resolve(blob), "image/png"));
  }

  // ---- pointer, wheel and keyboard ----------------------------------------------------

  private attachInteraction(): void {
    const el = this.element;
    el.tabIndex = 0;
    el.setAttribute("aria-roledescription", "widok rysunku");
    el.addEventListener("pointerdown", (e) => {
      el.focus({ preventScroll: true });
      this.pointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
      try {
        el.setPointerCapture(e.pointerId);
      } catch {
        // some environments cannot capture; dragging still works while the pointer stays inside
      }
      this.lastPinch = null;
    });
    el.addEventListener("pointermove", (e) => this.onPointerMove(e));
    const release = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      this.lastPinch = null;
    };
    el.addEventListener("pointerup", release);
    el.addEventListener("pointercancel", release);
    el.addEventListener("lostpointercapture", release);
    el.addEventListener("contextmenu", (e) => {
      if (this.mode === "3d") e.preventDefault();
    });
    el.addEventListener(
      "wheel",
      (e) => {
        e.preventDefault();
        const unit = e.deltaMode === 1 ? 33 : e.deltaMode === 2 ? 400 : 1;
        const factor = Math.exp(-e.deltaY * unit * (e.ctrlKey ? 0.012 : WHEEL_ZOOM));
        this.zoomAt(factor, e.offsetX, e.offsetY);
      },
      { passive: false },
    );
    el.addEventListener("keydown", (e) => this.onKey(e));
    el.addEventListener("dblclick", () => this.fit());
  }

  private zoomAt(factor: number, x: number, y: number): void {
    this.navigated();
    if (this.mode === "2d") this.cam2 = zoomAt2d(this.cam2, factor, x, y, this.width, this.height);
    else this.cam3 = zoom3d(this.cam3, 1 / factor);
    this.invalidate();
  }

  private onPointerMove(e: PointerEvent): void {
    const previous = this.pointers.get(e.pointerId);
    if (!previous) return;
    const current = { x: e.offsetX, y: e.offsetY };
    this.pointers.set(e.pointerId, current);
    if (this.pointers.size === 1) {
      const dx = current.x - previous.x;
      const dy = current.y - previous.y;
      if (dx === 0 && dy === 0) return;
      this.navigated();
      if (this.mode === "2d") {
        this.cam2 = panBy2d(this.cam2, dx, dy);
      } else if (e.shiftKey || e.buttons === 2 || e.buttons === 4) {
        this.cam3 = pan3d(this.cam3, dx, dy, this.height);
      } else {
        this.cam3 = orbit(this.cam3, dx, dy);
      }
      this.invalidate();
    } else if (this.pointers.size === 2) {
      const [a, b] = [...this.pointers.values()] as [{ x: number; y: number }, { x: number; y: number }];
      const distance = Math.hypot(a.x - b.x, a.y - b.y);
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      if (this.lastPinch && this.lastPinch.distance > 0) {
        this.navigated();
        const factor = distance / this.lastPinch.distance;
        const dx = mid.x - this.lastPinch.x;
        const dy = mid.y - this.lastPinch.y;
        if (this.mode === "2d") {
          this.cam2 = panBy2d(zoomAt2d(this.cam2, factor, mid.x, mid.y, this.width, this.height), dx, dy);
        } else {
          this.cam3 = pan3d(zoom3d(this.cam3, 1 / factor), dx, dy, this.height);
        }
        this.invalidate();
      }
      this.lastPinch = { distance, x: mid.x, y: mid.y };
    }
  }

  private onKey(e: KeyboardEvent): void {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const step = e.shiftKey ? 80 : 24;
    let handled = true;
    switch (e.key) {
      case "ArrowLeft":
      case "ArrowRight":
      case "ArrowUp":
      case "ArrowDown": {
        const dx = e.key === "ArrowLeft" ? step : e.key === "ArrowRight" ? -step : 0;
        const dy = e.key === "ArrowUp" ? step : e.key === "ArrowDown" ? -step : 0;
        this.navigated();
        if (this.mode === "2d") this.cam2 = panBy2d(this.cam2, dx, dy);
        else this.cam3 = e.shiftKey ? pan3d(this.cam3, dx, dy, this.height) : orbit(this.cam3, -dx * 0.5, -dy * 0.5);
        this.invalidate();
        break;
      }
      case "+":
      case "=":
        this.zoomBy(1.25);
        break;
      case "-":
      case "_":
        this.zoomBy(0.8);
        break;
      case "0":
      case "Home":
        this.fit();
        break;
      default:
        handled = false;
    }
    if (handled) e.preventDefault();
  }

  /** The world position under a screen point (2D only), for pointer read-outs. */
  worldAt(x: number, y: number): [number, number] | null {
    return this.mode === "2d" ? fromScreen2d(this.cam2, this.width, this.height, x, y) : null;
  }

  destroy(): void {
    this.resizeObserver?.disconnect();
    if (this.frame && typeof cancelAnimationFrame === "function") cancelAnimationFrame(this.frame);
  }
}

function scaleScene(scene: Scene, _factor: number): Scene {
  return scene;
}

export type { Segment, TurtleView };
