export type Route =
  | { name: "workspace" }
  | { name: "examples" }
  | { name: "challenges" }
  | { name: "challenge"; id: string }
  | { name: "reference"; anchor?: string }
  /** A shared program: the whole hash, to be handed to the workspace. */
  | { name: "link"; hash: string };

function decode(part: string | undefined): string | undefined {
  if (!part) return undefined;
  try {
    return decodeURIComponent(part);
  } catch {
    return undefined;
  }
}

/** Reads `location.hash`. Hash routing keeps every address working on a static host under any base path. */
export function parseRoute(hash: string): Route {
  if (hash.startsWith("#/p/")) return { name: "link", hash };
  const parts = hash.replace(/^#\/?/, "").split("/").filter(Boolean);
  switch (parts[0]) {
    case "przyklady":
      return { name: "examples" };
    case "wyzwania": {
      const id = decode(parts[1]);
      return id ? { name: "challenge", id } : { name: "challenges" };
    }
    case "opis": {
      const anchor = decode(parts[1]);
      return anchor ? { name: "reference", anchor } : { name: "reference" };
    }
    default:
      return { name: "workspace" };
  }
}

export function formatRoute(route: Route): string {
  switch (route.name) {
    case "workspace":
      return "#/";
    case "examples":
      return "#/przyklady";
    case "challenges":
      return "#/wyzwania";
    case "challenge":
      return `#/wyzwania/${encodeURIComponent(route.id)}`;
    case "reference":
      return route.anchor ? `#/opis/${encodeURIComponent(route.anchor)}` : "#/opis";
    case "link":
      return route.hash;
  }
}
