cat > tests/theme.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { ThemeController, type SystemTheme } from "../src/app/theme";
import { MemoryStorage } from "./fakes";

class FakeSystem implements SystemTheme {
  dark = false;
  private listeners = new Set<() => void>();
  get matchesDark() {
    return this.dark;
  }
  onChange(listener: () => void) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
  flip(dark: boolean) {
    this.dark = dark;
    for (const l of this.listeners) l();
  }
}

function make(storage = new MemoryStorage(), system = new FakeSystem()) {
  const applied: string[] = [];
  const theme = new ThemeController(storage, system, (t) => applied.push(t));
  return { theme, system, storage, applied };
}

describe("theme", () => {
  test("follows the system until the user chooses", () => {
    const { theme, system, applied } = make();
    expect(theme.choice).toBe("auto");
    expect(theme.effective).toBe("light");
    system.flip(true);
    expect(theme.effective).toBe("dark");
    expect(applied.at(-1)).toBe("dark");
    system.flip(false);
    expect(applied.at(-1)).toBe("light");
  });

  test("a manual choice wins over the system and survives a reload", () => {
    const first = make();
    first.theme.set("dark");
    first.system.flip(false);
    expect(first.theme.effective).toBe("dark");
    const second = make(first.storage, new FakeSystem());
    expect(second.theme.choice).toBe("dark");
    expect(second.theme.effective).toBe("dark");
  });

  test("the toggle steps through automatic, light and dark", () => {
    const { theme } = make();
    expect(theme.choice).toBe("auto");
    theme.cycle();
    expect(theme.choice).toBe("light");
    theme.cycle();
    expect(theme.choice).toBe("dark");
    theme.cycle();
    expect(theme.choice).toBe("auto");
  });

  test("subscribers hear about changes; junk in storage is ignored", () => {
    const storage = new MemoryStorage();
    storage.setItem("logomocja:v1:theme", "neon");
    const { theme } = make(storage);
