import { describe, expect, test } from "bun:test";
import { ThemeController, type SystemTheme } from "../src/app/theme";
import { MemoryStorage } from "./fakes";

class FakeSystem implements SystemTheme {
  dark = false;
  private listeners = new Set<() => void>();
  get matchesDark() {
    return this.dark;
  }
  onChange(listener: () => void) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
  flip(dark: boolean) {
    this.dark = dark;
    for (const l of this.listeners) l();
  }
}

function make(storage = new MemoryStorage(), system = new FakeSystem()) {
  const applied: string[] = [];
  const theme = new ThemeController(storage, system, (t) => applied.push(t));
  return { theme, system, storage, applied };
}

describe("theme", () => {
  test("follows the system until the user chooses", () => {
    const { theme, system, applied } = make();
    expect(theme.choice).toBe("auto");
    expect(theme.effective).toBe("light");
    system.flip(true);
    expect(theme.effective).toBe("dark");
    expect(applied.at(-1)).toBe("dark");
    system.flip(false);
    expect(applied.at(-1)).toBe("light");
  });

