/** Switching mode starts from a blank canvas: a drawing belongs to the mode that made it. */
setMode(mode: Mode): void {
  this.batch(() => {
    if (mode === this.state.mode) return;
    this.cancelFrame();
    this.execution = null;
    this.commit({
      ...this.state,
      mode,
      status: "idle",
      segments: [],
      turtle: INITIAL_TURTLE,
      currentLine: null,
      stack: [],
      stale: false,
      error: this.diagnose(this.state.source, mode),
    });
  });
}

/** The parse-time error the text has in this mode, if any. */
  this.batch(() => {
    this.cancelFrame();
    this.execution = null;
    this.commit({
      ...this.state,
      status: "idle",
      segments: [],
      turtle: INITIAL_TURTLE,
      currentLine: null,
      stack: [],
      error: this.diagnose(this.state.source, this.state.mode),
      stale: false,
    });
  });
}

/** Executes one statement; the first step starts a fresh, paused execution. */
step(): void {
  this.batch(() => {
    if (this.state.status === "running") this.pause();
    if (!this.execution && !this.begin()) return;
    this.commit({ ...this.state, status: "paused" });
    this.advance(1);
  });
}

private start(): void {
  this.commit({ ...this.state, status: "running" });
  if (RATES[this.state.speed - 1] === Infinity) {
    this.advance(Infinity);
    return;
  }
  this.lastTime = this.scheduler.now();
  this.budget = 0;
  this.schedule();
}

private cancelFrame(): void {
  if (this.frameId !== null) this.scheduler.cancel(this.frameId);
  this.frameId = null;
}

/** Compiles the source and starts an empty drawing; false when it cannot be run. */
private begin(): boolean {
  const compiled = compile(this.state.source, this.state.mode);
  if (!compiled.ok) {
    this.execution = null;
    this.commit({
      ...this.state,
      status: "error",
      segments: [],
      currentLine: null,
      error: compiled.error,
      stale: false,
    });
    return false;
  }
  this.execution = compiled.start();
  this.commit({ ...this.state, segments: [], currentLine: null, stack: [], error: null, stale: false });
  return true;
}

private schedule(): void {
  this.frameId = this.scheduler.request((time) => this.tick(time));
}

