describe("workspace: challenge documents", () => {
  test("a challenge opens in its own mode with its own starter and leaves the main drafts alone", () => {
    const { workspace } = open();
    workspace.edit("np 55 ; moje");
    workspace.openChallenge("szkielet");
    expect(workspace.activeChallenge?.id).toBe("szkielet");
    expect(workspace.studio.state.mode).toBe("3d");
    expect(workspace.studio.state.source).toBe(workspace.activeChallenge!.starter);
    workspace.closeChallenge();
    expect(workspace.activeChallenge).toBeNull();
    expect(workspace.studio.state.mode).toBe("2d");
    expect(workspace.studio.state.source).toBe("np 55 ; moje");
    expect(workspace.studio.state.status).toBe("finished");
  });

  test("work on a challenge is kept per challenge, across reloads, and never lands in the main draft", () => {
    const first = open();
    first.workspace.openChallenge("trojkat");
    first.workspace.edit("powtorz 3 [np 120 ; w trakcie");
    const second = open(first.storage);
    second.workspace.openChallenge("trojkat");
    expect(second.workspace.studio.state.source).toBe("powtorz 3 [np 120 ; w trakcie");
    second.workspace.openChallenge("kwadrat");
    expect(second.workspace.studio.state.source).toBe(second.workspace.activeChallenge!.starter);
    second.workspace.closeChallenge();
    expect(second.workspace.studio.state.source).toBe(findExample("kwadrat")!.source);
  });

  test("checking runs the program, reports pass or fail with a reason, and records the progress", () => {
    const { workspace, storage } = open();
    workspace.openChallenge("kwadrat");
    workspace.edit("powtorz 3 [np 100 pw 90]");
    const wrong = workspace.checkChallenge();
    expect(wrong.passed).toBe(false);
    expect(wrong.reason).toMatch(/Brakuje/);
    expect(workspace.challenges.isSolved("kwadrat")).toBe(false);
    workspace.edit("powtorz 4 [np 100 pw 90]");
    const right = workspace.checkChallenge();
    expect(right.passed).toBe(true);
    expect(workspace.challenges.isSolved("kwadrat")).toBe(true);
    expect(open(storage).workspace.challenges.isSolved("kwadrat")).toBe(true);
    expect(workspace.challenges.attempts("kwadrat")).toBe(2);
  });

  test("the mode cannot be switched inside a challenge, and unknown challenges are refused", () => {
    const { workspace } = open();
    expect(workspace.openChallenge("nie-ma")).toBe(false);
    expect(workspace.activeChallenge).toBeNull();
    workspace.openChallenge("kwadrat");
    workspace.switchMode("3d");
    expect(workspace.studio.state.mode).toBe("2d");
  });

  test("restarting a challenge brings back the starter text", () => {
    const { workspace } = open();
    workspace.openChallenge("kwadrat");
    workspace.edit("np 1");
    workspace.restartChallenge();
    expect(workspace.studio.state.source).toBe(workspace.activeChallenge!.starter);
  });

  test("checking with no challenge open is a mistake in the caller, not a crash", () => {
    const { workspace } = open();
    expect(() => workspace.checkChallenge()).toThrow();
  });
});
