import { clear, h, uid } from "./dom";
import { icon, type IconName } from "./icons";

export type ButtonVariant = "default" | "primary" | "quiet";

export interface ButtonOptions {
  label?: string;
  /** Accessible name when there is no visible label (icon-only buttons). */
  ariaLabel?: string;
  icon?: IconName;
  variant?: ButtonVariant;
  title?: string;
  shortcut?: string;
  onClick?: (event: MouseEvent) => void;
  class?: string;
  type?: "button" | "submit";
}

/** A button with the app's one shape: optional icon, optional text, never both missing. */
export function button(options: ButtonOptions): HTMLButtonElement {
  const el = h("button", {
    class: ["btn", options.variant && options.variant !== "default" ? `btn--${options.variant}` : "", options.label ? "" : "btn--icon", options.class ?? ""]
      .filter(Boolean)
      .join(" "),
    attrs: {
      type: options.type ?? "button",
      title: options.title ?? (options.shortcut ? `${options.ariaLabel ?? options.label} (${options.shortcut})` : options.ariaLabel),
      "aria-label": options.label ? undefined : options.ariaLabel,
      "aria-keyshortcuts": options.shortcut?.replace(/\s/g, ""),
    },
  });
  if (options.icon) el.appendChild(icon(options.icon, 18));
  if (options.label) el.appendChild(h("span", { class: "btn-label", text: options.label }));
  if (options.onClick) el.addEventListener("click", options.onClick);
  return el;
}

export function setButtonLabel(el: HTMLButtonElement, label: string): void {
  const text = el.querySelector(".btn-label");
  if (text) text.textContent = label;
}

export type PlateVariant = "info" | "ok" | "tourist" | "caution" | "stop" | "route" | "quiet";

/** A sign plate: a rounded rectangle with an inset keyline. In this app a plate always carries state. */
export function plate(text: string, variant: PlateVariant, iconName?: IconName): HTMLElement {
  return h("span", { class: `plate plate--${variant}` }, iconName ? icon(iconName, 14) : null, h("span", { text }));
}

// ---------------------------------------------------------------------------------------------

export interface ToastOptions {
  action?: { label: string; run: () => void };
  /** Milliseconds; 0 keeps it until dismissed. */
  timeout?: number;
}

/** Short messages that never steal focus. */
export class Toasts {
  readonly element: HTMLElement;

  constructor() {
    this.element = h("div", { class: "toasts", attrs: { role: "status", "aria-live": "polite", "aria-atomic": "false" } });
  }

  show(message: string, options: ToastOptions = {}): void {
    const toast = h("div", { class: "toast" }, h("span", { class: "toast-text", text: message }));
    const remove = () => toast.remove();
    if (options.action) {
      const { label, run } = options.action;
      toast.appendChild(
        button({
          label,
          variant: "quiet",
          class: "toast-action",
          onClick: () => {
            run();
            remove();
          },
        }),
      );
    }
    toast.appendChild(button({ ariaLabel: "Zamknij komunikat", icon: "close", variant: "quiet", class: "toast-close", onClick: remove }));
    this.element.appendChild(toast);
    while (this.element.children.length > 3) this.element.firstElementChild?.remove();
    const timeout = options.timeout ?? (options.action ? 9000 : 4500);
    if (timeout > 0) setTimeout(remove, timeout);
  }
