  for (const action of options.actions) {
    const el = button({
      label: action.label,
      variant: action.variant ?? "default",
      onClick: () => {
        if (action.run?.() !== false) close();
      },
    });
    if (action.initial) initial = el;
    footer.appendChild(el);
