export function confirmDialog(options: {
  title: string;
  message: string | Node;
  confirmLabel: string;
  cancelLabel?: string;
  danger?: boolean;
}): Promise<boolean> {
  return new Promise((resolve) => {
    let answered = false;
    const answer = (value: boolean) => () => {
      answered = true;
      resolve(value);
    };
    openDialog({
      title: options.title,
      body: typeof options.message === "string" ? h("p", { text: options.message }) : options.message,
      actions: [
        { label: options.cancelLabel ?? "Anuluj", run: answer(false), initial: true },
        { label: options.confirmLabel, variant: "primary", run: answer(true) },
      ],
      onClose: () => {
        if (!answered) resolve(false);
      },
    });
  });
