// ---------------------------------------------------------------------------------------------

export interface MenuItem {
  label: string;
  icon?: IconName;
  hint?: string;
  disabled?: boolean;
  onSelect: () => void;
}

export interface MenuOptions {
  label: string;
  icon?: IconName;
  /** Hide the text on narrow screens, keeping the accessible name. */
  collapseLabel?: boolean;
  items: () => (MenuItem | "separator")[];
  align?: "start" | "end";
  class?: string;
}

/**
 * A button that opens a list of actions. The list is attached to the page body while open, so no
 * scrolling toolbar can clip it; arrow keys move, Escape closes and returns focus.
 */
export function createMenu(options: MenuOptions): { element: HTMLElement; button: HTMLButtonElement; close: () => void } {
  const menuId = uid("menu");
  const trigger = h("button", {
    class: `btn menu-trigger ${options.class ?? ""}`.trim(),
    attrs: { type: "button", "aria-haspopup": "menu", "aria-expanded": "false", "aria-controls": menuId },
  });
  if (options.icon) trigger.appendChild(icon(options.icon, 18));
  trigger.appendChild(h("span", { class: options.collapseLabel ? "btn-label btn-label--wide" : "btn-label", text: options.label }));
  trigger.appendChild(icon("chevronDown", 14));
  const root = h("span", { class: "menu" }, trigger);
  let list: HTMLElement | null = null;

  const close = (restoreFocus = false) => {
    if (!list) return;
    list.remove();
    list = null;
    trigger.setAttribute("aria-expanded", "false");
    document.removeEventListener("pointerdown", onOutside, true);
    window.removeEventListener("resize", onViewportChange);
    window.removeEventListener("scroll", onViewportChange, true);
    if (restoreFocus) trigger.focus();
  };
  const onOutside = (event: Event) => {
    if (list && !list.contains(event.target as Node) && !trigger.contains(event.target as Node)) close();
  };
  const onViewportChange = () => close();

  const itemsOf = () => [...(list?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not([disabled])') ?? [])];

  const open = () => {
    if (list) return;
    list = h("div", { class: "menu-list", attrs: { role: "menu", id: menuId, "aria-label": options.label } });
    for (const entry of options.items()) {
      if (entry === "separator") {
        list.appendChild(h("div", { class: "menu-separator", attrs: { role: "separator" } }));
        continue;
      }
      const item = h(
        "button",
        {
          class: "menu-item",
          attrs: { type: "button", role: "menuitem", disabled: entry.disabled, tabindex: "-1" },
          on: {
            click: () => {
              close(true);
              entry.onSelect();
            },
          },
        },
        entry.icon ? icon(entry.icon, 16) : h("span", { class: "menu-icon-gap" }),
        h("span", { class: "menu-item-label", text: entry.label }),
        entry.hint ? h("span", { class: "menu-item-hint", text: entry.hint }) : null,
      );
      list.appendChild(item);
    }
    list.addEventListener("keydown", (event) => {
      const items = itemsOf();
      const index = items.indexOf(document.activeElement as HTMLButtonElement);
      if (event.key === "ArrowDown") items[(index + 1) % items.length]?.focus();
      else if (event.key === "ArrowUp") items[(index - 1 + items.length) % items.length]?.focus();
      else if (event.key === "Home") items[0]?.focus();
      else if (event.key === "End") items[items.length - 1]?.focus();
      else if (event.key === "Escape") close(true);
      else if (event.key === "Tab") close();
      else return;
      if (event.key !== "Tab") event.preventDefault();
    });
    document.body.appendChild(list);
    const rect = trigger.getBoundingClientRect();
    list.style.top = `${Math.round(rect.bottom + 4)}px`;
    if (options.align === "end") {
      list.style.right = `${Math.max(8, Math.round(window.innerWidth - rect.right))}px`;
    } else {
      list.style.left = `${Math.max(8, Math.round(rect.left))}px`;
    }
    trigger.setAttribute("aria-expanded", "true");
    document.addEventListener("pointerdown", onOutside, true);
    window.addEventListener("resize", onViewportChange);
    window.addEventListener("scroll", onViewportChange, true);
    itemsOf()[0]?.focus();
  };

  trigger.addEventListener("click", () => (list ? close() : open()));
  trigger.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" && !list) {
      event.preventDefault();
      open();
    }
  });
  return { element: root, button: trigger, close: () => close() };
}

/** Replaces the children of `el` with `nodes`. */
export function setChildren(el: Element, ...nodes: (Node | string | null | undefined | false)[]): void {
  clear(el);
  for (const node of nodes) {
    if (node === null || node === undefined || node === false) continue;
    el.appendChild(typeof node === "string" ? document.createTextNode(node) : node);
  }
}
