      const item = h(
        "button",
        {
          class: "menu-item",
          attrs: { type: "button", role: "menuitem", disabled: entry.disabled, tabindex: "-1" },
          on: {
            click: () => {
              close(true);
              entry.onSelect();
            },
          },
        },
        entry.icon ? icon(entry.icon, 16) : h("span", { class: "menu-icon-gap" }),
        h("span", { class: "menu-item-label", text: entry.label }),
        entry.hint ? h("span", { class: "menu-item-hint", text: entry.hint }) : null,
      );
      list.appendChild(item);
    }
    list.addEventListener("keydown", (event) => {
      const items = itemsOf();
      const index = items.indexOf(document.activeElement as HTMLButtonElement);
      if (event.key === "ArrowDown") items[(index + 1) % items.length]?.focus();
      else if (event.key === "ArrowUp") items[(index - 1 + items.length) % items.length]?.focus();
      else if (event.key === "Home") items[0]?.focus();
      else if (event.key === "End") items[items.length - 1]?.focus();
      else if (event.key === "Escape") close(true);
      else if (event.key === "Tab") close();
      else return;
      if (event.key !== "Tab") event.preventDefault();
    });
    document.body.appendChild(list);
    const rect = trigger.getBoundingClientRect();
    list.style.top = `${Math.round(rect.bottom + 4)}px`;
    if (options.align === "end") {
      list.style.right = `${Math.max(8, Math.round(window.innerWidth - rect.right))}px`;
    } else {
      list.style.left = `${Math.max(8, Math.round(rect.left))}px`;
    }
    trigger.setAttribute("aria-expanded", "true");
    document.addEventListener("pointerdown", onOutside, true);
    window.addEventListener("resize", onViewportChange);
    window.addEventListener("scroll", onViewportChange, true);
    itemsOf()[0]?.focus();
  };

  trigger.addEventListener("click", () => (list ? close() : open()));
  trigger.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" && !list) {
      event.preventDefault();
      open();
    }
  });
  return { element: root, button: trigger, close: () => close() };
}

/** Replaces the children of `el` with `nodes`. */
export function setChildren(el: Element, ...nodes: (Node | string | null | undefined | false)[]): void {
  clear(el);
  for (const node of nodes) {
    if (node === null || node === undefined || node === false) continue;
    el.appendChild(typeof node === "string" ? document.createTextNode(node) : node);
  }
}
