/** Polish plural forms: 1 odcinek, 2–4 odcinki, 5+ odcinków (and 12–14 odcinków). */
export function plural(n: number, forms: [one: string, few: string, many: string]): string {
  const abs = Math.abs(n);
  if (abs === 1) return forms[0];
  const lastTwo = abs % 100;
  const last = abs % 10;
  if (last >= 2 && last <= 4 && !(lastTwo >= 12 && lastTwo <= 14)) return forms[1];
  return forms[2];
}

export function countOf(n: number, forms: [string, string, string]): string {
  return `${n.toLocaleString("pl-PL")} ${plural(n, forms)}`;
}

/** A number as short as is still accurate: 12, 12.5, 0.333. */
export function compactNumber(n: number, digits = 3): string {
  if (!Number.isFinite(n)) return String(n);
  const rounded = Number(n.toFixed(digits));
  return Object.is(rounded, -0) ? "0" : String(rounded);
}

/** The heading of the turtle in the plane: degrees clockwise from "up the page", 0 to 359.9. */
export function headingDegrees(heading: readonly [number, number, number]): number {
  const degrees = (Math.atan2(heading[0], heading[1]) * 180) / Math.PI;
  return ((degrees % 360) + 360) % 360;
}
EOF
