    const forms: [string, string, string] = ["odcinek", "odcinki", "odcinków"];
    const expected: Record<number, string> = { 0: "odcinków", 1: "odcinek", 2: "odcinki", 4: "odcinki", 5: "odcinków", 12: "odcinków", 14: "odcinków", 22: "odcinki", 25: "odcinków", 112: "odcinków", 1000: "odcinków" };
    for (const [n, form] of Object.entries(expected)) expect(plural(Number(n), forms)).toBe(form);
    expect(countOf(1234, forms)).toBe(`${(1234).toLocaleString("pl-PL")} odcinki`);
  });

  test("numbers are short but accurate", () => {
    expect(compactNumber(12)).toBe("12");
    expect(compactNumber(12.5)).toBe("12.5");
    expect(compactNumber(1 / 3)).toBe("0.333");
    expect(compactNumber(-0.0001)).toBe("0");
    expect(compactNumber(7.000000001)).toBe("7");
  });

  test("the heading is measured clockwise from straight up the page", () => {
    expect(headingDegrees([0, 1, 0])).toBe(0);
    expect(headingDegrees([1, 0, 0])).toBe(90);
    expect(headingDegrees([0, -1, 0])).toBe(180);
