    this.routeList = h("ol", { class: "route-list", attrs: { "aria-label": "Aktywne procedury i powtórzenia" } });
    const route = h("div", { class: "route" }, h("span", { class: "route-label", text: "Trasa" }), h("div", { class: "route-body" }, this.routeEmpty, this.routeList));

