    }
    const next = this.nextChallengeHash();
    setChildren(
      this.challengeResult,
      h(
        "div",
        { class: `result result--${result.passed ? "pass" : "fail"}` },
        plate(result.passed ? "Zaliczone" : "Jeszcze nie", result.passed ? "ok" : "stop", result.passed ? "check" : "alert"),
