      h("div", { class: "pane-head pane-head--canvas" }, h("h2", { class: "pane-title", text: "Rysunek" }), this.stats, speedBox, tools),
      h("div", { class: "canvas-wrap" }, this.viewport.element, this.hint, this.staleNote, this.readout, this.unavailable),
    );

    // ---- tabs (narrow screens) and layout
    this.tabs = {
      code: h("button", { class: "tab", attrs: { type: "button", role: "tab", "aria-selected": "true" } }, icon("pencil", 16), h("span", { text: "Kod" })),
      draw: h("button", { class: "tab", attrs: { type: "button", role: "tab", "aria-selected": "false" } }, icon("square", 16), h("span", { text: "Rysunek" })),
    };
    this.tabs.code.addEventListener("click", () => this.showPane("code"));
    this.tabs.draw.addEventListener("click", () => this.showPane("draw"));
    const tabList = h("div", { class: "pane-tabs", attrs: { role: "tablist", "aria-label": "Widok" } }, this.tabs.code, this.tabs.draw);
    this.panes = h("div", { class: "panes", attrs: { "data-pane": "code" } }, codePane, canvasPane);

    this.element = h("section", { class: "page page--workspace", attrs: { "aria-labelledby": "workspace-title" } }, h("h1", { class: "visually-hidden", attrs: { id: "workspace-title", tabindex: "-1" }, text: "Pracownia" }), toolbar, tabList, this.panes);

    this.speedText.textContent = SPEED_LABELS[speed - 1]!;
    this.speedInput.setAttribute("aria-valuetext", SPEED_LABELS[speed - 1]!);
    this.studio.setSpeed(speed);

    this.studio.subscribe((state) => this.sync(state));
    deps.theme.subscribe((_choice, effective) => this.viewport.setTheme(effective));
    this.sync(this.studio.state);
    this.editor.setValue(this.studio.state.source);
  }

  // ---- showing and hiding ----------------------------------------------------------------

  /** Called by the router when the page appears. `challengeId` is set for a challenge. */
  show(challengeId?: string): void {
    this.visible = true;
    this.element.hidden = false;
    if (challengeId) {
      if (this.workspace.activeChallenge?.id !== challengeId && !this.workspace.openChallenge(challengeId)) {
        this.deps.navigate("#/wyzwania");
        return;
      }
    } else if (this.workspace.activeChallenge) {
      this.workspace.closeChallenge();
    }
    this.previous = null;
    this.renderChallenge();
    this.sync(this.studio.state);
    this.editor.setValue(this.studio.state.source);
    this.viewport.setMode(this.studio.state.mode);
    this.viewport.refresh();
    this.viewport.fit(true);
  }

  hide(): void {
    this.visible = false;
    this.element.hidden = true;
    if (this.studio.state.status === "running") this.studio.pause();
  }

  get isVisible(): boolean {
    return this.visible;
  }

  /** Moves keyboard focus into the program text. */
  focusEditor(): void {
    this.editor.focus();
  }

  // ---- commands --------------------------------------------------------------------------

  run(): void {
    if (this.runButton.getAttribute("aria-disabled") === "true") return;
    this.studio.run();
    if (this.studio.state.status === "error" && this.studio.state.error) this.showPane("code");
    else this.showPane("draw");
  }

  step(): void {
    this.studio.step();
  }

  pause(): void {
    if (this.studio.state.status === "running") this.studio.pause();
  }

  reset(): void {
    this.studio.reset();
    this.viewport.fit(true);
  }

  private setMode(mode: Mode): void {
    if (this.workspace.activeChallenge) return;
    this.workspace.switchMode(mode);
  }

  private setSpeed(speed: number): void {
    this.studio.setSpeed(speed);
    this.speedText.textContent = SPEED_LABELS[speed - 1]!;
    this.speedInput.setAttribute("aria-valuetext", SPEED_LABELS[speed - 1]!);
    try {
      this.deps.storage?.setItem(SPEED_KEY, String(speed));
    } catch {
      // not remembered
    }
  }

  private loadSpeed(): number {
    try {
      const stored = Number(this.deps.storage?.getItem(SPEED_KEY));
      if (Number.isInteger(stored) && stored >= 1 && stored <= 6) return stored;
    } catch {
      // default
    }
    return 4;
  }

  private resetView(): void {
    this.presetSelect.value = "perspective";
    this.viewport.resetView();
  }

  showPane(pane: "code" | "draw"): void {
    this.panes.setAttribute("data-pane", pane);
    for (const [name, tab] of Object.entries(this.tabs)) tab.setAttribute("aria-selected", String(name === pane));
    if (pane === "draw") this.viewport.refresh();
  }

  // ---- files and sharing -----------------------------------------------------------------

  private share(): void {
    const base = location.href.split("#")[0]!;
    showShareDialog(this.workspace.shareLink(base), (ok) => {
      this.deps.toasts.show(ok ? "Adres skopiowany do schowka." : "Nie udało się skopiować. Zaznacz adres i skopiuj go ręcznie.");
    });
  }

  private download(): void {
    const file = this.workspace.exportFile();
    downloadText(file.text, file.name);
    this.deps.toasts.show(`Pobrano plik ${file.name}.`);
  }

  private async exportPng(): Promise<void> {
    const blob = await this.viewport.exportPng();
    if (!blob) {
      this.deps.toasts.show("Nie ma jeszcze rysunku do zapisania. Uruchom program.");
      return;
    }
    const title = this.workspace.title() ?? `szkic-${this.studio.state.mode}`;
    downloadBlob(blob, `${title}.png`);
    this.deps.toasts.show(`Zapisano rysunek: ${title}.png.`);
  }

  private async onFileChosen(): Promise<void> {
    const file = this.fileInput.files?.[0];
    this.fileInput.value = "";
    if (!file) return;
    const read = await readTextFile(file);
    if ("error" in read) {
      this.deps.toasts.show(read.error, { timeout: 8000 });
      return;
    }
    await this.importText(file.name, read.text);
  }

  /** Loads file text into the editor, asking first if that would replace unsaved work. */
  async importText(name: string, text: string): Promise<void> {
    let result = this.workspace.importFile(name, text);
    if (result.status === "needs-confirmation") {
      const sure = await confirmDialog({
        title: "Zastąpić bieżący program?",
        message: `W edytorze są zmiany, które nie zostały zapisane. Otwarcie pliku „${name}” zastąpi je. Poprzednia wersja trafi do kopii zapasowych i będzie można ją przywrócić.`,
        confirmLabel: "Otwórz plik",
      });
      if (!sure) return;
      result = this.workspace.importFile(name, text, { confirmed: true });
    }
    if (result.status === "loaded") this.deps.toasts.show(`Otwarto plik ${name}.`);
  }

  private showBackups(): void {
    showBackupsDialog(this.workspace.backups(), {
      restore: (id) => {
        if (this.workspace.restoreBackup(id)) this.deps.toasts.show("Przywrócono kopię zapasową.");
      },
      remove: (id) => this.workspace.drafts.removeBackup(id),
    });
  }

  // ---- challenge ------------------------------------------------------------------------

  private renderChallenge(): void {
    const challenge = this.workspace.activeChallenge;
    this.challengeBar.hidden = !challenge;
    this.modeGroup.hidden = !!challenge;
    this.element.classList.toggle("is-challenge", !!challenge);
    if (!challenge) {
      setChildren(this.challengeBar);
      this.challengeResult = null;
      return;
    }
    const solved = this.workspace.challenges.isSolved(challenge.id);
    this.challengeResult = h("div", { class: "challenge-result", attrs: { "aria-live": "polite", "aria-atomic": "true" } });
    const hint = h("details", { class: "hint" }, h("summary", { text: "Podpowiedź" }), h("p", { text: challenge.hint }));
    setChildren(
      this.challengeBar,
      h(
        "div",
        { class: "challenge-head" },
        h("a", { class: "back-link", attrs: { href: "#/wyzwania" } }, icon("chevronRight", 14), h("span", { text: "Wszystkie wyzwania" })),
        solved ? plate("Rozwiązane", "ok", "check") : plate("Do rozwiązania", "info"),
      ),
      h("h2", { class: "challenge-title", text: challenge.title }),
      h("p", { class: "challenge-brief", text: challenge.brief }),
      h(
        "p",
        { class: "challenge-legend" },
        h("span", { class: "legend-line", attrs: { "aria-hidden": "true" } }),
        h("span", { text: "Fioletowa przerywana linia na rysunku to wzór do odtworzenia." }),
      ),
      hint,
      h(
        "div",
        { class: "challenge-actions" },
        button({ label: "Sprawdź rozwiązanie", icon: "check", variant: "primary", onClick: () => this.checkChallenge() }),
        button({
          label: "Zacznij od nowa",
          icon: "reset",
          onClick: async () => {
            const sure = await confirmDialog({ title: "Zacząć od nowa?", message: "Twój program w tym wyzwaniu zostanie zastąpiony tekstem początkowym.", confirmLabel: "Zacznij od nowa" });
            if (sure) {
              this.workspace.restartChallenge();
              this.setResult(null);
            }
          },
        }),
      ),
      this.challengeResult,
    );
  }

  private checkChallenge(): void {
    const result = this.workspace.checkChallenge();
    this.setResult(result);
    this.renderChallengeStatus();
  }

  private renderChallengeStatus(): void {
    const challenge = this.workspace.activeChallenge;
    const head = this.challengeBar.querySelector(".challenge-head");
    if (!challenge || !head) return;
    const old = head.querySelector(".plate");
    old?.replaceWith(this.workspace.challenges.isSolved(challenge.id) ? plate("Rozwiązane", "ok", "check") : plate("Do rozwiązania", "info"));
  }

  private setResult(result: CheckResult | null): void {
    if (!this.challengeResult) return;
    if (!result) {
      setChildren(this.challengeResult);
      return;
    }
    const next = this.nextChallengeHash();
    setChildren(
      this.challengeResult,
      h(
        "div",
        { class: `result result--${result.passed ? "pass" : "fail"}` },
        plate(result.passed ? "Zaliczone" : "Jeszcze nie", result.passed ? "ok" : "stop", result.passed ? "check" : "alert"),
        h("p", { class: "result-text", text: result.reason }),
        result.passed && next ? h("a", { class: "btn btn--primary", attrs: { href: next } }, h("span", { class: "btn-label", text: "Następne wyzwanie" }), icon("arrowRight", 16)) : null,
      ),
    );
  }

  private nextChallengeHash(): string | null {
    const current = this.workspace.activeChallenge;
    if (!current) return null;
    const all = this.deps.workspace.challenges;
    void all;
    return this.nextOf?.(current.id) ?? null;
  }

  /** Set by the app: the hash of the challenge after `id`, if any. */
  nextOf?: (id: string) => string | null;

  // ---- keeping the screen in step with the studio ----------------------------------------

  private sync(state: StudioState): void {
    const prev = this.previous;
    this.previous = state;

    if (this.editor.getValue() !== state.source) this.editor.setValue(state.source);
    this.editor.setError(state.error);
    this.editor.setCurrentLine(state.currentLine);

    // mode
    for (const mode of ["2d", "3d"] as const) {
      const on = state.mode === mode;
      this.modeButtons[mode].setAttribute("aria-checked", String(on));
      this.modeButtons[mode].tabIndex = on ? 0 : -1;
    }
    this.viewTools3d.hidden = state.mode !== "3d";
    this.element.dataset.mode = state.mode;
    if (!prev || prev.mode !== state.mode) {
      this.viewport.setMode(state.mode);
      if (state.mode === "3d") this.presetSelect.value = "perspective";
    }

    // toolbar
    const running = state.status === "running";
    const paused = state.status === "paused";
    setButtonLabel(this.runButton, paused ? "Wznów" : "Uruchom");
    this.setEnabled(this.runButton, !running);
    this.setEnabled(this.stepButton, true);
    this.setEnabled(this.pauseButton, running);
    this.setEnabled(this.resetButton, state.status !== "idle" || state.segments.length > 0 || state.stale);

    // drawing
    const ended = state.status === "finished" || state.status === "error";
    const challenge = this.workspace.activeChallenge;
    this.viewport.setScene(
      { segments: state.segments, turtle: state.turtle, ghost: challenge?.target() },
      { finished: ended && prev?.status !== state.status },
    );
    this.hint.hidden = state.segments.length > 0 || state.status === "running" || state.status === "paused";
    this.staleNote.hidden = !state.stale;
    this.stats.textContent = state.segments.length ? countOf(state.segments.length, ["odcinek", "odcinki", "odcinków"]) : "";
    this.renderReadout(state);

    if (!prev || prev.stack !== state.stack) this.renderRoute(state.stack);
    if (!prev || prev.status !== state.status || prev.error !== state.error || prev.stale !== state.stale || prev.mode !== state.mode || prev.segments.length !== state.segments.length && ended) {
      this.renderConsole(state);
    }
    if (prev && prev.status === "running" && state.status !== "running" && state.status !== "paused") {
      // a run just ended: on a narrow screen the message must be seen
      if (state.status === "error") this.showPane("code");
    }
  }

  private setEnabled(el: HTMLButtonElement, enabled: boolean): void {
    // aria-disabled keeps the button focusable, so pressing Uruchom does not throw keyboard focus away
    el.setAttribute("aria-disabled", String(!enabled));
    el.classList.toggle("is-disabled", !enabled);
  }

  private renderReadout(state: StudioState): void {
    const t = state.turtle;
    const cells: [string, string][] =
      state.mode === "2d"
        ? [["x", compactNumber(t.position[0], 2)], ["y", compactNumber(t.position[1], 2)], ["kierunek", `${compactNumber(headingDegrees(t.heading), 1)}°`]]
        : [["x", compactNumber(t.position[0], 2)], ["y", compactNumber(t.position[1], 2)], ["z", compactNumber(t.position[2], 2)]];
    setChildren(
      this.readout,
      ...cells.flatMap(([name, value]) => [h("dt", { text: name }), h("dd", { text: value })]),
      h("dt", { text: "pióro" }),
      h("dd", { class: "readout-pen" }, h("span", { class: "swatch", style: { background: t.color }, attrs: { "aria-hidden": "true" } }), h("span", { text: `${t.penDown ? "dół" : "góra"} · ${t.width}` })),
    );
  }

  private renderRoute(stack: readonly StackEntry[]): void {
    this.routeEmpty.hidden = stack.length > 0;
    this.routeList.hidden = stack.length === 0;
    setChildren(this.routeList);
    stack.forEach((entry, index) => {
      const current = index === stack.length - 1;
      const label =
        entry.kind === "call"
          ? `${entry.label}${entry.args && entry.args.length ? ` ${entry.args.map((a) => compactNumber(a, 2)).join(", ")}` : ""}`
          : `${entry.label} ${entry.iteration}/${entry.total}`;
      const item = h(
        "li",
        { class: `route-item${current ? " is-current" : ""}${entry.kind === "repeat" ? " route-item--repeat" : ""}` },
        h("button", { class: "route-plate", attrs: { type: "button", title: `Przejdź do wiersza ${entry.line}`, "aria-current": current ? "step" : undefined }, on: { click: () => this.editor.focusAt(entry.line, entry.column) } }, h("span", { text: label })),
      );
      this.routeList.appendChild(item);
    });
  }

  private renderConsole(state: StudioState): void {
    const keyRun = formatKeys(RUN);
    const keyStep = formatKeys(STEP);
    const showInCode = (error: NonNullable<StudioState["error"]>) =>
      button({ label: "Pokaż w kodzie", icon: "chevronRight", variant: "quiet", onClick: () => this.editor.focusAt(error.line, error.column) });
    let content: (Node | string)[];
    let tone = "idle";
    if (state.error) {
      tone = "error";
      const runtime = state.status === "error" && state.segments.length >= 0 && this.previousWasRun(state);
      content = [
        plate(runtime ? "Błąd w trakcie" : "Błąd", "stop", "alert"),
        h("div", { class: "console-text" }, h("p", { text: `Wiersz ${state.error.line}, kolumna ${state.error.column}: ${state.error.message}` }), runtime ? h("p", { class: "muted", text: state.segments.length ? "Rysunek zachowano do miejsca błędu." : "Przed błędem nic nie narysowano." }) : null),
        showInCode(state.error),
      ];
    } else if (state.status === "running") {
      tone = "run";
      content = [plate("Działa", "info"), h("p", { class: "console-text", text: "Program się wykonuje. Pauza lub Esc wstrzymuje animację." })];
    } else if (state.status === "paused") {
      tone = "paused";
      content = [plate("Wstrzymano", "caution"), h("p", { class: "console-text", text: state.currentLine ? `Ostatnio wykonany wiersz: ${state.currentLine}. Krok idzie dalej, ${keyRun} wznawia.` : `Krok idzie dalej, ${keyRun} wznawia.` })];
    } else if (state.status === "finished") {
      tone = "ok";
      content = [plate("Gotowe", "ok", "check"), h("p", { class: "console-text", text: `Program zakończony: ${countOf(state.segments.length, ["odcinek", "odcinki", "odcinków"])}.` })];
    } else if (state.stale) {
      tone = "paused";
      content = [plate("Nieaktualny", "caution", "alert"), h("p", { class: "console-text", text: `Rysunek pochodzi z wcześniejszej wersji programu. ${keyRun} uruchamia obecną.` })];
    } else {
      content = [plate("Gotowy", "quiet"), h("p", { class: "console-text", text: `${keyRun} uruchamia cały program, ${keyStep} wykonuje jeden krok.` })];
    }
    this.consoleBox.dataset.tone = tone;
    setChildren(this.consoleBox, h("div", { class: "console-row" }, ...content));
  }

  /** True when the error came from running (the drawing may be partial) rather than from the live check. */
  private previousWasRun(state: StudioState): boolean {
    return state.status === "error";
  }
}
