    const { studio } = newStudio("");
    studio.open("np 1 np 1 / 0", "2d");
    expect(studio.state.errorKind).toBe("runtime");
    studio.open("nie ma", "2d");
    expect(studio.state.errorKind).toBe("parse");
    studio.open("np 1", "2d");
    expect(studio.state.errorKind).toBeNull();
  });
});
