mkdir -p src/reference && cat > tests/reference.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { allKeywordSpellings, run } from "../src/lang";
import { COMMAND_DOCS, EXAMPLE_BLOCKS, SECTIONS, referenceExamples } from "../src/reference/content";

describe("command reference", () => {
  test("every spelling the interpreter accepts is documented", () => {
    const documented = new Set(
      COMMAND_DOCS.flatMap((c) => [...c.polish, ...c.english]).map((w) => w.normalize("NFC").toLowerCase()),
    );
    const missing = allKeywordSpellings().filter((w) => !documented.has(w.normalize("NFC")));
    expect(missing).toEqual([]);
  });

  test("every example in the reference runs without an error in its own mode", () => {
    const examples = referenceExamples();
    expect(examples.length).toBeGreaterThan(30);
    for (const example of examples) {
      const { error } = run(example.code, example.mode);
      if (error) throw new Error(`Przykład „${example.code.slice(0, 40)}…” kończy się błędem: ${error.message} (wiersz ${error.line})`);
    }
  });

  test("the examples that are meant to fail show exactly the error they claim", () => {
    for (const block of EXAMPLE_BLOCKS.filter((b) => b.expectError)) {
      const { error } = run(block.code, block.mode);
      expect(error).not.toBeNull();
      expect(`Wiersz ${error!.line}, kolumna ${error!.column}`).toBe(block.expectError!.position);
    }
  });

  test("every command has an example with something to see, and a one-line summary", () => {
    for (const doc of COMMAND_DOCS) {
      expect(doc.summary.length).toBeGreaterThan(15);
      expect(doc.example.code.trim().length).toBeGreaterThan(0);
      if (doc.id === "nrpowt" || doc.id === "ma") continue;
      const { segments } = run(doc.example.code, doc.example.mode);
      expect(segments.length).toBeGreaterThan(0);
    }
  });

  test("the sections the brief asks for are all there, with unique anchors", () => {
    const ids = SECTIONS.map((s) => s.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const wanted of ["wstep", "zapis", "ruch", "pioro", "trzy-d", "powtarzanie", "wyrazenia", "zmienne", "warunki", "procedury", "bledy", "limity"]) {
      expect(ids).toContain(wanted);
    }
  });

  test("the limits quoted in the text are the ones the interpreter enforces", () => {
    const text = JSON.stringify(SECTIONS.find((s) => s.id === "limity"));
    for (const n of ["50 000", "10 000", "32", "100 000"]) expect(text).toContain(n);
  });
});
EOF
