const blockById = (id: string) => EXAMPLE_BLOCKS.find((b) => b.id === id)!;
export const getExampleBlock = blockById;

/** Every example that is meant to run, for the test that keeps the documentation honest. */
export function referenceExamples(): Example[] {
  return [...COMMAND_DOCS.map((c) => c.example), ...EXAMPLE_BLOCKS.filter((b) => !b.expectError)];
}

