import { h } from "../app/dom";
import { countOf } from "../app/format";
import { icon } from "../app/icons";
import { button, confirmDialog, plate, type Toasts } from "../app/ui";
import { codeBlock } from "../editor/code-block";
import { EXAMPLES, type Example } from "../examples";
import { run, type Mode } from "../lang";
import type { Workspace } from "../studio/workspace";
import type { ThemeController } from "../app/theme";
import { Thumbnail } from "../view/thumbnail";

export interface ExamplesPageDeps {
  workspace: Workspace;
  toasts: Toasts;
  theme: ThemeController;
  navigate: (hash: string) => void;
}

type Filter = "all" | Mode;

/** The thirteen standard programs: look, read the code, load one into the workspace. */
export class ExamplesPage {
  readonly element: HTMLElement;
  private readonly cards = new Map<string, HTMLElement>();
  private readonly thumbnails: Thumbnail[] = [];
  private readonly count: HTMLElement;
  private readonly filterButtons = new Map<Filter, HTMLButtonElement>();
  private filter: Filter = "all";

  constructor(private readonly deps: ExamplesPageDeps) {
    const list = h("ul", { class: "cards", attrs: { "aria-label": "Przykładowe programy" } });
    for (const example of EXAMPLES) {
      const card = this.card(example);
      this.cards.set(example.id, card);
      list.appendChild(card);
    }
    this.count = h("p", { class: "muted tabular", attrs: { "aria-live": "polite" } });
    const filters = h("div", { class: "segmented", attrs: { role: "radiogroup", "aria-label": "Pokaż przykłady" } });
    const labels: [Filter, string][] = [["all", `Wszystkie (${EXAMPLES.length})`], ["2d", `2D (${EXAMPLES.filter((e) => e.mode === "2d").length})`], ["3d", `3D (${EXAMPLES.filter((e) => e.mode === "3d").length})`]];
    for (const [value, label] of labels) {
      const b = h("button", { class: "segment", attrs: { type: "button", role: "radio", "aria-checked": String(value === "all") } }, h("span", { text: label }));
      b.addEventListener("click", () => this.setFilter(value));
      this.filterButtons.set(value, b);
      filters.appendChild(b);
    }
    this.element = h(
      "section",
      { class: "page page--list", attrs: { "aria-labelledby": "examples-title", hidden: true } },
      h(
        "div",
        { class: "page-inner" },
        h(
          "header",
          { class: "page-head" },
          h("h1", { class: "page-title", attrs: { id: "examples-title", tabindex: "-1" }, text: "Przykłady" }),
          h("p", { class: "lead", text: "Trzynaście gotowych programów. Wczytaj dowolny do pracowni, uruchom krok po kroku i zmieniaj, co chcesz." }),
        ),
        h("div", { class: "filter-row" }, filters, this.count),
        list,
      ),
    );
    this.setFilter("all");
    deps.theme.subscribe((_c, effective) => this.thumbnails.forEach((t) => t.setTheme(effective)));
  }

  private card(example: Example): HTMLElement {
    const result = run(example.source, example.mode);
    const thumb = new Thumbnail(result.segments, example.mode, this.deps.theme.effective, `Podgląd rysunku: ${example.name}`);
    this.thumbnails.push(thumb);
    const modeLabel = example.mode === "2d" ? "2D" : "3D";
    return h(
      "li",
      { class: "card", attrs: { "data-mode": example.mode } },
      h(
        "article",
        { class: "card-inner", attrs: { "aria-labelledby": `ex-${example.id}` } },
        thumb.element,
        h(
          "div",
          { class: "card-body" },
          h("div", { class: "card-title-row" }, h("h2", { class: "card-title", attrs: { id: `ex-${example.id}` }, text: example.name }), plate(modeLabel, example.mode === "2d" ? "info" : "tourist")),
          h("p", { class: "card-text", text: example.tagline }),
          h(
            "div",
            { class: "card-actions" },
            button({
              label: "Wczytaj",
              icon: "play",
              variant: "primary",
              title: `Wczytaj przykład ${example.name} (${modeLabel}) do pracowni`,
              onClick: () => void this.load(example),
            }),
            h("details", { class: "peek" }, h("summary", {}, icon("chevronRight", 14), h("span", { text: "Pokaż kod" })), codeBlock(example.source, `Kod przykładu ${example.name}`)),
          ),
        ),
      ),
    );
  }

  private async load(example: Example): Promise<void> {
    const { workspace, toasts, navigate } = this.deps;
    let result = workspace.loadExample(example.id);
    if (result.status === "needs-confirmation") {
      const sure = await confirmDialog({
        title: "Zastąpić bieżący program?",
        message: `W edytorze ${example.mode === "2d" ? "2D" : "3D"} są zmiany, które nie zostały zapisane. Wczytanie przykładu „${example.name}” je zastąpi. Poprzednia wersja trafi do kopii zapasowych (menu Plik) i będzie można ją przywrócić.`,
        confirmLabel: "Wczytaj przykład",
      });
      if (!sure) return;
      result = workspace.loadExample(example.id, { confirmed: true });
    }
    if (result.status === "loaded") {
      navigate("#/");
      toasts.show(`Wczytano przykład „${example.name}”.`);
    }
  }

  private setFilter(filter: Filter): void {
    this.filter = filter;
    let shown = 0;
    for (const example of EXAMPLES) {
      const visible = filter === "all" || example.mode === filter;
      this.cards.get(example.id)!.hidden = !visible;
      if (visible) shown++;
    }
    for (const [value, b] of this.filterButtons) b.setAttribute("aria-checked", String(value === filter));
    this.count.textContent = `Pokazano ${shown} z ${EXAMPLES.length} ${shown === 1 ? "przykładu" : "przykładów"}.`;
    this.thumbnails.forEach((t) => t.refresh());
  }

  show(): void {
    this.element.hidden = false;
    this.thumbnails.forEach((t) => t.refresh());
  }

  hide(): void {
    this.element.hidden = true;
  }
}

void countOf;
EOF
