import { h } from "../app/dom";
import { icon } from "../app/icons";
import type { ThemeController } from "../app/theme";
import { button, confirmDialog, plate } from "../app/ui";
import { CHALLENGES } from "../challenges/challenges";
import type { Workspace } from "../studio/workspace";
import { Thumbnail } from "../view/thumbnail";

export interface ChallengesPageDeps {
  workspace: Workspace;
  theme: ThemeController;
}

/** The practice tasks with their targets, and how far the user has got. */
export class ChallengesPage {
  readonly element: HTMLElement;
  private readonly list: HTMLElement;
  private readonly summary: HTMLElement;
  private readonly bar: HTMLProgressElement;
  private thumbnails: Thumbnail[] = [];

  constructor(private readonly deps: ChallengesPageDeps) {
    this.list = h("ul", { class: "challenge-list", attrs: { "aria-label": "Lista wyzwań" } });
    this.summary = h("p", { class: "progress-text tabular" });
    this.bar = h("progress", { class: "progress", attrs: { max: CHALLENGES.length, value: 0, "aria-label": "Rozwiązane wyzwania" } });
    this.element = h(
      "section",
      { class: "page page--list", attrs: { "aria-labelledby": "challenges-title", hidden: true } },
      h(
        "div",
        { class: "page-inner" },
        h(
          "header",
          { class: "page-head" },
          h("h1", { class: "page-title", attrs: { id: "challenges-title", tabindex: "-1" }, text: "Wyzwania" }),
          h("p", { class: "lead", text: "Każde wyzwanie pokazuje wzór, a Logomocja sprawdza, czy Twój program narysował to samo, niezależnie od tego, jak go napisałeś." }),
        ),
        h("div", { class: "progress-row" }, this.summary, this.bar),
        this.list,
        h(
          "div",
          { class: "page-foot" },
          button({
            label: "Wyczyść postępy",
            icon: "trash",
            variant: "quiet",
            onClick: async () => {
              const sure = await confirmDialog({ title: "Wyczyścić postępy?", message: "Wszystkie wyzwania znów będą nierozwiązane, a Twoje rozwiązania zostaną usunięte z tej przeglądarki.", confirmLabel: "Wyczyść postępy" });
              if (sure) {
                this.deps.workspace.challenges.resetAll();
                this.render();
              }
            },
          }),
        ),
      ),
    );
    deps.theme.subscribe((_c, effective) => this.thumbnails.forEach((t) => t.setTheme(effective)));
    this.render();
