      const link = h("a", { class: "challenge-link", attrs: { href: `#/wyzwania/${challenge.id}` } }, h("span", { text: challenge.title }));
      this.list.appendChild(
        h(
          "li",
          { class: `challenge-row${solved ? " is-solved" : ""}` },
          thumb.element,
          h(
            "div",
            { class: "challenge-main" },
            h("h2", { class: "challenge-name" }, link),
            h("p", { class: "challenge-text", text: challenge.brief }),
            h(
              "div",
