  readonly element: HTMLElement;
  private readonly thumbnails: Thumbnail[] = [];
  private readonly toc: HTMLElement;
  private readonly sectionEls = new Map<string, HTMLElement>();

  constructor(private readonly deps: ReferencePageDeps) {
    const article = h("div", { class: "reference-body" });
    this.toc = h("ol", { class: "toc-list" });
    for (const section of SECTIONS) {
      const el = h("section", { class: "ref-section", attrs: { id: `opis-${section.id}`, "aria-labelledby": `opis-${section.id}-title` } }, h("h2", { class: "ref-title", attrs: { id: `opis-${section.id}-title`, tabindex: "-1" }, text: section.title }));
      for (const block of section.blocks) el.appendChild(this.block(block));
      this.sectionEls.set(section.id, el);
      article.appendChild(el);
      this.toc.appendChild(h("li", {}, h("a", { class: "toc-link", attrs: { href: `#/opis/${section.id}` }, text: section.title })));
    }
    article.appendChild(this.shortcutsSection());
    this.toc.appendChild(h("li", {}, h("a", { class: "toc-link", attrs: { href: "#/opis/skroty" }, text: "Skróty klawiszowe" })));

    const tocBox = h("details", { class: "toc", attrs: { open: true } }, h("summary", { class: "toc-title", text: "Spis treści" }), h("nav", { attrs: { "aria-label": "Spis treści opisu języka" } }, this.toc));
    this.element = h(
      "section",
      { class: "page page--reference", attrs: { "aria-labelledby": "reference-title", hidden: true } },
      h(
        "div",
        { class: "page-inner page-inner--reference" },
        h(
          "header",
          { class: "page-head" },
          h("h1", { class: "page-title", attrs: { id: "reference-title", tabindex: "-1" }, text: "Opis języka" }),
          h("p", { class: "lead", text: "Wszystko, co rozumie Logomocja: polecenia z przykładami, wyrażenia, zmienne, warunki, procedury, błędy i limity. Przy każdym przykładzie jest rysunek, który naprawdę wychodzi z tego kodu." }),
        ),
        h("div", { class: "reference-layout" }, tocBox, article),
      ),
    );
    deps.theme.subscribe((_c, effective) => this.thumbnails.forEach((t) => t.setTheme(effective)));
  }

  private block(block: Block): HTMLElement {
    switch (block.type) {
      case "p":
        return h("p", { class: "prose" }, ...inline(block.text));
      case "note":
        return h("p", { class: "note" }, plate("Uwaga", "caution", "info"), h("span", {}, ...inline(block.text)));
      case "list":
        return h("ul", { class: "prose-list" }, ...block.items.map((item) => h("li", {}, ...inline(item))));
      case "table":
        return h(
          "div",
          { class: "table-wrap" },
          h(
            "table",
            { class: "table" },
            h("caption", { text: block.caption }),
            h("thead", {}, h("tr", {}, ...block.head.map((c) => h("th", { attrs: { scope: "col" }, text: c })))),
            h("tbody", {}, ...block.rows.map((row) => h("tr", {}, ...row.map((cell) => h("td", {}, ...inline(cell)))))),
          ),
        );
      case "commands":
        return h("div", { class: "commands" }, ...block.ids.map((id) => this.command(COMMAND_DOCS.find((c) => c.id === id)!)));
      case "example": {
        const ex = getExampleBlock(block.id);
        return this.figure(ex, ex.caption, ex.expectError !== undefined);
      }
    }
  }

  private command(doc: CommandDoc): HTMLElement {
    const names = h("span", { class: "command-names" }, ...doc.polish.flatMap((n, i) => [i ? ", " : "", h("code", { class: i === 0 ? "command-main" : "command-alias", text: n })]));
    const english = doc.english.length
      ? h("span", { class: "command-english" }, h("span", { class: "muted", text: "po angielsku: " }), ...doc.english.flatMap((n, i) => [i ? ", " : "", h("code", { class: "command-alias", text: n })]))
      : null;
    return h(
      "article",
      { class: "command", attrs: { id: `polecenie-${doc.id}`, "aria-labelledby": `polecenie-${doc.id}-name` } },
      h(
        "header",
        { class: "command-head" },
        h("h3", { class: "command-title", attrs: { id: `polecenie-${doc.id}-name` } }, names, doc.syntax ? h("span", { class: "command-syntax", text: ` ${doc.syntax}` }) : null),
        doc.threeD ? plate("tylko 3D", "tourist") : null,
      ),
      english,
      h("p", { class: "prose" }, ...inline(doc.summary)),
      doc.details ? h("p", { class: "prose" }, ...inline(doc.details)) : null,
      this.figure({ ...doc.example }, doc.example.caption, false),
    );
  }

  private figure(example: Example, caption: string | undefined, failing: boolean): HTMLElement {
    const result = run(example.code, example.mode);
    const preview = failing
      ? h(
          "div",
          { class: "ref-error" },
          plate("Błąd", "stop", "alert"),
          h("p", { text: result.error ? `Wiersz ${result.error.line}, kolumna ${result.error.column}: ${result.error.message}` : "" }),
        )
      : (() => {
          const thumb = new Thumbnail(result.segments, example.mode, this.deps.theme.effective, "Rysunek z tego przykładu");
          this.thumbnails.push(thumb);
          return thumb.element;
        })();
    return h(
      "figure",
      { class: "ref-example" },
      h("div", { class: "ref-code" }, h("div", { class: "ref-code-head" }, plate(example.mode === "2d" ? "2D" : "3D", example.mode === "2d" ? "info" : "tourist"), button({ label: "Otwórz w pracowni", icon: "play2", variant: "quiet", onClick: () => void this.open(example) })), codeBlock(example.code)),
      preview,
      caption ? h("figcaption", { class: "ref-caption", text: caption }) : null,
    );
  }

  private async open(example: Example): Promise<void> {
    const { workspace, toasts, navigate } = this.deps;
    let result = workspace.loadSnippet(example.code, example.mode);
    if (result.status === "needs-confirmation") {
      const sure = await confirmDialog({
        title: "Zastąpić bieżący program?",
        message: `W edytorze ${example.mode === "2d" ? "2D" : "3D"} są zmiany, które nie zostały zapisane. Przykład z opisu je zastąpi. Poprzednia wersja trafi do kopii zapasowych (menu Plik).`,
        confirmLabel: "Otwórz przykład",
      });
      if (!sure) return;
      result = workspace.loadSnippet(example.code, example.mode, { confirmed: true });
    }
    if (result.status === "loaded") {
      navigate("#/");
      toasts.show("Przykład otwarty w pracowni.");
    }
  }

  private shortcutsSection(): HTMLElement {
    const rows = SHORTCUTS.map((s) => h("tr", {}, h("td", {}, h("kbd", { class: "kbd", text: formatKeys(s.keys) })), h("td", { text: s.label }), h("td", { text: s.group })));
    return h(
      "section",
      { class: "ref-section", attrs: { id: "opis-skroty", "aria-labelledby": "opis-skroty-title" } },
      h("h2", { class: "ref-title", attrs: { id: "opis-skroty-title", tabindex: "-1" }, text: "Skróty klawiszowe" }),
      h(
        "div",
        { class: "table-wrap" },
        h("table", { class: "table" }, h("caption", { text: "Skróty działają w całej pracowni" }), h("thead", {}, h("tr", {}, h("th", { attrs: { scope: "col" }, text: "Klawisze" }), h("th", { attrs: { scope: "col" }, text: "Działanie" }), h("th", { attrs: { scope: "col" }, text: "Gdzie" }))), h("tbody", {}, ...rows)),
      ),
    );
  }

  /** Scrolls to a section when the address names one. */
  show(anchor?: string): void {
    this.element.hidden = false;
    this.thumbnails.forEach((t) => t.refresh());
    const target = anchor ? document.getElementById(`opis-${anchor}`) ?? document.getElementById(`polecenie-${anchor}`) : null;
    const scroller = this.element.closest(".app-main") as HTMLElement | null;
    if (target) {
      target.scrollIntoView({ block: "start" });
      (target.querySelector("h2, h3") as HTMLElement | null)?.focus({ preventScroll: true });
    } else if (scroller) {
      scroller.scrollTop = 0;
    }
  }

  hide(): void {
    this.element.hidden = true;
  }
}

void icon;
EOF
