import { CHALLENGES } from "../challenges/challenges";
import { run, type Mode, type RunResult } from "../lang";
import { ChallengesPage } from "../pages/challenges-page";
import { ExamplesPage } from "../pages/examples-page";
import { ReferencePage } from "../pages/reference-page";
import { WorkspacePage } from "../pages/workspace-page";
import { browserScheduler, type Scheduler } from "../studio/scheduler";
import { Workspace } from "../studio/workspace";
import { showShortcutsDialog } from "./dialogs";
import { h } from "./dom";
import { icon, logoMark, type IconName } from "./icons";
import { formatRoute, parseRoute, type Route } from "./router";
import { browserSystemTheme, ThemeController, type SystemTheme } from "./theme";
import { Toasts } from "./ui";

export const VERSION = "1.0.0";

export interface AppOptions {
  root: HTMLElement;
  storage: Storage | null;
  scheduler?: Scheduler;
  system?: SystemTheme | null;
}

/** The testing hook the specification asks for. */
export interface LogomocjaHook {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

interface NavItem {
  label: string;
  hash: string;
  icon: IconName;
  names: Route["name"][];
}

const NAV: NavItem[] = [
  { label: "Pracownia", hash: "#/", icon: "pencil", names: ["workspace"] },
  { label: "Przykłady", hash: "#/przyklady", icon: "gallery", names: ["examples"] },
  { label: "Wyzwania", hash: "#/wyzwania", icon: "flag", names: ["challenges", "challenge"] },
  { label: "Opis języka", hash: "#/opis", icon: "book", names: ["reference"] },
];

const TITLES: Record<Route["name"], string> = {
  workspace: "Pracownia",
  examples: "Przykłady",
  challenges: "Wyzwania",
  challenge: "Wyzwanie",
  reference: "Opis języka",
  link: "Pracownia",
};

const nextFrame = () =>
  new Promise<void>((resolve) => {
    let done = false;
    const finish = () => {
      if (!done) {
        done = true;
        resolve();
      }
    };
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => finish());
    setTimeout(finish, 120); // a hidden tab never fires animation frames
  });

export class App {
  readonly workspace: Workspace;
  readonly theme: ThemeController;
  readonly toasts = new Toasts();
  readonly workspacePage: WorkspacePage;
  private readonly examplesPage: ExamplesPage;
  private readonly challengesPage: ChallengesPage;
  private readonly referencePage: ReferencePage;
  private readonly navLinks: { item: NavItem; el: HTMLAnchorElement }[] = [];
  private readonly themeButton: HTMLButtonElement;
  private current: Route = { name: "workspace" };
  private started = false;

  constructor(private readonly options: AppOptions) {
    const { root, storage } = options;
    this.theme = new ThemeController(storage, options.system === undefined ? browserSystemTheme() : options.system, (effective) => {
      document.documentElement.setAttribute("data-theme", effective);
    });
    this.workspace = new Workspace({ storage, scheduler: options.scheduler ?? browserScheduler });
    const navigate = (hash: string) => {
      if (location.hash === hash) this.route(parseRoute(hash));
      else location.hash = hash;
    };
    const nextChallenge = (id: string) => {
      const index = CHALLENGES.findIndex((c) => c.id === id);
      const next = CHALLENGES[index + 1];
      return next ? `#/wyzwania/${next.id}` : null;
    };
    this.workspacePage = new WorkspacePage({ workspace: this.workspace, theme: this.theme, toasts: this.toasts, storage, navigate, nextChallenge });
    this.examplesPage = new ExamplesPage({ workspace: this.workspace, toasts: this.toasts, theme: this.theme, navigate });
    this.challengesPage = new ChallengesPage({ workspace: this.workspace, theme: this.theme });
    this.referencePage = new ReferencePage({ workspace: this.workspace, theme: this.theme, toasts: this.toasts, navigate });

    this.themeButton = h("button", { class: "btn btn--icon btn--header", attrs: { type: "button" }, on: { click: () => this.theme.cycle() } });
    const renderTheme = () => this.renderThemeButton();
    this.theme.subscribe(renderTheme);
    renderTheme();

    const navList = (label: string, className: string) =>
      h(
        "nav",
        { class: className, attrs: { "aria-label": label } },
        h(
          "ul",
          { class: "nav-list" },
          ...NAV.map((item) => {
            const link = h("a", { class: "nav-link", attrs: { href: item.hash } }, icon(item.icon, 18), h("span", { text: item.label }));
            this.navLinks.push({ item, el: link });
            return h("li", {}, link);
          }),
        ),
      );

    const header = h(
      "header",
      { class: "topbar" },
      h("a", { class: "brand", attrs: { href: "#/", "aria-label": "Logomocja – strona główna pracowni" } }, logoMark(30), h("span", { class: "brand-name", text: "Logomocja" })),
      navList("Główna nawigacja", "topnav"),
      h("span", { class: "topbar-spacer" }),
      h("button", { class: "btn btn--icon btn--header", attrs: { type: "button", title: "Skróty klawiszowe (Ctrl+/)", "aria-label": "Skróty klawiszowe" }, on: { click: () => showShortcutsDialog() } }, icon("keyboard", 20)),
      this.themeButton,
    );
    const main = h(
      "main",
      { class: "app-main", attrs: { id: "main", tabindex: "-1" } },
      this.workspacePage.element,
      this.examplesPage.element,
      this.challengesPage.element,
      this.referencePage.element,
    );
    const bottom = navList("Nawigacja dolna", "bottomnav");
    const skip = h("a", { class: "skip-link", attrs: { href: "#main" }, text: "Przejdź do treści", on: { click: (e) => { e.preventDefault(); main.focus(); } } });
    const shell = h("div", { class: "app" }, skip, header, main, bottom, this.toasts.element);
    root.replaceChildren(shell);

    window.addEventListener("hashchange", () => this.route(parseRoute(location.hash)));
    document.addEventListener("keydown", (event) => this.onKeyDown(event));
  }

  private renderThemeButton(): void {
    const labels = { auto: "automatyczny (jak w systemie)", light: "jasny", dark: "ciemny" } as const;
    const next = { auto: "jasny", light: "ciemny", dark: "automatyczny" } as const;
    const choice = this.theme.choice;
    const name: IconName = choice === "auto" ? "monitor" : choice === "light" ? "sun" : "moon";
    this.themeButton.replaceChildren(icon(name, 20));
    this.themeButton.setAttribute("aria-label", `Motyw: ${labels[choice]}. Przełącz na ${next[choice]}.`);
    this.themeButton.title = `Motyw: ${labels[choice]}. Kliknij, aby przełączyć na ${next[choice]}.`;
  }

  /** Shows the page the address names. The first call also draws the restored draft. */
  start(): void {
    if (!this.started) {
      this.started = true;
      this.workspace.start();
    }
    this.route(parseRoute(location.hash), true);
  }

  private route(route: Route, initial = false): void {
    if (route.name === "link") {
      const result = this.workspace.openPermalink(route.hash);
      history.replaceState(null, "", `${location.pathname}${location.search}#/`);
      this.toasts.show(result ? "Wczytano program z linku. Poprzedni szkic jest w kopiach zapasowych (menu Plik)." : "Ten adres nie zawiera poprawnego programu, więc nic nie zmieniono.", { timeout: 7000 });
      route = { name: "workspace" };
    }
    this.current = route;
    const onWorkspace = route.name === "workspace" || route.name === "challenge";
    if (onWorkspace) {
      this.examplesPage.hide();
      this.challengesPage.hide();
      this.referencePage.hide();
      this.workspacePage.show(route.name === "challenge" ? route.id : undefined);
    } else {
      this.workspacePage.hide();
      this.examplesPage.hide();
      this.challengesPage.hide();
      this.referencePage.hide();
      if (route.name === "examples") this.examplesPage.show();
      else if (route.name === "challenges") this.challengesPage.show();
      else if (route.name === "reference") this.referencePage.show(route.anchor);
    }
    for (const { item, el } of this.navLinks) {
      if (item.names.includes(route.name)) el.setAttribute("aria-current", "page");
      else el.removeAttribute("aria-current");
    }
    document.title = route.name === "workspace" ? "Logomocja – pracownia żółwia" : `${TITLES[route.name]} – Logomocja`;
    const main = document.getElementById("main");
    if (main && route.name !== "reference") main.scrollTop = 0;
    if (!initial) {
      const heading = (route.name === "workspace" || route.name === "challenge" ? this.workspacePage.element : main)?.querySelector<HTMLElement>("h1:not([hidden])");
      heading?.focus({ preventScroll: true });
    }
    void formatRoute;
  }

  // ---- keyboard ----------------------------------------------------------------------------

  private onKeyDown(event: KeyboardEvent): void {
    if (document.querySelector("dialog[open]") || document.querySelector(".menu-list")) return;
    const mod = event.ctrlKey || event.metaKey;
    const target = event.target as HTMLElement | null;
    const typing = !!target && (target.tagName === "INPUT" || target.tagName === "SELECT" || (target.tagName === "TEXTAREA" && !target.classList.contains("editor-input")) || target.isContentEditable);
    const page = this.workspacePage;
    if (mod && event.key === "/") {
      event.preventDefault();
      showShortcutsDialog();
    } else if (event.key === "?" && !typing && target?.tagName !== "TEXTAREA") {
      event.preventDefault();
      showShortcutsDialog();
    } else if (page.isVisible) {
      if (mod && event.key === "Enter") {
        event.preventDefault();
        page.run();
      } else if ((mod && event.key === ".") || event.key === "F10") {
        event.preventDefault();
        page.step();
      } else if (event.key === "Escape" && this.workspace.studio.state.status === "running") {
        event.preventDefault();
        page.pause();
      } else if (event.altKey && event.code === "KeyR") {
        event.preventDefault();
        page.reset();
      }
    }
  }

  // ---- testing hook -------------------------------------------------------------------------

  /** Loads a program as if pasted, runs it to the end, frames it, and resolves once it is on screen. */
  async open(source: string, mode: Mode): Promise<RunResult> {
    if (location.hash !== "#/" && location.hash !== "") {
      history.replaceState(null, "", `${location.pathname}${location.search}#/`);
    }
    const result = this.workspace.paste(source, mode);
    this.route({ name: "workspace" }, true);
    const viewport = this.workspacePage.viewport;
    viewport.refresh();
    viewport.fit(true);
    viewport.paintNow();
    await nextFrame();
    viewport.refresh();
    viewport.fit(true);
    viewport.paintNow();
    await nextFrame();
    return { segments: result.segments, error: result.error };
  }

