input.command:
cat > src/styles/base.css <<'EOF'
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  color-scheme: light;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
html[data-theme="dark"] {
  color-scheme: dark;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 var(--fs-md) / 1.45 var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}
ul,
ol {
  padding: 0;
}

a {
  color: var(--blue-ink);
  text-underline-offset: 0.18em;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

::selection {
  background: var(--selection);
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.topbar :focus-visible,
.bottomnav :focus-visible {
  outline-color: var(--yellow);
}

* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-radius: 6px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-track {
  background: transparent;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  z-index: 100;
  left: 8px;
  top: -48px;
  padding: 8px 14px;
  border-radius: var(--r-md);
  background: var(--yellow);
  color: var(--on-yellow);
  font-weight: 700;
  text-decoration: none;
}
.skip-link:focus {
  top: 8px;
}

.tabular {
  font-variant-numeric: tabular-nums;
}
.muted {
  color: var(--ink-2);
}
.stack > * + * {
  margin-top: var(--s-3);
}

.kbd {
  display: inline-block;
  min-width: 1.6em;
  padding: 1px 6px;
