  background: var(--green-bg);
}
.progress::-moz-progress-bar {
  background: var(--green-bg);
}

/* ---------- menu ---------- */
.menu {
  display: inline-flex;
}
.menu-trigger {
  gap: 6px;
}
.menu-list {
  position: fixed;
  z-index: 70;
  min-width: 250px;
  max-width: calc(100vw - 16px);
  padding: 4px;
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-2);
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 38px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--r-md);
  background: transparent;
  color: var(--ink);
  font: 500 var(--fs-md) / 1.2 var(--font-ui);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item:focus-visible {
  background: var(--blue-tint);
  outline: none;
}
.menu-item:focus-visible {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.menu-item[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.menu-item-hint {
  margin-left: auto;
  padding-left: 16px;
  color: var(--ink-3);
  font-size: var(--fs-xs);
}
.menu-icon-gap {
  width: 16px;
  flex: none;
}
.menu-separator {
  height: 1px;
  margin: 4px 6px;
  background: var(--line);
}

/* ---------- dialog ---------- */
.dialog {
  width: min(520px, calc(100vw - 24px));
  max-height: calc(100dvh - 24px);
  padding: 0;
  border: 1px solid var(--line-strong);
  border-radius: var(--r-lg);
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow-2);
  overflow: hidden;
}
.dialog[open] {
  display: flex;
  flex-direction: column;
}
.dialog--wide {
  width: min(720px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(8, 14, 24, 0.58);
}
.dialog-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 10px 10px 20px;
  border-bottom: 1px solid var(--line);
}
.dialog-title {
  flex: 1;
  font-size: var(--fs-lg);
  font-weight: 700;
  line-height: 1.25;
}
.dialog-subtitle {
  margin: 0 0 8px;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.dialog-body {
  padding: 16px 20px 20px;
  overflow: auto;
}
.dialog-foot {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 20px;
  border-top: 1px solid var(--line);
  background: var(--surface-2);
}
.share-link {
  font-size: var(--fs-sm);
}
.shortcut-groups {
  display: grid;
  gap: 20px;
}
.shortcut-list {
  display: grid;
  grid-template-columns: minmax(130px, auto) 1fr;
  gap: 8px 16px;
  align-items: center;
}
.shortcut-list dt {
  white-space: nowrap;
}
.shortcut-list dd {
  color: var(--ink-2);
}
.backup-list {
  list-style: none;
  display: grid;
  gap: 8px;
  margin: 12px 0 0;
}
.backup {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--surface-2);
}
.backup-main {
  flex: 1;
  min-width: 0;
}
.backup-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.backup-preview {
  display: block;
  margin-top: 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 400 var(--fs-sm) var(--font-code);
}
.backup-actions {
  display: flex;
  gap: 4px;
}

/* ---------- toasts ---------- */
.toasts {
  position: fixed;
  z-index: 80;
  left: 50%;
  bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(480px, calc(100vw - 24px));
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 6px 8px 14px;
  border-radius: 8px;
  background: var(--ink);
  color: var(--surface);
  box-shadow: var(--shadow-2);
  font-size: var(--fs-sm);
  line-height: 1.35;
  pointer-events: auto;
  animation: toast-in var(--t-med) var(--ease);
}
.toast-text {
  flex: 1;
}
.toast .btn--quiet {
  color: inherit;
}
.toast .btn--quiet:hover {
  background: rgba(127, 127, 127, 0.28);
  color: inherit;
}
.toast .toast-action {
  color: inherit;
  text-decoration: underline;
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
EOF
echo ok

