}
.console-row .plate {
  margin-top: 1px;
}
.console-text {
  flex: 1;
  min-width: 0;
  font-size: var(--fs-sm);
  line-height: 1.4;
  color: var(--ink);
  overflow-wrap: anywhere;
}
.console-text p + p {
  margin-top: 2px;
}
.console[data-tone="error"] {
  background: var(--red-tint);
}
.console[data-tone="paused"] {
  background: var(--surface);
}

/* the route: the call stack drawn as a sign that lists where in the program the turtle is */
.route {
  flex: none;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 6px 12px;
  border-top: 1px solid var(--line);
  background: var(--surface-2);
}
.route-label {
  flex: none;
  font: 600 var(--fs-xs) / 1 var(--font-plate);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.route-body {
  flex: 1;
  min-width: 0;
}
.route-empty {
  color: var(--ink-2);
  font-size: var(--fs-sm);
  line-height: 1.35;
}
.route-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 2px;
  list-style: none;
}
.route-item + .route-item::before {
