  transform: rotate(45deg);
}
.route-item {
  display: inline-flex;
  align-items: center;
}
.route-plate {
  padding: 3px 9px;
  border: 0;
  border-radius: var(--r-md);
  background: var(--blue-btn);
  color: var(--on-blue-btn);
  box-shadow: inset 0 0 0 1.5px rgba(255, 255, 255, 0.7);
  font: 600 var(--fs-sm) / 1.3 var(--font-plate);
