  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}
.table th {
  background: var(--surface-2);
  color: var(--ink-2);
  font-weight: 700;
}

@media (max-width: 959px) {
  .reference-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }
  .toc {
    position: static;
    padding: 4px 12px;
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--r-lg);
  }
}
@media (max-width: 719px) {
  .page--list,
  .page--reference {
    padding: 16px 12px 40px;
  }
  .page-title {
    font-size: 1.4rem;
  }
  .lead {
    font-size: var(--fs-md);
  }
  .challenge-row {
    grid-template-columns: 96px minmax(0, 1fr);
    gap: 12px;
  }
  .challenge-go {
    display: none;
  }
  .challenge-text {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .ref-example {
    grid-template-columns: minmax(0, 1fr);
  }
  .cards {
    grid-template-columns: minmax(0, 1fr);
  }
}
