import { GlobalRegistrator } from "@happy-dom/global-registrator";

/** Installs a browser-like global environment (happy-dom) for tests that boot the real app. */
export function installDom(): () => void {
  GlobalRegistrator.register({ url: "http://localhost/app/", width: 1280, height: 800 });
  // happy-dom has no layout, so give elements a size the way a browser would.
  Object.defineProperty(HTMLElement.prototype, "getBoundingClientRect", {
    configurable: true,
    value() {
      return { x: 0, y: 0, left: 0, top: 0, right: 800, bottom: 600, width: 800, height: 600, toJSON() {} };
    },
  });
  return () => GlobalRegistrator.unregister();
}
EOF
cat > tests/app.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { installDom } from "./dom-env";
import { MemoryStorage } from "./fakes";

let teardown: () => void;
let App: typeof import("../src/app/app").App;

beforeAll(async () => {
  teardown = installDom();
  ({ App } = await import("../src/app/app"));
});
afterAll(() => teardown());

function boot(storage = new MemoryStorage()) {
  document.body.innerHTML = '<div id="app"></div>';
  const app = new App({ root: document.getElementById("app")!, storage, system: null });
  window.history.replaceState(null, "", "/app/#/");
  app.start();
  return { app, storage, hook: app.hook() };
}

describe("app: boots and exposes the testing hook", () => {
  test("the hook has a version, run and open", () => {
    const { hook } = boot();
    expect(typeof hook.version).toBe("string");
    expect(hook.version.length).toBeGreaterThan(0);
    expect(typeof hook.run).toBe("function");
    expect(typeof hook.open).toBe("function");
  });

  test("the page has a main landmark, one h1 per page, and a labelled toolbar", () => {
    boot();
    expect(document.querySelectorAll("main")).toHaveLength(1);
    expect(document.querySelector('[role="toolbar"]')?.getAttribute("aria-label")).toBeTruthy();
    expect(document.querySelector("h1")?.textContent).toBe("Pracownia");
  });

  test("the first screen holds the Kwadrat example, already drawn", () => {
    const { app } = boot();
    const editor = document.querySelector<HTMLTextAreaElement>(".editor-input")!;
    expect(editor.value).toContain("powtorz 4 [");
    expect(app.workspace.studio.state.segments).toHaveLength(4);
  });
});

describe("app: hook.run is the interpreter, without touching the UI", () => {
  test("returns segments and a Polish error with line and column", () => {
    const { hook, app } = boot();
    const before = app.workspace.studio.state.source;
    const ok = hook.run("np 100 pw 90 np 50", "2d");
    expect(ok.error).toBeNull();
    expect(ok.segments).toHaveLength(2);
    expect(ok.segments[0]).toEqual({ from: [0, 0, 0], to: [0, 100, 0], color: "#16866a", width: 3 });
    const bad = hook.run("np 100\nskacz", "2d");
    expect(bad.segments).toEqual([]);
    expect(bad.error).toEqual({ message: "Nieznane polecenie „skacz”.", line: 2, column: 1 });
    expect(app.workspace.studio.state.source).toBe(before);
  });
});

describe("app: hook.open puts the program in the editor and draws it", () => {
  test("the editor shows the text, the drawing is the interpreter's, and the promise resolves with the same result", async () => {
    const { hook, app } = boot();
    const source = "gora 90 powtorz 4 [np 20 pw 90]";
    const result = await hook.open(source, "3d");
    expect(result).toEqual(hook.run(source, "3d"));
    expect(document.querySelector<HTMLTextAreaElement>(".editor-input")!.value).toBe(source);
    expect(app.workspace.studio.state.mode).toBe("3d");
    expect(app.workspace.studio.state.status).toBe("finished");
    expect(app.workspace.studio.state.segments).toEqual(result.segments);
    expect(document.querySelector('[role="radio"][aria-checked="true"]')?.textContent).toContain("3D");
  });

  test("a parse error draws nothing and marks the line and column in the editor", async () => {
    const { hook } = boot();
    const result = await hook.open("np 10\n  skacz 5", "2d");
    expect(result.segments).toEqual([]);
    expect(result.error).toEqual({ message: "Nieznane polecenie „skacz”.", line: 2, column: 3 });
    await new Promise((r) => setTimeout(r, 20));
    const lines = document.querySelectorAll(".editor-code .line");
    expect(lines[1]!.classList.contains("is-error")).toBe(true);
    expect(lines[1]!.querySelector(".error-mark")?.textContent).toBe("skacz");
    expect(lines[1]!.querySelector(".lens")?.textContent).toBe("Nieznane polecenie „skacz”.");
    expect(document.querySelector(".gutter-line.is-error")?.textContent).toBe("2");
    expect(document.querySelector(".console")?.textContent).toContain("Wiersz 2, kolumna 3");
  });

  test("repeated opens never accumulate, reset and open again gives the same drawing", async () => {
    const { hook, app } = boot();
    const first = await hook.open("powtorz 3 [np 10 pw 120]", "2d");
    await hook.open("powtorz 3 [np 10 pw 120]", "2d");
    expect(app.workspace.studio.state.segments).toHaveLength(3);
    app.workspacePage.reset();
    expect(app.workspace.studio.state.segments).toEqual([]);
    const again = await hook.open("powtorz 3 [np 10 pw 120]", "2d");
    expect(again).toEqual(first);
  });

  test("it works from any page and brings the workspace back", async () => {
    const { hook } = boot();
    window.location.hash = "#/opis";
    window.dispatchEvent(new window.HashChangeEvent("hashchange"));
    await hook.open("np 5", "2d");
    expect(document.querySelector<HTMLElement>(".page--workspace")!.hidden).toBe(false);
  });
});

describe("app: the draft survives a reload", () => {
  test("after typing, a new app over the same storage shows the same text", async () => {
    const first = boot();
    const editor = document.querySelector<HTMLTextAreaElement>(".editor-input")!;
    editor.value = "np 77 ; moje";
    editor.dispatchEvent(new window.Event("input", { bubbles: true }));
    const second = boot(first.storage);
    expect(document.querySelector<HTMLTextAreaElement>(".editor-input")!.value).toBe("np 77 ; moje");
    expect(second.app.workspace.studio.state.source).toBe("np 77 ; moje");
  });
});
EOF
bun test tests/app.test.ts 2>&1 | tail -40

