// Serves ./dist under a sub-path with NO rewrite rules (a plain static host).
const base = process.argv[2]!; const root = process.argv[3]!;
const server = Bun.serve({ port: 4799, async fetch(req) {
  const url = new URL(req.url);
  if (!url.pathname.startsWith(base)) return new Response("not found", { status: 404 });
  let rel = url.pathname.slice(base.length);
  if (rel === "" || rel.endsWith("/")) rel += "index.html";
  const file = Bun.file(`${root}/${rel}`);
  return (await file.exists()) ? new Response(file) : new Response("not found", { status: 404 });
}});
console.log("listening", server.port);
EOF
