// Renders the app's own canvas drawing code to PNG files so the pictures can be looked at.
import { createCanvas, GlobalFonts } from "@napi-rs/canvas";
import { readdirSync } from "node:fs";
import { run } from "/work/src/lang";
import { EXAMPLES, findExample } from "/work/src/examples";
import { draw2d, draw3d } from "/work/src/view/draw";
import { fit2d, toScreen2d } from "/work/src/view/camera2d";
import { DEFAULT_CAMERA, PRESETS, fit3d } from "/work/src/view/camera3d";
import { DEFAULT_PALETTES } from "/work/src/view/palette";
import { INITIAL_TURTLE } from "/work/src/lang";

const fontDir = "/work/src/assets/fonts";
for (const f of readdirSync(fontDir).filter((n) => n.endsWith(".woff2"))) {
  const m = /^(barlow-semi-condensed|barlow|jetbrains-mono)-latin-(\d+)/.exec(f);
  if (m) GlobalFonts.registerFromPath(`${fontDir}/${f}`, m[1] === "barlow" ? "Barlow" : m[1] === "barlow-semi-condensed" ? "Barlow Semi Condensed" : "JetBrains Mono");
}

const [,, id, theme = "light", size = "900x640", preset = "perspective", out] = process.argv;
const [W, H] = size.split("x").map(Number) as [number, number];
const example = findExample(id!)!;
const { segments } = run(example.source, example.mode);
const canvas = createCanvas(W, H);
const ctx = canvas.getContext("2d") as unknown as CanvasRenderingContext2D;
const palette = DEFAULT_PALETTES[theme as "light" | "dark"];
const turtle = { ...INITIAL_TURTLE, position: segments.at(-1)?.to ?? [0, 0, 0], heading: [0.6, 0.8, 0] as [number, number, number] };
const scene = { segments, turtle };
const options = { grid: true, axes: true, turtle: true, lineScale: 1 };
const points = [...segments.flatMap((s) => [s.from, s.to]), [0, 0, 0] as [number, number, number]];
if (example.mode === "2d") {
  const cam = fit2d(points.map((p) => [p[0], p[1]] as [number, number]), W, H, 56);
  draw2d(ctx, W, H, cam, scene, palette, options);
} else {
  const cam = fit3d({ ...DEFAULT_CAMERA, ...(PRESETS as any)[preset] }, points, W, H);
  draw3d(ctx, W, H, cam, scene, palette, options);
}
await Bun.write(out ?? `/tmp/vis/out/${id}-${theme}.png`, canvas.toBuffer("image/png"));
console.log("wrote", out ?? `/tmp/vis/out/${id}-${theme}.png`, segments.length, "segments");
EOF
