// Cross-checks CSS class names against the TypeScript that creates elements.
// Run: bun tools/class-audit.ts   (exit 1 when a class used in code has no CSS rule and is not allow-listed)
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const walk = (dir: string): string[] =>
  readdirSync(dir).flatMap((n) => (statSync(join(dir, n)).isDirectory() ? walk(join(dir, n)) : [join(dir, n)]));

const css = walk("src/styles").filter((f) => f.endsWith(".css")).map((f) => readFileSync(f, "utf8")).join("\n");
const cssClasses = new Set([...css.matchAll(/\.([a-zA-Z][\w-]*)/g)].map((m) => m[1]!));

const ts = walk("src").filter((f) => f.endsWith(".ts")).map((f) => readFileSync(f, "utf8")).join("\n");
const used = new Set<string>();
for (const m of ts.matchAll(/class:\s*(?:"([^"]+)"|`([^`]+)`)/g)) {
  const text = (m[1] ?? m[2]!).replace(/\$\{[^}]*\}/g, " ");
  for (const c of text.split(/\s+/)) if (/^[a-z][\w-]*$/.test(c)) used.add(c);
}
for (const m of ts.matchAll(/classList\.(?:add|toggle|remove)\("([^"]+)"/g)) used.add(m[1]!);
for (const m of ts.matchAll(/class="([^"]+)"/g)) m[1]!.split(/\s+/).forEach((c) => used.add(c));
for (const m of ts.matchAll(/`tok-\$\{[^}]+\}`/g)) void m;

// created with template strings or states; verified by hand
const allowed = new Set(["icon", "logo-mark", "btn-label--wide", "menu-icon-gap"]);
const missing = [...used].filter((c) => !cssClasses.has(c) && !allowed.has(c)).sort();
const unused = [...cssClasses].filter((c) => !used.has(c) && !ts.includes(c) && !/^(is-|plate--|btn--|tok-|result--|route-item)/.test(c)).sort();

console.log(`classes used in code: ${used.size}, in CSS: ${cssClasses.size}`);
console.log(missing.length ? `USED BUT NOT STYLED: ${missing.join(", ")}` : "every class used in code has a rule");
console.log(unused.length ? `STYLED BUT NEVER USED: ${unused.join(", ")}` : "no dead CSS classes");
process.exit(missing.length ? 1 : 0);
EOF
