import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { buildPermalink } from "../src/share/permalink";
import { installDom } from "./dom-env";
import { MemoryStorage } from "./fakes";

let teardown: () => void;
let App: typeof import("../src/app/app").App;

beforeAll(async () => {
  teardown = installDom();
  ({ App } = await import("../src/app/app"));
});
afterAll(() => teardown());

class ManualSystem {
  dark = false;
  private l = new Set<() => void>();
  get matchesDark() {
    return this.dark;
  }
  onChange(fn: () => void) {
    this.l.add(fn);
    return () => this.l.delete(fn);
  }
  flip(v: boolean) {
    this.dark = v;
    this.l.forEach((f) => f());
  }
}

function boot(options: { storage?: MemoryStorage; hash?: string; system?: ManualSystem } = {}) {
  document.body.innerHTML = '<div id="app"></div>';
  document.documentElement.setAttribute("data-theme", "light");
  const storage = options.storage ?? new MemoryStorage();
  const system = options.system ?? new ManualSystem();
  window.history.replaceState(null, "", `/app/${options.hash ?? "#/"}`);
  const app = new App({ root: document.getElementById("app")!, storage, system });
  app.start();
  return { app, storage, system };
}

const byText = (selector: string, text: string) =>
  [...document.querySelectorAll<HTMLElement>(selector)].find((el) => el.textContent?.trim() === text || el.getAttribute("aria-label") === text);
const click = (el: Element | null | undefined) => {
  expect(el).toBeTruthy();
  el!.dispatchEvent(new window.MouseEvent("click", { bubbles: true, cancelable: true }));
};
const key = (target: EventTarget, init: KeyboardEventInit) =>
  target.dispatchEvent(new window.KeyboardEvent("keydown", { bubbles: true, cancelable: true, ...init }));
const tick = (ms = 10) => new Promise((r) => setTimeout(r, ms));
const editorEl = () => document.querySelector<HTMLTextAreaElement>(".editor-input")!;
const type = (text: string) => {
  editorEl().value = text;
  editorEl().dispatchEvent(new window.Event("input", { bubbles: true }));
};

describe("ui: run, step, pause, reset through the buttons", () => {
  test("Uruchom draws the program; Reset clears it", () => {
    const { app } = boot();
    app.workspace.studio.setSpeed(6);
    type("powtorz 3 [np 30 pw 120]");
    click(byText(".toolbar .btn", "Uruchom"));
    expect(app.workspace.studio.state.status).toBe("finished");
    expect(app.workspace.studio.state.segments).toHaveLength(3);
    click(byText(".toolbar .btn", "Reset"));
    expect(app.workspace.studio.state.segments).toHaveLength(0);
    expect(app.workspace.studio.state.status).toBe("idle");
  });

  test("Krok executes one command and highlights its line; the console names the state", () => {
    const { app } = boot();
    type("np 10\npw 90\nnp 20");
    click(byText(".toolbar .btn", "Krok"));
    expect(app.workspace.studio.state.status).toBe("paused");
    expect(document.querySelectorAll(".editor-code .line")[0]!.classList.contains("is-current")).toBe(false); // render is coalesced
    return tick(30).then(() => {
      expect(document.querySelectorAll(".editor-code .line")[0]!.classList.contains("is-current")).toBe(true);
      expect(document.querySelector(".gutter-line.is-current")?.textContent).toBe("1");
      expect(document.querySelector(".console")?.textContent).toContain("Wstrzymano");
      expect(byText(".toolbar .btn", "Wznów")).toBeTruthy();
    });
  });

  test("Pauza is available only while running and the animation really stops", async () => {
    const { app } = boot();
    app.workspace.studio.setSpeed(1);
    type("powtorz 100 [np 1 pw 1]");
    const pause = byText(".toolbar .btn", "Pauza")!;
    expect(pause.getAttribute("aria-disabled")).toBe("true");
    click(byText(".toolbar .btn", "Uruchom"));
    expect(app.workspace.studio.state.status).toBe("running");
    expect(pause.getAttribute("aria-disabled")).toBe("false");
    expect(byText(".toolbar .btn", "Uruchom")!.getAttribute("aria-disabled")).toBe("true");
    click(pause);
    expect(app.workspace.studio.state.status).toBe("paused");
    const before = app.workspace.studio.state.segments.length;
    await tick(80);
    expect(app.workspace.studio.state.segments.length).toBe(before);
  });

  test("a disabled-looking button does nothing when pressed (it stays focusable on purpose)", () => {
    const { app } = boot();
    click(byText(".toolbar .btn", "Pauza"));
    expect(app.workspace.studio.state.status).toBe("finished"); // boot already drew the square
  });

  test("a parse error from Uruchom keeps the editor in front and shows the message with a way to jump to it", () => {
    boot();
    type("np 10\nskacz");
    click(byText(".toolbar .btn", "Uruchom"));
    const text = document.querySelector(".console")!.textContent!;
    expect(text).toContain("Wiersz 2, kolumna 1: Nieznane polecenie „skacz”.");
    expect(text).toContain("nic się nie narysuje");
    expect(byText(".console .btn", "Pokaż w kodzie")).toBeTruthy();
  });

  test("a run-time error says the drawing was kept", async () => {
    const { app } = boot();
    app.workspace.studio.setSpeed(6);
    type("np 10\nnp 1 / 0");
    click(byText(".toolbar .btn", "Uruchom"));
    await tick(30);
    const text = document.querySelector(".console")!.textContent!;
    expect(text).toContain("Dzielenie przez zero");
    expect(text).toContain("Rysunek zachowano do miejsca błędu");
  });
});

describe("ui: keyboard shortcuts", () => {
  test("Ctrl+Enter runs, F10 and Ctrl+. step, Esc pauses, Alt+R resets", () => {
    const { app } = boot();
    app.workspace.studio.setSpeed(1);
    type("powtorz 50 [np 1 pw 1]");
    key(editorEl(), { key: "Enter", ctrlKey: true });
    expect(app.workspace.studio.state.status).toBe("running");
    key(editorEl(), { key: "Escape" });
    expect(app.workspace.studio.state.status).toBe("paused");
    key(document.body, { key: "F10" });
    expect(app.workspace.studio.state.status).toBe("paused");
    key(document.body, { key: ".", ctrlKey: true });
    expect(app.workspace.studio.state.status).toBe("paused");
