import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { buildPermalink } from "../src/share/permalink";
import { installDom } from "./dom-env";
import { MemoryStorage } from "./fakes";

let teardown: () => void;
let App: typeof import("../src/app/app").App;

beforeAll(async () => {
  teardown = installDom();
  ({ App } = await import("../src/app/app"));
});
afterAll(() => teardown());

class ManualSystem {
  dark = false;
  private l = new Set<() => void>();
  get matchesDark() {
    return this.dark;
  }
  onChange(fn: () => void) {
    this.l.add(fn);
    return () => this.l.delete(fn);
  }
  flip(v: boolean) {
    this.dark = v;
    this.l.forEach((f) => f());
  }
}

function boot(options: { storage?: MemoryStorage; hash?: string; system?: ManualSystem } = {}) {
  document.body.innerHTML = '<div id="app"></div>';
  document.documentElement.setAttribute("data-theme", "light");
  const storage = options.storage ?? new MemoryStorage();
  const system = options.system ?? new ManualSystem();
  window.history.replaceState(null, "", `/app/${options.hash ?? "#/"}`);
  const app = new App({ root: document.getElementById("app")!, storage, system });
  app.start();
  return { app, storage, system };
}

const byText = (selector: string, text: string) =>
  [...document.querySelectorAll<HTMLElement>(selector)].find((el) => el.textContent?.trim() === text || el.getAttribute("aria-label") === text);
const click = (el: Element | null | undefined) => {
  expect(el).toBeTruthy();
  el!.dispatchEvent(new window.MouseEvent("click", { bubbles: true, cancelable: true }));
};
const key = (target: EventTarget, init: KeyboardEventInit) =>
  target.dispatchEvent(new window.KeyboardEvent("keydown", { bubbles: true, cancelable: true, ...init }));
const tick = (ms = 10) => new Promise((r) => setTimeout(r, ms));
const editorEl = () => document.querySelector<HTMLTextAreaElement>(".editor-input")!;
const type = (text: string) => {
  editorEl().value = text;
  editorEl().dispatchEvent(new window.Event("input", { bubbles: true }));
};

