describe("ui: accessibility sweep", () => {
  const pages = ["#/", "#/przyklady", "#/wyzwania", "#/wyzwania/kwadrat", "#/opis"];

  test("every button, link, input and select has an accessible name", async () => {
    boot();
    for (const hash of pages) {
      window.location.hash = hash;
      window.dispatchEvent(new window.HashChangeEvent("hashchange"));
      await tick();
      const visible = (el: Element) => !el.closest("[hidden]");
      for (const el of document.querySelectorAll("button, a[href], input, select, textarea")) {
        if (!visible(el)) continue;
        const name =
          el.getAttribute("aria-label") ||
          el.getAttribute("title") ||
          (el.id && document.querySelector(`label[for="${el.id}"]`)?.textContent) ||
          el.closest("label")?.textContent ||
          el.textContent?.trim();
        if (!name) throw new Error(`${hash}: ${el.outerHTML.slice(0, 120)} has no accessible name`);
      }
    }
  });

  test("canvases are labelled, dialogs are labelled, the document language is Polish, and there is exactly one h1 per page", async () => {
    boot();
    for (const hash of pages) {
      window.location.hash = hash;
      window.dispatchEvent(new window.HashChangeEvent("hashchange"));
      await tick();
      const h1s = [...document.querySelectorAll("h1")].filter((h) => !h.closest("[hidden]"));
      expect(h1s).toHaveLength(1);
      for (const canvas of document.querySelectorAll("canvas")) {
        expect(canvas.getAttribute("role")).toBe("img");
        expect(canvas.getAttribute("aria-label")).toBeTruthy();
      }
    }
    key(document.body, { key: "/", ctrlKey: true });
    expect(document.querySelector("dialog[open]")!.getAttribute("aria-labelledby")).toBeTruthy();
  });

  test("the editor is a labelled textarea described by the console", () => {
    boot();
    const area = editorEl();
    expect(area.getAttribute("aria-label")).toBe("Program w Logo");
    const describedBy = area.getAttribute("aria-describedby")!;
    expect(document.getElementById(describedBy)?.getAttribute("aria-live")).toBe("polite");
  });

  test("icon-only buttons say what they do; the live regions exist", () => {
    boot();
    for (const label of ["Oddal", "Przybliż", "Dopasuj widok do rysunku", "Przywróć domyślny widok", "Zapisz rysunek jako PNG", "Skróty klawiszowe"]) {
      expect(byText("button", label), label).toBeTruthy();
    }
    expect(document.querySelector('.toasts[role="status"]')).toBeTruthy();
  });

  test("the main navigation marks the current page", async () => {
    boot();
    window.location.hash = "#/wyzwania";
    window.dispatchEvent(new window.HashChangeEvent("hashchange"));
    await tick();
    const current = [...document.querySelectorAll('.topnav a[aria-current="page"]')].map((a) => a.textContent);
    expect(current).toEqual(["Wyzwania"]);
    expect(document.title).toBe("Wyzwania – Logomocja");
  });
});
