  "nrpowt","x","y","f","g","[","]","(",")","+","-","*","/","<",">","=","<=","<>",",",":x","\"#16866a\"","\"#zzz\"","1","2","0","10","90","360","0.5",".5","1e3",";c\n","\n","  ","\t","@","🐢","12abc"];
