cat > /tmp/fuzz2.ts <<'EOF'
import { run } from "/work/src/lang";
const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)]!;
const rnd = (n: number) => Math.floor(Math.random() * n);
function expr(depth: number, inRepeat: boolean, names: string[]): string {
  const r = Math.random();
  if (depth <= 0 || r < 0.4) return pick([String(rnd(100)), "0.5", ".25", ...(names.length ? names : ["7"]), ...(inRepeat ? ["nrpowt"] : [])]);
  if (r < 0.55) return `(${expr(depth - 1, inRepeat, names)})`;
  if (r < 0.65) return `-${expr(depth - 1, inRepeat, names)}`;
  return `${expr(depth - 1, inRepeat, names)} ${pick(["+", "-", "*"])} ${expr(depth - 1, inRepeat, names)}`;
}
function stmts(depth: number, inRepeat: boolean, names: string[], procs: string[]): string {
  const out: string[] = [];
  for (let i = 0; i < 1 + rnd(4); i++) {
    const r = Math.random();
    if (r < 0.3) out.push(`${pick(["np", "ws", "pw", "lw"])} ${expr(2, inRepeat, names)}`);
    else if (r < 0.4) out.push(pick(["pod", "opu", "dom", "czyść"]));
    else if (r < 0.47) out.push(`kolor "#${(rnd(0xffffff) | 0).toString(16).padStart(6, "0")}"`);
    else if (r < 0.52) out.push(`grubosc ${1 + rnd(12)}`);
    else if (r < 0.6 && depth > 0) out.push(`powtorz ${rnd(5)} [${stmts(depth - 1, true, names, procs)}]`);
    else if (r < 0.68 && depth > 0) out.push(`jeśli ${expr(1, inRepeat, names)} ${pick(["<", ">", "=", "<>"])} ${expr(1, inRepeat, names)} [${stmts(depth - 1, inRepeat, names, procs)}]`);
    else if (r < 0.74 && depth > 0) out.push(`jeżeli ${expr(1, inRepeat, names)} < ${expr(1, inRepeat, names)} [${stmts(depth - 1, inRepeat, names, procs)}] [${stmts(depth - 1, inRepeat, names, procs)}]`);
    else if (r < 0.8) out.push(`niech ${pick(["a", "b"])} ${expr(2, inRepeat, names)}`);
    else if (r < 0.86 && procs.length) out.push(`${pick(procs)} ${expr(1, inRepeat, names)}`);
    else if (r < 0.88) out.push("stop");
    else out.push(`np ${rnd(50)}`);
  }
  return out.join(" ");
}
let thrown = 0, diff = 0, ok = 0, errs: Record<string, number> = {};
for (let i = 0; i < 30000; i++) {
  const withProc = Math.random() < 0.5;
  const header = withProc ? `oto p ma: n\n  niech a 1\n  ${stmts(2, false, ["n", "a", "b"], [])}\njuż\n` : "";
  const body = `niech a 3\nniech b 4\n${stmts(3, false, ["a", "b"], withProc ? ["p"] : [])}`;
  const src = header + body;
  try {
    const r2 = run(src, "2d"), r3 = run(src, "3d");
    if (JSON.stringify(r2) !== JSON.stringify(r3)) { diff++; if (diff < 3) console.log("2D/3D DIFFER", JSON.stringify(src)); }
    if (r2.error) errs[r2.error.message.replace(/„[^”]*”/g, "„”").slice(0, 50)] = (errs[r2.error.message.replace(/„[^”]*”/g, "„”").slice(0, 50)] ?? 0) + 1; else ok++;
  } catch (e) { thrown++; if (thrown < 4) console.log("THROWN", JSON.stringify(src), String(e).slice(0, 120)); }
}
console.log({ thrown, diff, ok }); console.log(errs);
EOF
bun /tmp/fuzz2.ts

