describe("studio: long programs do not animate forever at fast speeds", () => {
  const LONG = "powtorz 1500 [np 1 pw 1]"; // 1 + 1500 * 2 = 3001 statements

  test("at the fast levels the whole run takes at most about three seconds, however long the program", () => {
    for (const speed of [4, 5]) {
      const { studio, scheduler } = newStudio(LONG);
      studio.setSpeed(speed);
      studio.run();
      for (let t = 0; t < 3300; t += 16) scheduler.frame(16);
      expect(studio.state.status).toBe("finished");
    }
  });

  test("the slow levels are left alone: watching closely is the point", () => {
    const { studio, scheduler } = newStudio(LONG);
    studio.setSpeed(3);
    studio.run();
    for (let t = 0; t < 3300; t += 16) scheduler.frame(16);
    expect(studio.state.status).toBe("running");
  });

  test("short programs keep the speed the user chose", () => {
    const slow = newStudio("np 1 np 1 np 1 np 1 np 1 np 1");
    slow.studio.setSpeed(4);
    slow.studio.run();
    slow.scheduler.frame(16);
    expect(slow.studio.state.status).toBe("running"); // 6 statements at 150/s need 40ms
    slow.scheduler.settle();
    expect(slow.studio.state.status).toBe("finished");
  });
});
EOF
