describe("ui: ARIA patterns are complete, not half-built", () => {
  test("the Kod/Rysunek switch is a labelled group of toggle buttons, not a tab strip without panels", () => {
    boot();
    expect(document.querySelector('[role="tablist"], [role="tab"]')).toBeNull();
    const group = document.querySelector('[role="group"][aria-label="Widok"]')!;
    const buttons = [...group.querySelectorAll("button")];
    expect(buttons.map((b) => b.textContent)).toEqual(["Kod", "Rysunek"]);
    expect(buttons.map((b) => b.getAttribute("aria-pressed"))).toEqual(["true", "false"]);
    click(buttons[1]);
    expect(buttons.map((b) => b.getAttribute("aria-pressed"))).toEqual(["false", "true"]);
    expect(document.querySelector(".panes")!.getAttribute("data-pane")).toBe("draw");
  });

  test("the drawing viewport is a labelled group, and roledescription is never used without a role", () => {
    boot();
    const viewport = document.querySelector(".canvas-wrap .viewport")!;
    expect(viewport.getAttribute("role")).toBe("group");
    expect(viewport.getAttribute("aria-label")).toBeTruthy();
    for (const el of document.querySelectorAll("[aria-roledescription]")) expect(el.getAttribute("role")).toBeTruthy();
  });

  test("the turtle readout is a labelled group of name/value cells", () => {
    boot();
    const readout = document.querySelector(".readout")!;
    expect(readout.getAttribute("role")).toBe("group");
    expect(readout.getAttribute("aria-label")).toBe("Położenie żółwia");
    expect(readout.querySelector("dt, dd")).toBeNull();
    expect([...readout.querySelectorAll(".readout-name")].map((n) => n.textContent)).toEqual(["x", "y", "kierunek", "pióro"]);
  });
});
EOF
