    expect(viewport.getAttribute("aria-label")).toBeTruthy();
    for (const el of document.querySelectorAll("[aria-roledescription]")) expect(el.getAttribute("role")).toBeTruthy();
  });

  test("the turtle readout is a labelled group of name/value cells", () => {
    boot();
    const readout = document.querySelector(".readout")!;
