// sRGB hex <-> OKLCH, then an 8-step ramp (L 0.18..0.95) at the colour's hue, chroma reduced until in gamut.
const toLin = (v: number) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
const fromLin = (v: number) => (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055);
function hexToOklch(hex: string): [number, number, number] {
  const [r, g, b] = [1, 3, 5].map((i) => toLin(parseInt(hex.slice(i, i + 2), 16) / 255)) as [number, number, number];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bb = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return [L, Math.hypot(a, bb), (Math.atan2(bb, a) * 180) / Math.PI];
}
function oklchToHex(L: number, C: number, H: number): string | null {
  const a = C * Math.cos((H * Math.PI) / 180), b = C * Math.sin((H * Math.PI) / 180);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3, m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3, s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const rgb = [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s];
  if (rgb.some((v) => v < -0.0005 || v > 1.0005)) return null;
  return "#" + rgb.map((v) => Math.round(Math.min(1, Math.max(0, fromLin(Math.min(1, Math.max(0, v))))) * 255).toString(16).padStart(2, "0")).join("");
}
export function ramp(hex: string): { canonical: string; tonalRamp: string[] } {
  const [L, C, H] = hexToOklch(hex);
  const steps = Array.from({ length: 8 }, (_, i) => 0.18 + (0.95 - 0.18) * (i / 7));
  const tonalRamp = steps.map((l) => { for (let c = C; c >= 0; c -= C / 40) { const h = oklchToHex(l, c, H); if (h) return h; } return oklchToHex(l, 0, H)!; });
  return { canonical: `oklch(${(L * 100).toFixed(1)}% ${C.toFixed(3)} ${H.toFixed(1)})`, tonalRamp };
}
const colors: Record<string, string> = { "sign-blue": "#12468e", "signal-yellow": "#ffd21f", "turtle-green": "#0e6a53", "tourist-brown": "#7a4a22", "stop-red": "#b3122b", "route-purple": "#8a3ab9", "copper": "#c1763d", "asphalt-ink": "#121c2a", "cool-paper": "#f2f5f9" };
const out: Record<string, unknown> = {};
for (const [k, v] of Object.entries(colors)) out[k] = ramp(v);
console.log(JSON.stringify(out, null, 1));
