cat > tests/css-logic.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { installDom } from "./dom-env";

/**
 * Layout cannot be rendered here, but the CSS cascade can be evaluated: these tests check the rules whose
 * logic matters (what is shown at which width, [hidden], and the metrics the editor overlay depends on).
 */
let teardown: () => void;
beforeAll(() => {
  teardown = installDom();
});
afterAll(() => teardown());

const CSS = ["tokens", "base", "components", "shell", "editor", "workspace", "pages"]
  .map((name) => readFileSync(`${import.meta.dir}/../src/styles/${name}.css`, "utf8"))
  .join("\n");

/** A fresh document at the given width, with the markup the app produces for the parts under test. */
function page(width: number, html: string, theme = "light") {
  (window as unknown as { happyDOM: { setViewport(v: { width: number; height: number }): void } }).happyDOM.setViewport({ width, height: 900 });
  document.documentElement.setAttribute("data-theme", theme);
  document.head.innerHTML = `<style>${CSS}</style>`;
  document.body.innerHTML = html;
  const style = (selector: string, property: string) => getComputedStyle(document.querySelector(selector)!).getPropertyValue(property);
  return { style, display: (selector: string) => style(selector, "display") };
}

const SHELL = `
  <nav class="topnav"></nav><nav class="bottomnav"></nav>
  <div class="toolbar"><button class="btn"><span class="btn-label">Krok</span></button><button class="btn btn--collapse"><span class="btn-label">Udostępnij</span></button><span class="menu"><button class="btn menu-trigger"><span class="btn-label">Plik</span></button></span></div>
  <div class="pane-tabs"></div>
  <div class="panes" data-pane="code"><section class="pane pane--code"><div class="route is-empty"></div></section><section class="pane pane--canvas"><span class="speed-text"></span></section></div>`;

describe("css: what is shown at which width", () => {
  test("phone (390px): bottom navigation, one pane behind a switch, icon-only toolbar, no empty route", () => {
    const p = page(390, SHELL);
    expect(p.display(".topnav")).toBe("none");
    expect(p.display(".bottomnav")).toBe("block");
    expect(p.display(".pane-tabs")).toBe("flex");
    expect(p.display(".pane--canvas")).toBe("none");
    expect(p.display(".pane--code")).toBe("flex");
    expect(p.display(".toolbar .btn-label")).toBe("none");
    expect(p.display(".btn--collapse")).toBe("none");
    expect(p.display(".route.is-empty")).toBe("none");
    expect(p.display(".speed-text")).toBe("none");
  });

  test("tablet (800px): top navigation, still one pane at a time", () => {
    const p = page(800, SHELL);
    expect(p.display(".topnav")).toBe("block");
    expect(p.display(".bottomnav")).toBe("none");
    expect(p.display(".pane-tabs")).toBe("flex");
    expect(p.display(".pane--canvas")).toBe("none");
    expect(p.display(".toolbar .btn-label")).not.toBe("none");
  });

  test("desktop (1440px): both panes side by side, no pane switch, labelled buttons", () => {
    const p = page(1440, SHELL);
    expect(p.display(".pane-tabs")).toBe("none");
    expect(p.display(".pane--canvas")).toBe("flex");
    expect(p.display(".pane--code")).toBe("flex");
    expect(p.style(".panes", "grid-template-columns")).toContain("minmax(340px, 42%)");
    expect(p.display(".btn--collapse")).not.toBe("none");
    expect(p.display(".speed-text")).not.toBe("none");
  });

  test("the menu button keeps its icon but drops its label on a phone", () => {
    expect(page(390, SHELL).display(".menu-trigger .btn-label")).toBe("none");
    expect(page(1440, SHELL).display(".menu-trigger .btn-label")).not.toBe("none");
  });
});

describe("css: the [hidden] attribute always wins", () => {
  test("elements whose class sets a display are still hidden", () => {
    const p = page(
      1440,
      `<div class="segmented" hidden></div><ol class="route-list" hidden></ol><section class="challenge-bar" hidden></section><p class="canvas-hint" hidden></p><span class="tools-group" hidden></span><div class="card" hidden></div><section class="page" hidden></section>`,
    );
    for (const selector of [".segmented", ".route-list", ".challenge-bar", ".canvas-hint", ".tools-group", ".card", ".page"]) {
      expect(p.display(selector), selector).toBe("none");
    }
  });
});

describe("css: the editor overlay and the textarea share identical text metrics", () => {
  const EDITOR = `<div class="editor"><div class="editor-viewport"><div class="editor-layers"><div class="editor-code"><div class="line">np 1</div></div></div><textarea class="editor-input"></textarea></div></div>`;

  test.each([1440, 390])("at %ipx the layer and the textarea agree on font, size, line height, tabs and padding", (width) => {
    const p = page(width, EDITOR);
    for (const property of ["font-family", "font-size", "line-height", "letter-spacing", "tab-size", "white-space", "padding-top", "padding-left", "padding-right", "font-variant-ligatures"]) {
      const layer = p.style(".editor-code", property);
      const area = p.style(".editor-input", property);
      expect(`${property}: ${layer}`).toBe(`${property}: ${area}`);
    }
  });

  test("the line height is a fixed pixel value shared with the gutter", () => {
    expect(page(1440, EDITOR).style(".editor", "line-height")).toBe("var(--lh)");
  });

  test("the textarea text is invisible while the caret stays visible", () => {
    const p = page(1440, EDITOR);
    expect(p.style(".editor-input", "color")).toBe("transparent");
    expect(p.style(".editor-input", "caret-color")).not.toBe("transparent");
  });
});

describe("css: both themes define every colour the components use", () => {
  test("each custom property used in the stylesheets is defined for light and dark", () => {
    const used = new Set([...CSS.matchAll(/var\((--[\w-]+)/g)].map((m) => m[1]!));
    const light = CSS.slice(CSS.indexOf(":root"), CSS.indexOf('[data-theme="dark"]'));
    const dark = CSS.slice(CSS.indexOf('[data-theme="dark"] {'), CSS.indexOf("@media (pointer: coarse)"));
    const swatch = (css: string) => new Set([...css.matchAll(/(--[\w-]+)\s*:/g)].map((m) => m[1]!));
    const definedLight = swatch(light);
    const dynamic = new Set(["--lh", "--pad-x", "--pad-y", "--gutter-digits", "--swatch", "--plate-bg", "--plate-fg", "--plate-key"]);
    const missing = [...used].filter((v) => !definedLight.has(v) && !dynamic.has(v));
    expect(missing).toEqual([]);
    // every light colour token that matters for contrast is redefined (or intentionally shared) in dark
    const shared = new Set(["--font-ui", "--font-plate", "--font-code", "--fs-xs", "--fs-sm", "--fs-md", "--fs-lg", "--fs-xl", "--fs-2xl", "--s-1", "--s-2", "--s-3", "--s-4", "--s-5", "--s-6", "--s-7", "--r-sm", "--r-md", "--r-lg", "--header-h", "--control-h", "--ease", "--t-fast", "--t-med", "--on-header", "--nav-current-bg", "--nav-current-fg", "--on-blue-btn", "--yellow", "--on-yellow"]);
    const notDark = [...definedLight].filter((v) => !swatch(dark).has(v) && !shared.has(v));
    expect(notDark).toEqual([]);
  });

  test("the dark theme really changes the ground and the ink", () => {
    const light = page(1440, `<p class="muted"></p>`, "light");
    const lightInk = light.style(".muted", "color");
    const dark = page(1440, `<p class="muted"></p>`, "dark");
    expect(dark.style(".muted", "color")).not.toBe(lightInk);
  });
});
EOF
bun test tests/css-logic.test.ts 2>&1 | grep -E "^\(fail\)|pass$|fail$|error:|Expected|Received|^[-+] " | head -40

