describe("css + app together, in the real DOM", () => {
  async function boot(width: number, hash = "#/") {
    const { App } = await import("../src/app/app");
    const { MemoryStorage } = await import("./fakes");
    (window as unknown as { happyDOM: { setViewport(v: { width: number; height: number }): void } }).happyDOM.setViewport({ width, height: 900 });
    document.documentElement.setAttribute("data-theme", "light");
    document.head.innerHTML = `<style>${CSS}</style>`;
    document.body.innerHTML = '<div id="app"></div>';
    window.history.replaceState(null, "", `/app/${hash}`);
    const app = new App({ root: document.getElementById("app")!, storage: new MemoryStorage(), system: null });
    app.start();
    await new Promise((r) => setTimeout(r, 20));
    return app;
  }
  const display = (selector: string) => getComputedStyle(document.querySelector(selector)!).display;
  const click = (selector: string, text: string) =>
    [...document.querySelectorAll<HTMLElement>(selector)].find((e) => e.textContent!.trim() === text)!.dispatchEvent(new window.MouseEvent("click", { bubbles: true }));

  test("on a phone only one pane shows, and the Kod/Rysunek switch swaps them", async () => {
    await boot(390);
    expect(display(".pane--code")).toBe("flex");
    expect(display(".pane--canvas")).toBe("none");
    click(".pane-tabs .tab", "Rysunek");
    expect(display(".pane--code")).toBe("none");
    expect(display(".pane--canvas")).toBe("flex");
    click(".pane-tabs .tab", "Kod");
    expect(display(".pane--code")).toBe("flex");
  });

  test("on a desktop both panes show and the switch is gone", async () => {
    await boot(1440);
    expect(display(".pane--code")).toBe("flex");
    expect(display(".pane--canvas")).toBe("flex");
    expect(display(".pane-tabs")).toBe("none");
  });

  test("inside a challenge the 2D/3D switch and the 3D tools are really hidden, and the brief really shows", async () => {
    await boot(1440, "#/wyzwania/kwadrat");
    expect(display(".segmented[aria-label='Tryb rysowania']")).toBe("none");
    expect(display(".challenge-bar")).not.toBe("none");
    expect(display(".tools-group")).toBe("none");
  });

  test("the Trasa strip appears only when something is running (and always on a desktop)", async () => {
    await boot(390);
    expect(display(".route")).toBe("none");
    click(".toolbar .btn", "Krok");
    click(".toolbar .btn", "Krok");
    expect(display(".route")).toBe("flex");
    await boot(1440);
    expect(display(".route")).toBe("flex");
  });

  test("pages other than the workspace hide it entirely", async () => {
    await boot(1440, "#/przyklady");
    expect(display(".page--workspace")).toBe("none");
    expect(display(".page--list")).not.toBe("none");
  });
});
EOF
