describe("ui: the editor's keyboard behaviour", () => {
  const press = (init: KeyboardEventInit) => {
    const event = new window.KeyboardEvent("keydown", { bubbles: true, cancelable: true, ...init });
    editorEl().dispatchEvent(event);
    return event;
  };
  const caretAt = (offset: number, end = offset) => editorEl().setSelectionRange(offset, end);

  test("Enter keeps the indentation of the line, and adds two spaces after an opening bracket or a procedure header", () => {
    boot();
    type("powtorz 4 [");
    caretAt(11);
    expect(press({ key: "Enter" }).defaultPrevented).toBe(true);
    expect(editorEl().value).toBe("powtorz 4 [\n  ");
    type("  np 10");
    caretAt(7);
    press({ key: "Enter" });
    expect(editorEl().value).toBe("  np 10\n  ");
    type("oto kwadrat ma: bok");
    caretAt(19);
    press({ key: "Enter" });
    expect(editorEl().value).toBe("oto kwadrat ma: bok\n  ");
  });

  test("Enter in the middle of a line splits it and keeps the rest", () => {
    boot();
    type("np 10 pw 90");
    caretAt(5);
    press({ key: "Enter" });
    expect(editorEl().value).toBe("np 10\n pw 90".replace("\n ", "\n"));
  });

  test("Tab inserts two spaces, Shift+Tab takes them back, a selection of several lines is indented together", () => {
    boot();
    type("np 1");
    caretAt(0);
    expect(press({ key: "Tab" }).defaultPrevented).toBe(true);
    expect(editorEl().value).toBe("  np 1");
    caretAt(2);
    press({ key: "Tab", shiftKey: true });
    expect(editorEl().value).toBe("np 1");

    type("np 1\nnp 2\nnp 3");
    caretAt(0, 9);
    press({ key: "Tab" });
    expect(editorEl().value).toBe("  np 1\n  np 2\nnp 3");
    caretAt(0, editorEl().value.indexOf("np 3") - 1);
    press({ key: "Tab", shiftKey: true });
    expect(editorEl().value).toBe("np 1\nnp 2\nnp 3");
  });

  test("Escape, then Tab, leaves the editor instead of indenting (so the keyboard is never trapped)", () => {
    boot();
    type("np 1");
    press({ key: "Escape" });
    const tab = press({ key: "Tab" });
    expect(tab.defaultPrevented).toBe(false);
    expect(editorEl().value).toBe("np 1");
    expect(press({ key: "Tab" }).defaultPrevented).toBe(true); // the escape was one-shot
  });

  test("Enter with Ctrl runs the program instead of typing a newline; composition is left alone", () => {
    boot();
    type("np 1");
    caretAt(4);
    expect(press({ key: "Enter", ctrlKey: true }).defaultPrevented).toBe(true);
    expect(editorEl().value).toBe("np 1");
    expect(press({ key: "Enter", isComposing: true }).defaultPrevented).toBe(false);
  });

  test("every edit reaches the workspace, so the draft is saved", () => {
    const { app } = boot();
    type("np 1");
    caretAt(4);
    press({ key: "Enter" });
    expect(app.workspace.drafts.loadDraft("2d")).toBe("np 1\n");
  });
});
EOF
