cat > tests/viewport.test.ts <<'EOF'
import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { installDom } from "./dom-env";

let teardown: () => void;
let Viewport: typeof import("../src/view/viewport").Viewport;
let run: typeof import("../src/lang").run;

/** A canvas context that records the path it is asked to draw. */
class RecordingContext {
  strokes: [number, number, number, number][] = [];
  private current: [number, number][] = [];
  fills: string[] = [];
  fillStyle = "";
  strokeStyle = "";
  lineWidth = 1;
  moveTo(x: number, y: number) {
    this.current.push([x, y]);
  }
  lineTo(x: number, y: number) {
    const from = this.current[this.current.length - 1] ?? [x, y];
    this.strokes.push([from[0], from[1], x, y]);
    this.current.push([x, y]);
  }
  beginPath() {
    this.current = [];
  }
  setTransform() {}
  setLineDash() {}
  fillRect() {}
  fill() {}
  stroke() {}
  arc() {}
  save() {}
  restore() {}
  closePath() {}
  translate() {}
  rotate() {}
  fillText() {}
  strokeText() {}
  measureText() {
    return { width: 0 };
  }
}

let context: RecordingContext;

beforeAll(async () => {
  teardown = installDom();
  HTMLCanvasElement.prototype.getContext = function () {
    return context as unknown as CanvasRenderingContext2D;
  } as never;
  ({ Viewport } = await import("../src/view/viewport"));
  ({ run } = await import("../src/lang"));
});
afterAll(() => teardown());
beforeEach(() => {
  context = new RecordingContext();
});

function make(mode: "2d" | "3d", source: string) {
  const viewport = new Viewport({ mode, theme: "light", interactive: true, decorations: false });
  document.body.appendChild(viewport.element);
  viewport.setScene({ segments: run(source, mode).segments });
  viewport.refresh();
  viewport.fit(true);
  return viewport;
}

/** The screen positions of the drawn segments' end points (the drawing only: no grid or axes are drawn here). */
function drawn(viewport: InstanceType<typeof Viewport>): [number, number][] {
  context.strokes = [];
  viewport.paintNow();
  return context.strokes.flatMap((s): [number, number][] => [[s[0], s[1]], [s[2], s[3]]]);
}

