import type { Comparison, Condition, Expr, Procedure, Program, Statement } from "./ast";
import { LangError } from "./errors";
import { LIMITS } from "./limits";
import { nameOf, tokenize, type Token } from "./lexer";
import { argumentOf, commandFor, isDefineWord, isEndWord, isRepcount, isReserved, isSpatial } from "./vocabulary";
import type { Mode } from "./types";

const COLOR_MESSAGE =
  'Niepoprawny kolor: oczekiwano sześciu cyfr szesnastkowych w cudzysłowie, np. "#16866a".';
const WIDTH_MESSAGE = "Grubość musi być liczbą całkowitą od 1 do 12.";
const REPEAT_MESSAGE = "Liczba powtórzeń musi być liczbą całkowitą od 0 do 10000.";

interface Scan {
  /** Parameter count of every procedure header found, by name (the first definition wins). */
  arity: Map<string, number>;
  /** Names assigned by `niech` at top level. */
  globals: Set<string>;
  /** Parameters and `niech` names of each procedure body, keyed by the index of its `oto` token. */
  locals: Map<number, Set<string>>;
}

/**
 * Looks through the tokens before parsing, tolerating errors, so that calls may precede
 * definitions and names may be assigned after their first use.
 */
function scan(tokens: Token[]): Scan {
  const result: Scan = { arity: new Map(), globals: new Set(), locals: new Map() };
  let current: Set<string> | null = null;
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i]!;
    if (token.kind !== "word") continue;
    if (isDefineWord(token.text) && token.startsLine && !current) {
      const params: string[] = [];
      let j = i + 2;
      for (; tokens[j] && tokens[j]!.line === token.line; j++) {
        const t = tokens[j]!;
        if (t.kind === "word" && !(j === i + 2 && nameOf(t.text) === "ma" && tokens[j + 1]?.kind === "colon")) {
          params.push(nameOf(t.text));
        }
      }
      const name = tokens[i + 1];
      if (name?.kind === "word" && name.line === token.line) {
        const key = nameOf(name.text);
        if (!result.arity.has(key)) result.arity.set(key, params.length);
      }
      current = new Set(params);
      result.locals.set(i, current);
      i = j - 1;
    } else if (isEndWord(token.text) && token.startsLine) {
      current = null;
    } else if (commandFor(token.text) === "let" && tokens[i + 1]?.kind === "word") {
      (current ?? result.globals).add(nameOf(tokens[i + 1]!.text));
    }
  }
  return result;
}

