  | "lparen"
  | "rparen"
  | "lbracket"
  | "rbracket"
  | "comma"
  | "colon";

export interface Token {
  kind: TokenKind;
  text: string;
  line: number;
  column: number;
  /** The first token on its line (comments do not count). */
  startsLine: boolean;
  /** Whitespace (or the start of the file) directly before the token. */
  spaceBefore: boolean;
  /** Whitespace, a comment or the end of the file directly after the token. */
  spaceAfter: boolean;
