const WORD_CHAR = /[\p{L}\p{M}\p{N}_]/u;

/** `ma:` may be written without a space before the first parameter: `ma:bok`. */
function followsMa(tokens: Token[], colonAt: number): boolean {
  const previous = tokens[tokens.length - 1];
  return (
    previous !== undefined &&
    previous.kind === "word" &&
    previous.text.toLowerCase() === "ma" &&
    !previous.spaceAfter &&
    colonAt > 0
  );
}

/** The case-insensitive identity of a name: `:Bok` and `bok` are the same. */
export function nameOf(text: string): string {
  return (text.startsWith(":") ? text.slice(1) : text).normalize("NFC").toLowerCase();
}
const NUMBER = /^(?:\d+(?:\.\d+)?|\.\d+)$/;
