  let lineStart = 0;
  let i = 0;
  const isSpace = (index: number) => index < 0 || index >= source.length || /[\s;]/.test(source[index]!);
  const push = (kind: TokenKind, start: number, end: number) => {
    tokens.push({
      kind,
      text: source.slice(start, end),
      line,
      column: start - lineStart + 1,
      startsLine: tokens.length === 0 || tokens[tokens.length - 1]!.line !== line,
      spaceBefore: isSpace(start - 1),
      spaceAfter: isSpace(end),
    });
  };
  while (i < source.length) {
    const ch = source[i]!;
    if (ch === "\n") {
      line++;
      i++;
      lineStart = i;
    } else if (/\s/.test(ch)) {
      i++;
    } else if (ch === ";") {
      while (i < source.length && source[i] !== "\n") i++;
    } else if (ch === '"') {
      const start = i++;
      while (i < source.length && source[i] !== '"' && source[i] !== "\n") i++;
      if (source[i] === '"') i++;
      push("string", start, i);
    } else if (ch === ",") {
      push("comma", i, i + 1);
      i++;
    } else if (ch === ":" && (!WORD_CHAR.test(source[i + 1] ?? "") || followsMa(tokens, i))) {
      push("colon", i, i + 1);
      i++;
    } else if ("<>=".includes(ch)) {
      const pair = source.slice(i, i + 2);
      const length = pair === "<=" || pair === ">=" || pair === "<>" ? 2 : 1;
      push("compare", i, i + length);
      i += length;
    } else if ("+-*/".includes(ch)) {
      push("op", i, i + 1);
      i++;
    } else if (ch === "(" || ch === ")") {
      push(ch === "(" ? "lparen" : "rparen", i, i + 1);
      i++;
    } else if (ch === "[" || ch === "]") {
      push(ch === "[" ? "lbracket" : "rbracket", i, i + 1);
      i++;
    } else if (/[\p{N}.]/u.test(ch)) {
      NUMBER_RUN.lastIndex = i;
      const run = NUMBER_RUN.exec(source)![0];
      push(NUMBER.test(run) ? "number" : "badnumber", i, i + run.length);
      i += run.length;
