  /** Counts one executed operation. */
  count(at: Token): void {
    if (++this.ops > LIMITS.operations) throw new LangError(MESSAGES.operations, at);
  }

  enterFrame(at: Token): void {
    if (this.depth >= LIMITS.frames) throw new LangError(MESSAGES.frames, at);
    this.depth++;
  }

  addSegment(from: Vec3, to: Vec3, at: Token): void {
    if (this.segments.length >= LIMITS.segments) throw new LangError(MESSAGES.segments, at);
    const segment = { from, to, color: this.color, width: this.width };
    this.segments.push(segment);
    this.added = segment;
  }
}

function evaluate(expr: Expr, m: Machine): number {
  switch (expr.type) {
    case "number":
      return expr.value;
    case "repcount":
      return m.frame.repeats[m.frame.repeats.length - 1]!.iteration;
    case "name": {
      const v = m.frame.locals.get(expr.name) ?? m.globals.get(expr.name);
      if (v === undefined) throw new Fault(`Zmienna „${expr.at.text.replace(/^:/, "")}” nie ma jeszcze wartości.`);
      return v;
    }
    case "group":
      return evaluate(expr.inner, m);
    case "unary":
      return expr.op === "-" ? -evaluate(expr.operand, m) : evaluate(expr.operand, m);
    case "binary": {
      // Walk the left spine iteratively: a chain of thousands of terms is left-deep.
      const spine: Extract<Expr, { type: "binary" }>[] = [];
      let node: Expr = expr;
      while (node.type === "binary") {
        spine.push(node);
        node = node.left;
      }
      let acc = evaluate(node, m);
      for (let i = spine.length - 1; i >= 0; i--) {
        const { op, right } = spine[i]!;
        const r = evaluate(right, m);
        if (op === "/" && r === 0) throw new Fault(MESSAGES.divisionByZero);
        acc = op === "+" ? acc + r : op === "-" ? acc - r : op === "*" ? acc * r : acc / r;
        if (!Number.isFinite(acc)) throw new Fault(MESSAGES.notFinite);
      }
      return acc;
    }
  }
}

/** Evaluates an argument; any fault is reported at the argument's first token. */
function value(expr: Expr, m: Machine): number {
  try {
    return evaluate(expr, m);
  } catch (e) {
    if (e instanceof Fault) throw new LangError(e.message, expr.at);
    throw e;
  }
}

function integerIn(n: number, min: number, max: number): boolean {
  return Number.isInteger(n) && n >= min && n <= max;
}

function checkCoordinates(position: Vec3, at: Token): void {
  if (position.some((c) => Math.abs(c) > LIMITS.coordinate)) {
    throw new LangError(MESSAGES.coordinate, at);
  }
}

function holds(op: string, l: number, r: number): boolean {
  switch (op) {
    case "<":
      return l < r;
    case ">":
      return l > r;
    case "=":
      return l === r;
    case "<=":
      return l <= r;
    case ">=":
      return l >= r;
    default:
      return l !== r;
  }
}

/** Runs statements; returns true when a `stop` ended the enclosing call (or the program). */
function* runBlock(body: Statement[], m: Machine): Generator<void, boolean> {
  for (const statement of body) {
    const at = statement.at;
    m.at = at;
    m.count(at);
    switch (statement.type) {
      case "repeat": {
        const times = value(statement.count, m);
        if (!integerIn(times, 0, 10_000)) throw new LangError(MESSAGES.repeat, statement.count.at);
        m.enterFrame(at);
        const repeats = m.frame.repeats;
        const state: RepeatState = { at, iteration: Math.min(1, times), total: times };
        repeats.push(state);
        yield;
        for (let i = 1; i <= times; i++) {
          state.iteration = i;
          if (yield* runBlock(statement.body, m)) return true;
          m.count(at);
        }
        repeats.pop();
        m.depth--;
        break;
      }
      case "call": {
        const procedure = m.program.procedures.get(statement.name)!;
        const locals = new Map<string, number>();
        const args = statement.args.map((arg) => value(arg, m));
        procedure.params.forEach((param, i) => locals.set(param, args[i]!));
        const depth = m.depth;
        m.enterFrame(at);
        m.frames.push({ locals, repeats: [], call: { name: procedure.displayName, args, at } });
        yield;
        yield* runBlock(procedure.body, m);
        m.frames.pop();
        m.depth = depth;
        m.count(at);
        break;
      }
      case "if": {
        const { op, left, right } = statement.condition;
        const taken = holds(op, value(left, m), value(right, m));
        yield;
        const branch = taken ? statement.then : statement.otherwise;
        if (branch) {
          if (yield* runBlock(branch, m)) return true;
          m.count(at);
        }
        break;
      }
      case "let":
        m.frame.locals.set(statement.name, value(statement.value, m));

