describe("ui: the console follows the stepping", () => {
  test("while paused it names the line that was executed last, and updates on every step", () => {
    boot();
    type("np 10\npw 90\nnp 20");
    click(byText(".toolbar .btn", "Krok"));
    expect(document.querySelector(".console")!.textContent).toContain("wiersz: 1");
    click(byText(".toolbar .btn", "Krok"));
    expect(document.querySelector(".console")!.textContent).toContain("wiersz: 2");
    click(byText(".toolbar .btn", "Krok"));
    expect(document.querySelector(".console")!.textContent).toContain("wiersz: 3");
  });
});
EOF
