input.command:
cat >> tests/ui.test.ts <<'EOF'

describe("ui: moving the executing-line band is cheap", () => {
  test("changing the current line does not rebuild the coloured layer", async () => {
    const { app } = boot();
    type("np 1\nnp 2\nnp 3");
    await tick(30);
    const before = [...document.querySelectorAll(".editor-code .line")];
    app.workspace.studio.step();
    await tick(30);
    const after = [...document.querySelectorAll(".editor-code .line")];
    expect(after.length).toBe(before.length);
    expect(after.every((el, i) => el === before[i])).toBe(true); // the same nodes, only classes moved
    expect(after[0]!.classList.contains("is-current")).toBe(true);
    app.workspace.studio.step();
    await tick(30);
    expect(after[0]!.classList.contains("is-current")).toBe(false);
    expect(after[1]!.classList.contains("is-current")).toBe(true);
    expect([...document.querySelectorAll(".gutter-line.is-current")].map((g) => g.textContent)).toEqual(["2"]);
  });

  test("typing still re-colours, and the band survives the re-colouring", async () => {
    const { app } = boot();
    type("np 1\nnp 2");
    app.workspace.studio.step();
    await tick(30);
    type("np 1\nnp 22");
    await tick(30);
    expect(app.workspace.studio.state.currentLine).toBeNull(); // editing stops the run
    expect(document.querySelector(".editor-code .line.is-current")).toBeNull();
  });
});
EOF
