input.command:
cat >> tests/ui.test.ts <<'EOF'

describe("ui: sharing is one click when the clipboard works", () => {
  function withClipboard(writeText: (text: string) => Promise<void>) {
    Object.defineProperty(window.navigator, "clipboard", { value: { writeText }, configurable: true });
  }
  afterAll(() => {
    Object.defineProperty(window.navigator, "clipboard", { value: undefined, configurable: true });
  });

  test("Udostępnij copies the link at once and says so, without opening a dialog", async () => {
    const copied: string[] = [];
    withClipboard(async (text) => void copied.push(text));
    boot();
    type("np 42 ; do udostępnienia");
    click(byText(".toolbar .btn", "Udostępnij"));
    await tick();
    expect(found(document.querySelector("dialog[open]"))).toBe(false);
    expect(copied).toHaveLength(1);
    expect(copied[0]).toContain("#/p/2d/");
    expect(document.querySelector(".toasts")!.textContent).toContain("skopiowany");
  });

  test("the toast offers to show the address, and the dialog then holds the same link", async () => {
    const copied: string[] = [];
    withClipboard(async (text) => void copied.push(text));
    boot();
    click(byText(".toolbar .btn", "Udostępnij"));
    await tick();
    click(byText(".toast .btn", "Pokaż adres"));
    const input = document.querySelector<HTMLInputElement>("dialog[open] input")!;
    expect(input.value).toBe(copied[0]!);
    click(byText("dialog[open] .btn", "Zamknij"));
  });

  test("when the browser refuses the clipboard, the dialog opens so the address can be copied by hand", async () => {
    withClipboard(async () => {
      throw new Error("denied");
    });
    boot();
    click(byText(".toolbar .btn", "Udostępnij"));
    await tick();
    expect(found(document.querySelector("dialog[open] input"))).toBe(true);
    click(byText("dialog[open] .btn", "Zamknij"));
  });
});
EOF
bun test tests/ui.test.ts -t "one click when the clipboard" 2>&1 | grep -E "\(fail\)|\(pass\)|^ *[0-9]+ (pass|fail)" | head -6

