cat > tests/zz-fuzz-ui.test.ts <<'EOF'
import { afterAll, beforeAll, expect, test } from "bun:test";
import { installDom } from "./dom-env";
import { MemoryStorage } from "./fakes";
let teardown: () => void; let App: any;
beforeAll(async () => { teardown = installDom(); ({ App } = await import("../src/app/app")); });
afterAll(() => teardown());
const vocab = ["np","ws","pw","lw","pod","opu","kolor","grubosc","powtorz","niech","jeśli","jeżeli","stop","dom","czyść","gora","dol","pp","pl","oto","już","ma:","nrpowt","x","f","[","]","(",")","+","-","*","/","<",">","=",",",":x","\"#16866a\"","1","2","0","10","90","360","0.5","1e3",";c\n","\n","@","🐢"];
test("the app survives 400 random programs through open()", async () => {
  document.body.innerHTML = '<div id="app"></div>';
  const app = new App({ root: document.getElementById("app")!, storage: new MemoryStorage(), system: null });
  app.start();
  const hook = app.hook();
  let errors = 0;
  for (let i = 0; i < 400; i++) {
    const n = 1 + Math.floor(Math.random() * 20);
    const src = Array.from({ length: n }, () => vocab[Math.floor(Math.random() * vocab.length)]).join(Math.random() < 0.7 ? " " : "\n");
    const mode = Math.random() < 0.5 ? "2d" : "3d";
    const result = await hook.open(src, mode);
    if (result.error) errors++;
    const text = document.querySelector<HTMLTextAreaElement>(".editor-input")!.value;
    if (text !== src) throw new Error(`editor shows different text for ${JSON.stringify(src)}`);
    if (app.workspace.studio.state.segments.length !== result.segments.length) throw new Error("drawing differs from the result");
  }
  expect(errors).toBeGreaterThan(0);
}, 60000);
EOF
bun test tests/zz-fuzz-ui.test.ts 2>&1 | tail -4; rm tests/zz-fuzz-ui.test.ts

